// =====================================================================
//  anclc - The ANCL (AI-Native Computing Language) Bootstrap Compiler
//  Phase 0 bootstrap, written in C++ (a native systems language).
//
//  Pipeline:  .ancl source
//    -> Lexer/Tokenizer
//    -> Recursive-descent Parser  (Abstract Syntax Tree)
//    -> Semantic analysis         (slot/stack-frame layout)
//    -> Codegen                   (hand-encoded x86-64 machine code)
//    -> PE32+ writer              (native Windows .exe, kernel32 imports)
//
//  No external assembler or linker is used to produce the target .exe.
//  The emitted binary depends on no VM, interpreter, or C runtime.
//  See ../HELP.md and ../../02_ai_guide_pack/ANCL_AI_GUIDE.md.
// =====================================================================
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <cctype>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <memory>

using std::string;
using std::vector;
using u8  = uint8_t;
using u16 = uint16_t;
using u32 = uint32_t;
using u64 = uint64_t;
using i64t = int64_t;

static void fail(const string& msg) {
    fprintf(stderr, "anclc: error: %s\n", msg.c_str());
    exit(1);
}

// SC1 (self-correcting compiler): true ONLY under `anclc --fix`. The normal
// compile path never sets this, so its behavior stays byte-for-byte identical
// (and the anclc3==anclc4 self-host fixpoint is untouched).
static bool g_fixMode = false;

static bool slurpFile(const string& path, string& out){
    FILE* f=fopen(path.c_str(),"rb"); if(!f) return false;
    fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
    out.resize(n>0?(size_t)n:0);
    if(n>0){ size_t rd=fread(&out[0],1,n,f); out.resize(rd); }
    fclose(f); return true;
}
static string dirOf(const string& path){
    size_t s=path.find_last_of("/\\");
    return s==string::npos ? string("") : path.substr(0,s+1);
}
// Lexical canonicalization for the include-once KEY (never for file I/O: the
// joined path is what gets opened, so open behaviour is untouched). Import
// resolution is plain string concatenation, so the same file arrives as
// "core_lib/./x.ancl" from one importer and "core_lib/././x.ancl" from another,
// include-once misses, and the module is parsed TWICE -- every function and
// @DATA item in it lands in the binary twice. Measured across 186 corpus
// programs: 276 duplicated definitions, every one of them this. Collapses
// '\' to '/', drops '.' and empty segments, folds 'seg/..'. Purely lexical
// ('..' across a symlink would alias wrongly; the tree has none), and it must
// stay BYTE-IDENTICAL to imp_canon() in the self-hosted compiler.
static string canonPath(const string& p){
    string q; q.reserve(p.size());
    for (size_t i=0;i<p.size();i++) q.push_back(p[i]=='\\' ? '/' : p[i]);
    bool absRoot = !q.empty() && q[0]=='/';
    vector<string> out;
    size_t i=0, n=q.size();
    while (i<n){
        while (i<n && q[i]=='/') i++;
        size_t j=i; while (j<n && q[j]!='/') j++;
        if (j>i){
            string seg=q.substr(i,j-i);
            if (seg=="."){ }
            else if (seg==".."){
                // fold onto a real segment; keep '..' when there is nothing to
                // fold (leading ../..) or the top is a drive root ("C:")
                if (!out.empty() && out.back()!=".." && out.back().back()!=':') out.pop_back();
                else out.push_back(seg);
            } else out.push_back(seg);
        }
        i=j;
    }
    string r = absRoot ? string("/") : string("");
    for (size_t k=0;k<out.size();k++){ if (k) r+="/"; r+=out[k]; }
    return r;
}

// ---------------------------------------------------------------------
//  CONDITIONAL COMPILATION -- @if <target> / @else / @end
//
//  A deliberately dumb LINE filter, applied to every source text as it is
//  read, so it covers the root file and every import with one mechanism and
//  no parser involvement. It is what lets ONE source serve Windows, Linux and
//  bare metal -- previously the answer was a duplicate tree under Linux/,
//  which drifted out of step twice and had to be regenerated by hand.
//
//      @if linux
//      import "../core_lib/liblinux.ancl";
//      @else
//      import "../core_lib/win32_api.ancl";
//      @end
//
//  Recognised targets: windows, linux, bare. `linux` is true for both
//  --target=linux and --target=linux-dyn. A leading '!' negates: @if !windows.
//
//  âš  DISABLED LINES ARE BLANKED, NOT REMOVED. Every line the filter rejects
//  becomes an empty line, so line numbers are preserved exactly and the
//  file:line diagnostics built in lever B keep pointing at the real source.
//  Deleting the lines instead would silently mis-report every error below the
//  first conditional in the file.
//
//  Directives are recognised only when they are the entire (trimmed) line, so
//  an '@if' inside a string literal or a comment is untouched.
// ---------------------------------------------------------------------
static string g_condTarget = "windows";     // set from --target before any file is read

static bool condMatches(const string& want){
    bool neg = (!want.empty() && want[0]=='!');
    string t = neg ? want.substr(1) : want;
    bool v;
    if      (t=="windows") v = (g_condTarget=="windows");
    else if (t=="linux")   v = (g_condTarget=="linux");
    else if (t=="bare")    v = (g_condTarget=="bare");
    else { fprintf(stderr,"anclc: error: unknown @if target '%s' (want windows/linux/bare)\n", t.c_str()); exit(1); }
    return neg ? !v : v;
}

static string applyCond(const string& src, const string& path){
    // Fast path: no directive in the file at all -> byte-identical passthrough,
    // so every existing source keeps compiling to exactly the same bytes.
    if (src.find("@if") == string::npos && src.find("@else") == string::npos
        && src.find("@end") == string::npos) return src;
    string out; out.reserve(src.size());
    size_t i=0; int depth=0;
    // emitting[k] = is the region at nesting depth k+1 live?  taken[k] = has some
    // arm at that depth already been taken (so @else must not re-enable)?
    vector<char> emitting, taken;
    int lineNo=0;
    while (i<=src.size()){
        size_t e=src.find('\n', i);
        bool last=(e==string::npos);
        string line = src.substr(i, last? src.size()-i : e-i);
        lineNo++;
        string t=line;
        while(!t.empty() && (t.back()=='\r'||t.back()==' '||t.back()=='\t')) t.pop_back();
        size_t b=t.find_first_not_of(" \t");
        string body = (b==string::npos)? string("") : t.substr(b);
        bool isDirective=false;
        if (body.rfind("@if",0)==0 && (body.size()==3 || body[3]==' ' || body[3]=='\t')){
            string arg = body.size()>3 ? body.substr(4) : string("");
            size_t a=arg.find_first_not_of(" \t");
            arg = (a==string::npos)? string("") : arg.substr(a);
            size_t z=arg.find_first_of(" \t#");
            if (z!=string::npos) arg=arg.substr(0,z);
            if (arg.empty()){ fprintf(stderr,"anclc: error: %s:%d: @if needs a target\n",path.c_str(),lineNo); exit(1); }
            bool parentLive = emitting.empty() || emitting.back();
            bool v = parentLive && condMatches(arg);
            emitting.push_back(v?1:0); taken.push_back(v?1:0); depth++;
            isDirective=true;
        } else if (body=="@else"){
            if (depth==0){ fprintf(stderr,"anclc: error: %s:%d: @else without @if\n",path.c_str(),lineNo); exit(1); }
            bool parentLive = (depth<2) || emitting[depth-2];
            emitting[depth-1] = (parentLive && !taken[depth-1]) ? 1 : 0;
            if (emitting[depth-1]) taken[depth-1]=1;
            isDirective=true;
        } else if (body=="@end"){
            if (depth==0){ fprintf(stderr,"anclc: error: %s:%d: @end without @if\n",path.c_str(),lineNo); exit(1); }
            emitting.pop_back(); taken.pop_back(); depth--;
            isDirective=true;
        }
        bool live = emitting.empty() || emitting.back();
        // A directive line itself is always blanked; a dead line is blanked too.
        if (!isDirective && live) out += line;
        if (!last) out += '\n';
        if (last) break;
        i=e+1;
    }
    if (depth!=0){ fprintf(stderr,"anclc: error: %s: %d unterminated @if (missing @end)\n",path.c_str(),depth); exit(1); }
    return out;
}

// ---------------------------------------------------------------------
// 1. LEXER
// ---------------------------------------------------------------------
enum class Tok {
    End, Ident, Int, Float, Str,
    At,            // @ (for @DATA / @CODE handled as Ident-like keywords)
    LParen, RParen, LBrace, RBrace, LBracket, RBracket,
    Colon, Semi, Comma, Arrow, Assign, Dot, FatArrow,   // FatArrow '=>' for match arms (feature #5)
    Plus, Minus, Star, Slash, Percent,
    EqEq, Ne, Lt, Le, Gt, Ge, Amp, AndAnd, OrOr, Bang,
    Pipe, Caret, Shl, Shr,    // infix bitwise: | ^ << >>  (& reuses Amp)
    KwFunc, KwIf, KwElse, KwLoop, KwWhile, KwBreak, KwContinue, KwReturn, KwSyscall,
    KwData, KwCode, KwStruct, KwImport, KwExtern, KwTool, KwLet,
};

struct Token {
    Tok kind;
    string text;   // identifier text / string bytes (decoded)
    i64t  ival = 0;
    double dval = 0.0;   // float-literal value (Tok::Float)
    int   line = 0;
    size_t off = 0;      // byte offset where this token STARTS, for caret diagnostics
};

// ---------------------------------------------------------------------
//  A6: --diagnostics=json. One diagnostic = ONE line = one JSON object, so a
//  tool consumes framing + classification instead of scraping prose (Studio's
//  fix_count() scans for "the first digits after a ': '" -- that fragility is
//  what this flag retires for new tooling). Scope v1, deliberately bounded:
//  PARSE errors (they carry file/line/col) and every GATED warning, in BOTH
//  compilers; other fatal messages stay prose. Field order is FIXED
//  (kind, file, line, col, msg) and the escaping rules are mirrored in the
//  self-hosted dj_*/dg_* helpers -- for warnings the two compilers must emit
//  BYTE-IDENTICAL JSON lines, exactly as they do for the prose the msg wraps.
//  A warning's msg is the full prose line (minus the newline); an error's msg
//  is that compiler's message text, which was never gated identical.
// ---------------------------------------------------------------------
static bool g_jsonDiag = false;
static void jsonAppendEscaped(string& o, const string& s){
    static const char* hex = "0123456789abcdef";
    for (size_t i=0;i<s.size();i++){
        unsigned char c = (unsigned char)s[i];
        if      (c=='"')  o += "\\\"";
        else if (c=='\\') o += "\\\\";
        else if (c=='\n') o += "\\n";
        else if (c=='\r') o += "\\r";
        else if (c=='\t') o += "\\t";
        else if (c<0x20){ o += "\\u00"; o += hex[(c>>4)&15]; o += hex[c&15]; }
        else o += (char)c;
    }
}
static void emitJsonDiag(const char* kind, const string& file, int line, int col, const string& msg){
    string o = "{\"kind\":\""; o += kind; o += "\"";
    if (line > 0){
        o += ",\"file\":\""; jsonAppendEscaped(o, file);
        o += "\",\"line\":" + std::to_string(line);
        if (col > 0) o += ",\"col\":" + std::to_string(col);
    }
    o += ",\"msg\":\""; jsonAppendEscaped(o, msg); o += "\"}";
    fprintf(stderr, "%s\n", o.c_str());
}
// Every warning funnels through here: msg is the FULL prose line without the
// trailing newline, so text mode prints exactly what it always printed and
// json mode wraps the identical bytes.
static void warnDiag(const string& msg){
    if (g_jsonDiag) emitJsonDiag("warning", "", 0, 0, msg);
    else fprintf(stderr, "%s\n", msg.c_str());
}

// Print the offending source line and a `^` under the exact column. Tabs are
// expanded to spaces first, otherwise the caret drifts away from the glyph it is
// meant to point at on any line that happens to be tab-indented.
static void emitCaret(const string& s, size_t off, int line){
    if (off > s.size()) off = s.size();
    size_t ls = off; while (ls > 0 && s[ls-1] != '\n') ls--;
    size_t le = off; while (le < s.size() && s[le] != '\n') le++;
    string raw = s.substr(ls, le - ls);
    size_t want = off - ls, col = 0; string shown;
    for (size_t k = 0; k <= raw.size(); k++){
        if (k == want) col = shown.size();
        if (k == raw.size()) break;
        if (raw[k] == '\t') { do { shown.push_back(' '); } while (shown.size() % 4); }
        else if (raw[k] == '\r') { }
        else shown.push_back(raw[k]);
    }
    string num = std::to_string(line);
    string pad(num.size(), ' ');
    fprintf(stderr, "  %s | %s\n", num.c_str(), shown.c_str());
    fprintf(stderr, "  %s | %*s^\n", pad.c_str(), (int)col, "");
}

// SC1: a catchable parse error, thrown ONLY in --fix mode (the normal path
// keeps calling fail()/exit, so it stays byte-identical). `expected` is set when
// the failure was a missing specific token (an expect(k,...) site) -> exactly
// what the F1/F2 inserter can auto-heal; other errors carry haveExpected=false.
struct ParseError { string msg; int line=0; size_t off=0; Tok expected=Tok::End; bool haveExpected=false; };

struct Lexer {
    const string& src;
    size_t i = 0;
    int line = 1;
    size_t prevTokEnd = 0;   // SC1: byte offset just past the PREVIOUS token (the --fix splice anchor)
    explicit Lexer(const string& s) : src(s) {}

    char peek() { return i < src.size() ? src[i] : '\0'; }
    char peek2(){ return i+1 < src.size() ? src[i+1] : '\0'; }
    char peek3(){ return i+2 < src.size() ? src[i+2] : '\0'; }
    char get()  { char c = peek(); if (c=='\n') line++; if (i<src.size()) i++; return c; }

    void skip() {
        for (;;) {
            char c = peek();
            if (c==' '||c=='\t'||c=='\r'||c=='\n') { get(); continue; }
            if (c=='#') { while (peek()!='\n' && peek()!='\0') get(); continue; }
            break;
        }
    }

    string decodeEscapes(const string& raw) {
        string out;
        for (size_t k=0;k<raw.size();k++) {
            char c = raw[k];
            if (c=='\\' && k+1<raw.size()) {
                char n = raw[++k];
                switch(n){
                    case 'n': out.push_back('\n'); break;
                    case 't': out.push_back('\t'); break;
                    case 'r': out.push_back('\r'); break;
                    case '0': out.push_back('\0'); break;
                    case '\\':out.push_back('\\'); break;
                    case '"': out.push_back('"');  break;
                    default:  out.push_back(n);     break;
                }
            } else out.push_back(c);
        }
        return out;
    }

    Token next() {
        prevTokEnd = i;           // SC1: end of the previous token, before skipping whitespace
        skip();
        Token t; t.line = line; t.off = i;   // caret diagnostics: where this token starts
        char c = peek();
        if (c=='\0') { t.kind = Tok::End; return t; }

        // identifiers / keywords (allow leading @ for @DATA / @CODE)
        if (c=='@' || isalpha((unsigned char)c) || c=='_') {
            string s;
            if (c=='@') { s.push_back(get()); }
            while (isalnum((unsigned char)peek()) || peek()=='_') s.push_back(get());
            if      (s=="@DATA")  t.kind = Tok::KwData;
            else if (s=="@CODE")  t.kind = Tok::KwCode;
            else if (s=="func")   t.kind = Tok::KwFunc;
            else if (s=="if")     t.kind = Tok::KwIf;
            else if (s=="else")   t.kind = Tok::KwElse;
            else if (s=="loop")   t.kind = Tok::KwLoop;
            else if (s=="while")  t.kind = Tok::KwWhile;
            else if (s=="break")  t.kind = Tok::KwBreak;
            else if (s=="continue") t.kind = Tok::KwContinue;
            else if (s=="return") t.kind = Tok::KwReturn;
            else if (s=="syscall")t.kind = Tok::KwSyscall;
            else if (s=="let")    t.kind = Tok::KwLet;
            else if (s=="struct") t.kind = Tok::KwStruct;
            else if (s=="import") t.kind = Tok::KwImport;
            else if (s=="extern") t.kind = Tok::KwExtern;
            else if (s=="tool")   t.kind = Tok::KwTool;
            else { t.kind = Tok::Ident; t.text = s; }   // 'prompt' is a CONTEXTUAL keyword (see parseProgram), not reserved
            return t;
        }
        // numbers: decimal or 0x.. hex (negative handled by parser via unary '-')
        if (isdigit((unsigned char)c)) {
            string s;
            if (c=='0' && (peek2()=='x' || peek2()=='X')) {
                get(); get();                                  // consume "0x"
                while (isxdigit((unsigned char)peek())) s.push_back(get());
                t.kind = Tok::Int; t.ival = (i64t)strtoull(s.c_str(), nullptr, 16); return t;
            }
            while (isdigit((unsigned char)peek())) s.push_back(get());
            bool isFloat = false;
            // fraction: '.' immediately followed by a digit  (so "<int>.field" stays Int + Dot)
            if (peek()=='.' && isdigit((unsigned char)peek2())) {
                isFloat = true;
                s.push_back(get());                              // consume '.'
                while (isdigit((unsigned char)peek())) s.push_back(get());
            }
            // exponent: e/E [ +/- ] digits   (1.5e3, 2e10, 2E-5)
            if ((peek()=='e' || peek()=='E') &&
                (isdigit((unsigned char)peek2()) ||
                 ((peek2()=='+' || peek2()=='-') && isdigit((unsigned char)peek3())))) {
                isFloat = true;
                s.push_back(get());                              // 'e' / 'E'
                if (peek()=='+' || peek()=='-') s.push_back(get());
                while (isdigit((unsigned char)peek())) s.push_back(get());
            }
            if (isFloat) { t.kind = Tok::Float; t.dval = strtod(s.c_str(), nullptr); return t; }
            t.kind = Tok::Int; t.ival = strtoll(s.c_str(), nullptr, 10); return t;
        }
        // char literal 'x'  -> int (ASCII)
        if (c=='\'') {
            get();
            char ch = get();
            if (ch=='\\') {
                char n=get();
                switch(n){case 'n':ch='\n';break;case 't':ch='\t';break;case 'r':ch='\r';break;
                          case '0':ch='\0';break;case '\\':ch='\\';break;case '\'':ch='\'';break;default:ch=n;}
            }
            if (peek()=='\'') get();
            t.kind = Tok::Int; t.ival = (unsigned char)ch; return t;
        }
        // string literal
        if (c=='"') {
            get();
            string raw;
            while (peek()!='"' && peek()!='\0') {
                if (peek()=='\\') { raw.push_back(get()); if(peek()!='\0') raw.push_back(get()); }
                else raw.push_back(get());
            }
            if (peek()=='"') get();
            t.kind = Tok::Str; t.text = decodeEscapes(raw); return t;
        }
        // operators / punctuation
        get();
        switch (c) {
            case '(': t.kind=Tok::LParen; return t;
            case ')': t.kind=Tok::RParen; return t;
            case '{': t.kind=Tok::LBrace; return t;
            case '}': t.kind=Tok::RBrace; return t;
            case '[': t.kind=Tok::LBracket; return t;
            case ']': t.kind=Tok::RBracket; return t;
            case '.': t.kind=Tok::Dot;    return t;
            case ':': t.kind=Tok::Colon;  return t;
            case ';': t.kind=Tok::Semi;   return t;
            case ',': t.kind=Tok::Comma;  return t;
            case '+': t.kind=Tok::Plus;   return t;
            case '*': t.kind=Tok::Star;   return t;
            case '/': t.kind=Tok::Slash;  return t;
            case '%': t.kind=Tok::Percent;return t;
            case '<':
                if (peek()=='=') { get(); t.kind=Tok::Le; return t; }
                if (peek()=='<') { get(); t.kind=Tok::Shl; return t; }
                t.kind=Tok::Lt; return t;
            case '>':
                if (peek()=='=') { get(); t.kind=Tok::Ge; return t; }
                if (peek()=='>') { get(); t.kind=Tok::Shr; return t; }
                t.kind=Tok::Gt; return t;
            case '!':
                if (peek()=='=') { get(); t.kind=Tok::Ne; return t; }
                t.kind=Tok::Bang; return t;
            case '&':
                if (peek()=='&') { get(); t.kind=Tok::AndAnd; return t; }
                t.kind=Tok::Amp; return t;
            case '|':
                if (peek()=='|') { get(); t.kind=Tok::OrOr; return t; }
                t.kind=Tok::Pipe; return t;
            case '^': t.kind=Tok::Caret; return t;
            case '-':
                if (peek()=='>') { get(); t.kind=Tok::Arrow; return t; }
                t.kind=Tok::Minus; return t;
            case '=':
                if (peek()=='=') { get(); t.kind=Tok::EqEq; return t; }
                if (peek()=='>') { get(); t.kind=Tok::FatArrow; return t; }   // '=>' match arm (feature #5)
                t.kind=Tok::Assign; return t;
        }
        if (g_fixMode) throw ParseError{ string("unexpected character '")+c+"'", t.line, prevTokEnd, Tok::End, false };
        fail(string("unexpected character '")+c+"' on line "+std::to_string(t.line));
        return t;
    }
};

// ---------------------------------------------------------------------
// 2. AST
// ---------------------------------------------------------------------
enum class NodeKind { Int, Float, Str, Var, Binary, Call, Addr };
struct Expr {
    NodeKind kind;
    i64t     ival = 0;        // Int
    double   dval = 0.0;      // Float literal value
    bool     isFloat = false; // result is f64? (stamped by parser; routes codegen to XMM/SSE2)
    int      strId = -1;      // Str (index into program strings)
    string   name;            // Var / Call name
    char     op = 0;          // Binary: + - * / and 'e'(==) 'l'(<) 'g'(>)
    std::unique_ptr<Expr> lhs, rhs;       // Binary
    vector<std::unique_ptr<Expr>> args;   // Call
};
using ExprP = std::unique_ptr<Expr>;

enum class StKind { Assign, If, Loop, Syscall, Return, ExprStmt, Break, Continue };
struct Stmt {
    StKind kind;
    string name;                       // Assign target
    bool   targetFloat = false;        // Assign target is an f64 slot (an int RHS converts via cvtsi2sd)
    bool   isLet = false;              // written as `let name = ...` -- an EXPLICIT local declaration
    ExprP  expr;                       // Assign value / If|Loop cond / Return value / ExprStmt expr
    vector<std::unique_ptr<Stmt>> body;     // If-then / Loop body
    vector<std::unique_ptr<Stmt>> elseBody;  // If-else
    i64t   sysNo = 0;                  // Syscall number
    vector<ExprP> sysArgs;             // Syscall args
};
using StmtP = std::unique_ptr<Stmt>;

struct Param { string name; string type; };
struct Func {
    string name;
    vector<Param> params;
    string retType;
    vector<StmtP> body;
    bool   isTool = false;   // declared via `tool` -> gets a JSON-Schema descriptor in the registry
    string toolDesc;         // optional LLM-facing description (trailing string literal after the signature)
    vector<string> floatLocals;     // f64 locals the PARSER saw (typed decls + float-RHS inference);
                                    // the post-parse stamping pass seeds from this and grows it
                                    // (a vector, not a set: Func must stay nothrow-movable for vector<Func>)
    string srcFile;                 // file this definition came from (empty for synthesized funcs)
    int    srcLine = 0;             // line of the 'func'/'tool' keyword
    string srcText;                 // normalized ('\r'-stripped) source span, for the duplicate check
};

struct DataVar {
    string name;
    string type;     // i32/i64/ptr/str/buf/...
    bool   isStr = false;
    int    strId = -1;     // if str
    i64t   ival = 0;       // if int constant  (also holds IEEE-754 bits when isFloat)
    bool   isFloat = false;// f64 constant: ival holds the raw 64-bit IEEE-754 pattern
    bool   isBuf = false;  // raw writable buffer in .data
    i64t   bufSize = 0;    // buffer size in bytes
    int    dataOff = -1;   // assigned .data offset (buffers)
};

// Lightweight, author-declared type (feature #4). Carries exactly what `p.field`/`a[i]`
// desugaring needs; never used for inference. A variable/field is loaded as i64 by default;
// these descriptors only drive field/index access.
struct Type {
    int    width = 8;          // load/store width of THIS value (scalar 1/2/4/8; ptr 8) -- used by p.field
    bool   isFloat = false;    // f64 scalar: width 8 but the value lives in XMM, not a GP reg
    bool   isAddr = false;     // this "value" is an inline address (array / nested-struct field) -> .field yields its address, not a load
    bool   dottable = false;   // p.field allowed (struct pointer/value); sname names the struct
    string sname;
    bool   indexable = false;  // a[i] allowed over SCALAR elements (load/store)
    int    elemWidth = 8;      // a[i] element load/store width
    int    elemSize  = 8;      // a[i] stride (sizeof element)
    bool   elemFloat = false;  // a[i] element is f64/f32 -- the LOAD must be stamped, or the
                               // bits land in RAX and the float path reads garbage (the same
                               // silent class as the f64-field bug; latent for *f64 until f32)
    bool   isSum = false;      // feature #5: a *Sum value -> `match` allowed (NOT dottable)
    string sumName;
};
struct AStruct {
    int size = 0;
    std::map<string,int> off;        // field name -> byte offset
    std::map<string,Type> ftype;     // field name -> type (drives p.field width / address)
};
// feature #5: a sum type (tagged union). A value is a heap ptr to { tag:i64 @0, payload @8 }.
struct SumVariant {
    string name;
    int    tag = 0;
    vector<std::pair<string,Type>> fields;   // (field name, type) in declaration order
    std::map<string,int> foff;               // field name -> byte offset within the block (>=8)
};
struct ASum {
    string name;
    int    blockSize = 8;                     // 8 (tag) + max variant payload, aligned to 8
    vector<SumVariant> variants;
    std::map<string,int> variantIndex;        // variant name -> index into variants
};

// SC4 (the `intent` oracle, L3): a declared acceptance case + the intent it belongs to.
struct IntentCase { string fnName; vector<i64t> args; i64t expected = 0; };
struct AIntent    { string name; int goalSid = 0; vector<IntentCase> cases; int checkerFuncIdx = 0; };

struct Program {
    vector<DataVar> data;
    vector<Func>    funcs;
    vector<string>  strings;   // string table (decoded bytes)
    std::map<string,AStruct> structs;   // struct layouts (compile-time)
    std::map<string,ASum>    sums;      // feature #5: sum-type (tagged union) layouts
    vector<AIntent>          intents;   // SC4: declared `intent` oracles (declaration order)
    std::set<string> warnedShadow;   // builtin-shadow warnings, deduped by name
    std::set<string> importedFiles;     // module include-once
    std::map<string,string> externs;    // user-declared FFI imports: func -> dll
    std::set<string> externPtrRet;      // externs whose return is a full 64-bit value
    std::set<string> externFloatRet;    // externs whose return is a float (in XMM0; no movsxd)
    std::set<string> externFloat32Ret;  // the '-> f32' subset: XMM0 holds a SINGLE and must be
                                        // widened (cvtss2sd) before the f64-computing language
                                        // touches it -- reading it as a double is garbage bits
    int addString(const string& s) { strings.push_back(s); return (int)strings.size()-1; }
};

// ---------------------------------------------------------------------
// 3. PARSER  (recursive descent)
// ---------------------------------------------------------------------

// FOOTGUN 3: defining a function whose name is a compiler builtin used to compile
// silently -- and every CALL still went to the builtin, so the user's function was
// dead code. That was the ancl_vm File>Open crash (a local `str_copy` that returned
// a length, while calls hit the builtin which returns a POINTER).
static bool isBuiltinName(const string& n){
    static const std::set<string> B = {
        "alloc","free","memcpy","memset","strlen","strcmp","str_copy","str_to_int",
        "int_to_str","puts_cstr","read_int","read_char","syscall","callp","callpp",
        "load8","load16","load32","load64","store8","store16","store32","store64",
        "band","bor","bxor","shl","shr","sqrt","itof","ftoi","fbits","ffrombits",
        "outb","inb","__mb_info",
        "tool_count","tool_name","tool_schema","tool_fn","tools_json"
    };
    return B.count(n)!=0;
}
struct Parser {
    Lexer lex;
    Token cur;
    Program& prog;
    string baseDir;
    std::map<string,Type> localType;   // feature #4: per-function name -> declared type (params + typed locals)
    string curFile;                    // the file THIS parser is reading, for diagnostics
    Parser(const string& src, Program& p, string base="", string file="")
        : lex(src), prog(p), baseDir(base), curFile(file) { cur = lex.next(); }

    [[noreturn]] void perr(const string& m){
        if (g_fixMode) throw ParseError{ m, cur.line, lex.prevTokEnd, Tok::End, false };   // SC1: catchable
        // The bootstrap used to print a bare "(line N)" with NO FILE. The line was
        // right -- imports are parsed recursively, not spliced, so it is the line
        // within the offending file -- but with 1000+ importing files in this tree you
        // could not tell WHICH file line N belonged to. The self-hosted compiler has
        // named the file since lever B; this brings the reference into line with it and
        // adds the caret, which was the last open item on the lever-B worklist.
        if (g_jsonDiag){
            size_t off = cur.off > lex.src.size() ? lex.src.size() : cur.off;
            size_t ls = off; while (ls > 0 && lex.src[ls-1] != '\n') ls--;
            emitJsonDiag("error", curFile.empty() ? "<input>" : curFile,
                         cur.line, (int)(off - ls + 1), m);
            exit(1);
        }
        fprintf(stderr, "anclc: error: %s:%d: %s\n",
                (curFile.empty() ? "<input>" : curFile.c_str()), cur.line, m.c_str());
        emitCaret(lex.src, cur.off, cur.line);
        exit(1);
    }
    void advance(){ cur = lex.next(); }
    bool accept(Tok k){ if(cur.kind==k){advance();return true;} return false; }
    void expect(Tok k, const char* what){
        if(cur.kind!=k){
            if (g_fixMode) throw ParseError{ string("expected ")+what, cur.line, lex.prevTokEnd, k, true };  // SC1: F1/F2-fixable
            perr(string("expected ")+what);
        }
        advance();
    }

    bool isTypeKw() { return cur.kind==Tok::Ident; } // types are plain idents (i32,i64,...)

    // compile-time constant folding for @DATA initializers (literals, +-*/%, earlier @DATA ints)
    i64t foldConst(Expr* e){
        if (e->kind==NodeKind::Int) return e->ival;
        if (e->kind==NodeKind::Var){
            for (auto& d:prog.data) if (d.name==e->name && !d.isStr && !d.isBuf) return d.ival;
            perr("unknown constant '"+e->name+"' in @DATA initializer");
        }
        if (e->kind==NodeKind::Binary){
            i64t a=foldConst(e->lhs.get()), b=foldConst(e->rhs.get());
            switch(e->op){
                case '+':return a+b;  case '-':return a-b;  case '*':return a*b;
                case '/':return b?a/b:0; case 'm':return b?a%b:0;
                case 'e':return a==b; case 'n':return a!=b;
                case 'l':return a<b;  case 'L':return a<=b; case 'g':return a>b; case 'G':return a>=b;
                case 'a':return (a&&b)?1:0; case 'o':return (a||b)?1:0;
            }
        }
        // infix bitwise/shift desugar to intrinsic 2-arg calls (bor/bxor/band/shl/shr)
        // in the expression parser; fold them here so @DATA const-exprs accept | & ^ << >> too.
        if (e->kind==NodeKind::Call && e->args.size()==2){
            i64t a=foldConst(e->args[0].get()), b=foldConst(e->args[1].get());
            if (e->name=="bor")  return a|b;
            if (e->name=="bxor") return a^b;
            if (e->name=="band") return a&b;
            if (e->name=="shl")  return (i64t)((u64)a << (b&63));
            if (e->name=="shr")  return (i64t)((u64)a >> (b&63));
        }
        perr("non-constant expression in @DATA initializer");
        return 0;
    }
    // compile-time f64 folding for @DATA initializers (float/int literals, + - * /,
    // earlier @DATA consts - f64 ones decode their stored IEEE-754 bits)
    double foldConstF(Expr* e){
        if (e->kind==NodeKind::Float) return e->dval;
        if (e->kind==NodeKind::Int)   return (double)e->ival;
        if (e->kind==NodeKind::Var){
            for (auto& d:prog.data) if (d.name==e->name && !d.isStr && !d.isBuf){
                if (d.isFloat){ union { i64t u; double dd; } cv; cv.u=d.ival; return cv.dd; }
                return (double)d.ival;
            }
            perr("unknown constant '"+e->name+"' in f64 @DATA initializer");
        }
        if (e->kind==NodeKind::Binary){
            double l=foldConstF(e->lhs.get()), r=foldConstF(e->rhs.get());
            switch(e->op){
                case '+':return l+r; case '-':return l-r; case '*':return l*r;
                case '/':return r==0.0?0.0:l/r;
            }
            perr("unsupported operator in f64 @DATA initializer (only + - * /)");
        }
        perr("non-constant expression in f64 @DATA initializer");
        return 0.0;
    }

    // top-level items may repeat and appear in any order (so imported modules merge cleanly)
    void parseProgram() {
        for (;;) {
            if      (cur.kind==Tok::KwStruct) parseStruct();
            else if (cur.kind==Tok::KwImport) parseImport();
            else if (cur.kind==Tok::KwExtern) parseExtern();
            else if (cur.kind==Tok::KwData) { advance(); parseData(); }
            else if (cur.kind==Tok::KwCode) { advance(); parseCode(); }
            else if (cur.kind==Tok::KwFunc) parseFunc();      // bare top-level function (modules)
            else if (cur.kind==Tok::KwTool) parseTool();      // LLM-callable function + JSON-Schema descriptor
            // 'prompt'/'sum' are CONTEXTUAL: keywords only here (top-level decl), ordinary identifiers
            // elsewhere (so existing code like ai_bridge's `ai_request(prompt: i64,...)` and any `sum`
            // local keep compiling). 'match' is contextual at statement position (see parseStmt).
            else if (cur.kind==Tok::Ident && cur.text=="prompt") parsePrompt();
            else if (cur.kind==Tok::Ident && cur.text=="sum") parseSum();   // feature #5
            else if (cur.kind==Tok::Ident && cur.text=="intent") parseIntent();   // SC4: the intent oracle (L3)
            else if (cur.kind==Tok::End) break;
            else perr("unexpected top-level token");
        }
    }

    void parseImport(){
        advance();
        if (cur.kind!=Tok::Str) perr("expected \"path\" after import");
        string rel=cur.text; advance();
        accept(Tok::Semi);
        bool abs = (rel.size()>1 && rel[1]==':') || (!rel.empty() && (rel[0]=='\\'||rel[0]=='/'));
        string full = abs ? rel : baseDir + rel;
        string key = canonPath(full);                     // include-once on the CANONICAL key --
        if (prog.importedFiles.count(key)) return;        // "a/./x" and "a/././x" are the same file
        prog.importedFiles.insert(key);
        string src2;
        if (!slurpFile(full, src2)) fail("cannot open import '"+full+"'");
        src2 = applyCond(src2, full);          // conditional compilation, before parsing
        Parser sub(src2, prog, dirOf(full), full);
        sub.parseProgram();
    }

    void parseExtern(){
        advance();
        if (cur.kind!=Tok::Str) perr("expected \"dll\" after extern");
        string dll=cur.text; advance();
        for (;;) {
            if (cur.kind!=Tok::Ident) perr("expected function name in extern");
            string fn=cur.text; advance();
            if (cur.kind==Tok::Arrow){            // optional return-type hint
                advance();
                if (cur.kind!=Tok::Ident) perr("expected return type after '->'");
                string rt=cur.text; advance();
                // The hint was previously matched against ptr/i64/f64/f32 and ANY other
                // spelling was silently dropped -- so `-> HBITMAP` or `-> u64` compiled
                // clean and then took extendRet's default sign-extension, truncating a
                // 64-bit handle to EAX. Unknown hints are now rejected.
                //
                // The 32-bit-ish group is deliberately a NO-OP rather than a width
                // instruction: extendRet's ABI name tables (LRESULT/HANDLE/ATOM returns)
                // must keep overriding the declaration, because the tree contains
                // genuinely wrong hints that those tables currently rescue -- e.g.
                // `DispatchMessageA -> i32`, whose real return is a 64-bit LRESULT.
                // Making the hint authoritative would start truncating them.
                if (rt=="ptr"||rt=="i64"||rt=="u64") prog.externPtrRet.insert(fn);
                else if (rt=="f64"||rt=="f32") { prog.externFloatRet.insert(fn);   // float return in XMM0
                                                 if (rt=="f32") prog.externFloat32Ret.insert(fn); }
                else if (rt=="i32"||rt=="u32"||rt=="i16"||rt=="u16"||rt=="i8"||rt=="u8"||rt=="void") { }
                else perr("unknown extern return type '"+rt+"' (want ptr/i64/u64/i32/u32/i16/u16/i8/u8/f64/f32/void)");
            }
            prog.externs[fn]=dll;
            if (!accept(Tok::Comma)) break;
        }
        expect(Tok::Semi,"';'");
    }

    static int alignUp4(int v,int a){ return a<=1 ? v : ((v + a - 1)/a*a); }

    // parse a type spec, returning its total byte size; sets *alignOut to the alignment
    int parseTypeSize(int* alignOut, Type* tout=nullptr){
        int base, align; bool isPtr=false; string elemName;
        if (accept(Tok::Star)) {                    // *T  -> pointer, 8 bytes
            if (cur.kind==Tok::Ident){ elemName=cur.text; advance(); } else perr("expected type after '*'");
            base=8; align=8; isPtr=true;
        } else if (cur.kind==Tok::Ident) {
            string nm=cur.text; advance(); elemName=nm;
            if (prog.structs.count(nm)) { base=prog.structs[nm].size; align=8; }
            else if (prog.sums.count(nm)) { base=8; align=8; }   // feature #5: a bare sum value is a pointer (8B)
            else if (nm=="i8")  { base=1; align=1; }
            else if (nm=="i16") { base=2; align=2; }
            else if (nm=="i32"||nm=="f32") { base=4; align=4; }
            else if (nm=="i64"||nm=="f64"||nm=="ptr"||nm=="str") { base=8; align=8; }
            else perr("unknown type '"+nm+"'");
        } else { perr("expected type"); base=8; align=8; }
        // type descriptor for the NON-array base
        Type t;
        if (isPtr) {
            t.width=8;
            if (prog.sums.count(elemName)) { t.isSum=true; t.sumName=elemName; }          // *Sum -> match
            else if (prog.structs.count(elemName)) { t.dottable=true; t.sname=elemName; t.indexable=true; t.elemSize=prog.structs[elemName].size; }  // *Struct -> p.field AND rows[i].field (v1.1 chaining)
            else { t.indexable=true; t.elemWidth=scalarWidth(elemName); t.elemSize=t.elemWidth;
                   t.elemFloat=(elemName=="f64"||elemName=="f32"); }                              // *scalar -> a[i]
        } else if (prog.sums.count(elemName)) {
            t.isSum=true; t.sumName=elemName; t.width=8;                                   // bare sum value (a pointer) -> match
        } else if (prog.structs.count(elemName)) {
            t.dottable=true; t.sname=elemName; t.width=8; t.isAddr=true;                  // struct value (inline addr) -> p.field
        } else {
            t.width=scalarWidth(elemName);                                               // plain scalar
            if (elemName=="f64"||elemName=="f32") t.isFloat=true;                         // f64/f32 -> XMM/SSE2 path
        }
        int total=base;
        if (accept(Tok::LBracket)) {                // T[N] array field -> a[i] over base elements; .field yields its address
            total = base * (int)foldConst(parseExpr().get());
            expect(Tok::RBracket,"']'");
            Type arr; arr.isAddr=true; arr.elemSize=base;
            if (!isPtr && !prog.structs.count(elemName)) { arr.indexable=true; arr.elemWidth=scalarWidth(elemName);
                                                           arr.elemFloat=(elemName=="f64"||elemName=="f32"); }
            t=arr;                                  // scalar[N] is indexable; struct[N]/ptr[N] are address-only in v1
        }
        if (tout) *tout=t;
        if (alignOut) *alignOut=align;
        return total;
    }

    void parseStruct(){
        advance();                                   // 'struct'
        if (cur.kind!=Tok::Ident) perr("expected struct name");
        string nm=cur.text; advance();
        expect(Tok::LBrace,"'{'");
        prog.structs[nm];        // forward-declare (empty) so a self-referential `next: *Self` field
                                 // resolves as a struct pointer (dottable) for v1.1 chaining; size is
                                 // size-neutral (a *T field is 8 bytes regardless) and finalized below.
        AStruct st; int off=0;
        while (cur.kind==Tok::Ident){
            string fn=cur.text; advance();
            expect(Tok::Colon,"':'");
            int align; Type ft; int sz=parseTypeSize(&align,&ft);
            off=alignUp4(off,align);
            st.off[fn]=off;
            st.ftype[fn]=ft;
            off+=sz;
            if (!accept(Tok::Semi)) accept(Tok::Comma);   // ';' or ',' separator (either accepted)
        }
        expect(Tok::RBrace,"'}'");
        st.size=alignUp4(off,8);
        if (st.size==0) st.size=8;
        // Duplicate struct definitions: the map assignment below means the LAST
        // one silently wins EVERY field offset, program-wide -- a layout hazard
        // stronger than the function case (a conflicting copy silently moves
        // every p.field in code that believed the other one). Measured across
        // 186 corpus programs: ZERO duplicates exist, so a conflicting
        // redefinition has no legitimate use to protect and warns with zero
        // measured false positives. An IDENTICAL layout stays silent -- two
        // distinct files carrying the same module, as with @DATA and functions.
        // âš  The self-hosted par_struct_find used to resolve FIRST-match here --
        // a latent cross-compiler divergence (probe: 16 vs 24 on a two-def
        // program), aligned to last-match when this warning landed.
        {
            auto it=prog.structs.find(nm);
            if (it!=prog.structs.end() && (it->second.size>0 || !it->second.off.empty())){
                bool same = it->second.size==st.size && it->second.off==st.off;
                if (same){
                    for (auto& kv : st.ftype){
                        auto jt=it->second.ftype.find(kv.first);
                        const Type& a=jt->second; const Type& b=kv.second;   // off== guarantees the key exists
                        if (a.width!=b.width || a.isFloat!=b.isFloat || a.isAddr!=b.isAddr ||
                            a.dottable!=b.dottable || a.sname!=b.sname || a.indexable!=b.indexable ||
                            a.elemWidth!=b.elemWidth || a.elemSize!=b.elemSize || a.elemFloat!=b.elemFloat ||
                            a.isSum!=b.isSum || a.sumName!=b.sumName){ same=false; break; }
                    }
                }
                if (!same && !prog.warnedShadow.count("dups@"+nm)){
                    prog.warnedShadow.insert("dups@"+nm);
                    warnDiag("anclc: warning: conflicting redefinition of struct '" + nm + "' -- the last definition silently wins every field offset");
                }
            }
        }
        prog.structs[nm]=st;
    }

    // feature #5: `sum Name { Variant(f: T, ...), Empty, ... }` -> a tagged union.
    // A value is a heap ptr to { tag:i64 @0, active-variant fields @8 }. We record the layout and
    // synthesize a maker function per variant (alloc + store tag + store fields). `match` reads it back.
    void synthSumMaker(const string& sumName, ASum& sm, SumVariant& v){
        Func f; f.name = "__sum_" + sumName + "_" + v.name;
        for (auto& fld : v.fields) { Param p; p.name=fld.first; p.type="i64"; f.params.push_back(p); }  // makers pass fields as i64 regs; stored at the field's real width below
        f.retType = "ptr";
        f.body.push_back(mkAssign("__p", mkCall1("alloc", mkInt(sm.blockSize))));         // __p avoids colliding with a field named `p`
        f.body.push_back(mkExprStmt(mkCall("store64", mkVar("__p"), mkInt(v.tag))));      // tag @ 0
        for (auto& fld : v.fields)
            f.body.push_back(mkExprStmt(mkCall(stName(fld.second.width), mkBin('+', mkVar("__p"), mkInt(v.foff[fld.first])), mkVar(fld.first))));
        f.body.push_back(mkReturn(mkVar("__p")));
        prog.funcs.push_back(std::move(f));
    }
    void parseSum(){
        advance();                                   // 'sum' (contextual identifier)
        if (cur.kind!=Tok::Ident) perr("expected sum name");
        string nm=cur.text; advance();
        expect(Tok::LBrace,"'{'");
        prog.sums[nm];                               // forward-declare (self/mutual-ref payloads resolve)
        ASum sm; sm.name=nm; int maxEnd=8; int tag=0;
        while (cur.kind==Tok::Ident){
            SumVariant v; v.name=cur.text; v.tag=tag; advance();
            int off=8;
            if (accept(Tok::LParen)) {               // Variant(field: type, ...)
                if (cur.kind!=Tok::RParen) {
                    for(;;){
                        if (cur.kind!=Tok::Ident) perr("expected field name in variant '"+v.name+"'");
                        string fn=cur.text; advance();
                        expect(Tok::Colon,"':'");
                        int align; Type ft; int sz=parseTypeSize(&align,&ft);
                        // f32 VARIANT fields stay refused (the self-hosted side always has):
                        // the synthesized maker passes fields as i64 registers and stores at
                        // the field's width, so a 4-byte single would get the low 32 bits of
                        // the DOUBLE's pattern -- garbage with no diagnostic. f32 STORAGE
                        // lives in structs/arrays, where loads and stores convert honestly.
                        if (ft.isFloat && ft.width==4) perr("f32 sum-variant fields are not supported (use f64)");
                        off=alignUp4(off,align);
                        v.fields.push_back({fn,ft}); v.foff[fn]=off;
                        off+=sz;
                        if (!accept(Tok::Comma)) break;
                    }
                }
                expect(Tok::RParen,"')'");
            }
            if (off>maxEnd) maxEnd=off;
            sm.variantIndex[v.name]=(int)sm.variants.size();
            sm.variants.push_back(std::move(v));
            tag++;
            accept(Tok::Comma);                      // optional separator between variants
        }
        expect(Tok::RBrace,"'}'");
        sm.blockSize=alignUp4(maxEnd,8); if (sm.blockSize<8) sm.blockSize=8;
        prog.sums[nm]=sm;
        for (auto& v : prog.sums[nm].variants) synthSumMaker(nm, prog.sums[nm], v);
    }

    void parseData() {
        while (cur.kind==Tok::Ident) {
            DataVar dv;
            dv.name = cur.text; advance();
            expect(Tok::Colon, "':'");
            if (cur.kind!=Tok::Ident) perr("expected type");
            dv.type = cur.text; advance();
            if (cur.kind==Tok::LBracket) {
                // initialized integer array:  name: scalarType[N] = { cexpr, ... }
                // -> a read-only byte blob placed in .rdata (interned via the string path);
                //    the name evaluates to the blob's ADDRESS (read with load*(name + i*w)).
                advance();
                long N = (long)foldConst(parseExpr().get());                  // element count (const-expr)
                expect(Tok::RBracket, "']'");
                if (N < 0) perr("@DATA array length must be >= 0");
                if (dv.type!="i8"&&dv.type!="i16"&&dv.type!="i32"&&dv.type!="i64"&&dv.type!="ptr")
                    perr("@DATA arrays support only integer element types (i8/i16/i32/i64/ptr) in v1");
                int w = scalarWidth(dv.type);
                expect(Tok::Assign, "'='");
                expect(Tok::LBrace, "'{'");
                std::string blob((size_t)N*w, '\0');                          // zero-init (C-style zero-fill)
                long cnt=0;
                while (cur.kind!=Tok::RBrace) {                               // '}' ends the list (trailing comma OK)
                    if (cnt>=N) perr("too many initializers for @DATA array '"+dv.name+"'");
                    i64t v = foldConst(parseExpr().get());                    // per-element const-expr fold
                    for (int k=0;k<w;++k) blob[(size_t)(cnt*w+k)] = (char)(u8)((u64)v >> (8*k));  // little-endian
                    cnt++;
                    if (cur.kind==Tok::Comma) advance();                      // ',' required between elements
                    else break;
                }
                expect(Tok::RBrace, "'}'");
                dv.isStr = true; dv.strId = prog.addString(blob);             // blob in .rdata; name = its address
            } else {
            expect(Tok::Assign, "'='");
            if (dv.type=="buf") {
                dv.isBuf = true; dv.bufSize = foldConst(parseExpr().get());   // size may be a const expr
            } else if (cur.kind==Tok::Str) {
                dv.isStr = true; dv.strId = prog.addString(cur.text); advance();
            } else if (dv.type=="f64"||dv.type=="f32") {                      // f64 const: IEEE-754 bits live in ival
                union { double d; i64t u; } cv; cv.d = foldConstF(parseExpr().get());
                dv.isFloat = true; dv.ival = cv.u;
            } else {
                dv.ival = foldConst(parseExpr().get());                       // folded constant expression
            }
            }
            expect(Tok::Semi, "';'");
            // FOOTGUN 1: a duplicate @DATA name used to compile SILENTLY, first
            // definition winning and the second ignored. This cost a real debug
            // cycle (a second `lbl_port` collided with the control label and the
            // Phase-6.5 map rendered the wrong text).
            // Only a CONFLICTING redefinition is an error. An identical one is a
            // harmless no-op and happens legitimately when two distinct files hold
            // the same module (include-once now canonicalizes its key, so the SAME
            // file can no longer arrive twice -- but two copied files still can);
            // erroring on that would reject trees that are merely redundant, not wrong.
            for (auto& d0 : prog.data)
                if (d0.name == dv.name){
                    bool same = d0.type==dv.type && d0.isStr==dv.isStr && d0.isBuf==dv.isBuf &&
                                d0.isFloat==dv.isFloat && d0.ival==dv.ival && d0.bufSize==dv.bufSize;
                    if (same && d0.isStr) same = (prog.strings[d0.strId] == prog.strings[dv.strId]);
                    // A WARNING, not an error. It earned its keep immediately -- it found
                    // multi_tester's m_int (core_lib's "int    = " label vs the IEC-104
                    // "20:INTROG", so the 61850 integer display rendered the wrong text)
                    // and Aether Studio's s_logname/g_logpath (the errfix training corpus
                    // was being appended into aether_output.log). But the Aether Engine
                    // declares a module-local `m_pass` self-test string in EVERY module,
                    // which is a convention rather than a mistake; erroring would reject
                    // the engine outright. Report once per name and let the author judge.
                    if (!same && !prog.warnedShadow.count("@"+dv.name)){
                        prog.warnedShadow.insert("@"+dv.name);
                        warnDiag("anclc: warning: conflicting redefinition of @DATA '" + dv.name + "' -- the first definition silently wins");
                    }
                }
            prog.data.push_back(dv);
        }
    }

    // Capture the definition's normalized source span + origin, then push it,
    // warning if it CONFLICTS with an earlier definition of the same name.
    // Shared by parseFunc and parseTool -- the two spellings must not diverge
    // on this the way they once did on operand placement (lever I).
    void finishFuncDef(Func& f, size_t startOff, int startLine){
        size_t endOff = cur.off; if (endOff > lex.src.size()) endOff = lex.src.size();
        if (endOff > startOff){
            string t = lex.src.substr(startOff, endOff - startOff);
            size_t rb = t.rfind('}');                     // trim trailing blanks/comments after the body
            if (rb != string::npos) t = t.substr(0, rb+1);
            string n; n.reserve(t.size());
            for (char c : t) if (c != '\r') n.push_back(c);   // an LF copy of a CRLF file is the same code
            f.srcText = n;
        }
        f.srcFile = curFile.empty() ? string("<input>") : curFile;
        f.srcLine = startLine;
        // Duplicate function definitions: the last one silently wins EVERY call
        // (funcLabel is name-keyed). Measured across 186 corpus programs before
        // building this: ~206 duplicates are the deliberate module-self-test
        // `main` convention (an importing program's main overrides them), and
        // the only other conflict was a live bug (two different flow_resets in
        // the agent -- both call sites cleared one table, the other was NEVER
        // cleared). So: `main` is exempt, an IDENTICAL copy is silent (two
        // distinct files legitimately carry the same module -- the @DATA
        // duplicate check reasons the same way), and only a CONFLICTING
        // redefinition warns. Once per name, like every warning here.
        if (f.name != "main" && !f.srcText.empty()){
            for (auto& f0 : prog.funcs){
                if (f0.name != f.name || f0.srcText.empty()) continue;
                if (f0.srcText != f.srcText && !prog.warnedShadow.count("dup@"+f.name)){
                    prog.warnedShadow.insert("dup@"+f.name);
                    warnDiag("anclc: warning: conflicting redefinition of function '" + f.name + "' -- the last definition silently wins every call");
                }
                break;                                    // compare against the FIRST occurrence only
            }
        }
        prog.funcs.push_back(std::move(f));
    }

    void parseFunc() {
        size_t defOff = cur.off; int defLine = cur.line;
        advance();   // 'func'
        Func f;
        if (cur.kind!=Tok::Ident) perr("expected function name");
        f.name = cur.text; advance();
        // FOOTGUN 3: redefining a compiler builtin compiles silently AND every call
        // still goes to the builtin, so the definition is dead code. That was the
        // ancl_vm File>Open crash (a local `str_copy` returning a LENGTH while calls
        // hit the builtin, which returns a POINTER).
        // A WARNING, not an error: ~50 definitions across this tree shadow a builtin
        // (str_copy / str_to_int / strlen / int_to_str in the protocol simulators and
        // testers), several in files owned by other agents. They are all dead code
        // today, so promoting this to an error is a repo-wide cleanup decision, not
        // something the compiler should force. Reported once per name.
        if (isBuiltinName(f.name) && !prog.warnedShadow.count(f.name)){
            prog.warnedShadow.insert(f.name);
            warnDiag("anclc: warning: '" + f.name + "' redefines a compiler builtin -- every call still goes to the builtin, so this definition is dead code");
        }
        expect(Tok::LParen, "'('");
        if (cur.kind!=Tok::RParen) {
            for (;;) {
                Param p;
                if (cur.kind!=Tok::Ident) perr("expected param name");
                p.name = cur.text; advance();
                expect(Tok::Colon, "':'");
                if (cur.kind!=Tok::Ident) perr("expected param type");
                p.type = cur.text; advance();
                f.params.push_back(p);
                if (!accept(Tok::Comma)) break;
            }
        }
        expect(Tok::RParen, "')'");
        expect(Tok::Arrow, "'->'");
        if (cur.kind!=Tok::Ident) perr("expected return type");
        f.retType = cur.text; advance();
        expect(Tok::LBrace, "'{'");
        localType.clear();
        for (auto& pp:f.params) localType[pp.name]=typeFromName(pp.type);   // params dottable iff typed with a struct name
        f.body = parseBlock();
        for (auto& kv:localType) if (kv.second.isFloat) f.floatLocals.push_back(kv.first);  // hand parse-time f64 knowledge to the stamping pass
        finishFuncDef(f, defOff, defLine);
    }
    // `tool` = `func` + an optional trailing description string. Emits the native function
    // (callable/addressable like any func) AND, via the registry, a JSON-Schema descriptor.
    void parseTool() {
        size_t defOff = cur.off; int defLine = cur.line;
        advance();   // 'tool'
        Func f; f.isTool = true;
        if (cur.kind!=Tok::Ident) perr("expected tool name");
        f.name = cur.text; advance();
        expect(Tok::LParen, "'('");
        if (cur.kind!=Tok::RParen) {
            for (;;) {
                Param p;
                if (cur.kind!=Tok::Ident) perr("expected param name");
                p.name = cur.text; advance();
                expect(Tok::Colon, "':'");
                if (cur.kind!=Tok::Ident) perr("expected param type");
                p.type = cur.text; advance();
                f.params.push_back(p);
                if (!accept(Tok::Comma)) break;
            }
        }
        expect(Tok::RParen, "')'");
        expect(Tok::Arrow, "'->'");
        if (cur.kind!=Tok::Ident) perr("expected return type");
        f.retType = cur.text; advance();
        if (cur.kind==Tok::Str) { f.toolDesc = cur.text; advance(); }   // optional doc string
        expect(Tok::LBrace, "'{'");
        localType.clear();
        for (auto& pp:f.params) localType[pp.name]=typeFromName(pp.type);
        f.body = parseBlock();
        for (auto& kv:localType) if (kv.second.isFloat) f.floatLocals.push_back(kv.first);
        finishFuncDef(f, defOff, defLine);
    }
    // `prompt NAME(params) -> str { "template with {holes}" }` desugars to an ordinary
    // function that substitutes the holes into a build buffer, calls the program-provided
    // ai_request(prompt_ptr, out_ptr), and returns the reply buffer. NO new codegen.
    void ensurePromptBuffers(){
        for (auto& d:prog.data) if (d.name=="__prompt_build") return;       // create once, shared
        DataVar b; b.name="__prompt_build"; b.type="buf"; b.isBuf=true; b.bufSize=16384; prog.data.push_back(b);
        DataVar r; r.name="__prompt_reply"; r.type="buf"; r.isBuf=true; r.bufSize=65536; prog.data.push_back(r);
    }
    static bool isIntType(const string& t){ return t=="i8"||t=="i16"||t=="i32"||t=="i64"; }
    void parsePrompt(){
        advance();   // 'prompt'
        Func f;
        if (cur.kind!=Tok::Ident) perr("expected prompt name");
        f.name=cur.text; advance();
        expect(Tok::LParen,"'('");
        if (cur.kind!=Tok::RParen){
            for(;;){
                Param p;
                if (cur.kind!=Tok::Ident) perr("expected param name");
                p.name=cur.text; advance();
                expect(Tok::Colon,"':'");
                if (cur.kind!=Tok::Ident) perr("expected param type");
                p.type=cur.text; advance();
                f.params.push_back(p);
                if (!accept(Tok::Comma)) break;
            }
        }
        expect(Tok::RParen,"')'");
        expect(Tok::Arrow,"'->'");
        if (cur.kind!=Tok::Ident) perr("expected return type");
        f.retType=cur.text; advance();
        if (f.retType!="str" && f.retType!="ptr") perr("a prompt must return 'str' or 'ptr'");
        expect(Tok::LBrace,"'{'");
        if (cur.kind!=Tok::Str) perr("expected a template string literal in the prompt body");
        string tmpl=cur.text; advance();
        expect(Tok::RBrace,"'}'");

        // split the template into literal segments + {param} holes ({{ and }} -> literal braces)
        vector<string> segs; vector<int> holes;
        string seg;
        for (size_t i=0;i<tmpl.size();){
            char c=tmpl[i];
            if (c=='{' && i+1<tmpl.size() && tmpl[i+1]=='{'){ seg.push_back('{'); i+=2; continue; }
            if (c=='}' && i+1<tmpl.size() && tmpl[i+1]=='}'){ seg.push_back('}'); i+=2; continue; }
            if (c=='{'){
                segs.push_back(seg); seg.clear();
                size_t j=i+1; string id;
                while (j<tmpl.size() && tmpl[j]!='}'){ id.push_back(tmpl[j]); j++; }
                if (j>=tmpl.size()) perr("unterminated '{hole}' in prompt '"+f.name+"'");
                int pidx=-1;
                for (size_t k=0;k<f.params.size();k++) if (f.params[k].name==id){ pidx=(int)k; break; }
                if (pidx<0) perr("prompt '"+f.name+"' hole '{"+id+"}' is not a parameter");
                const string& pt=f.params[pidx].type;
                if (!isIntType(pt) && pt!="str" && pt!="ptr")
                    perr("prompt hole '{"+id+"}' type '"+pt+"' unsupported (use str/ptr or i8..i64)");
                holes.push_back(pidx);
                i=j+1; continue;
            }
            seg.push_back(c); i++;
        }
        segs.push_back(seg);                 // segs.size() == holes.size()+1

        ensurePromptBuffers();

        // desugared body: build the prompt, call ai_request, return the reply buffer
        vector<StmtP> body;
        body.push_back(mkAssign("e", mkCall("str_copy", mkVar("__prompt_build"), mkStr(prog.addString(segs[0])))));
        for (size_t h=0;h<holes.size();h++){
            const Param& pp=f.params[holes[h]];
            if (isIntType(pp.type)){
                body.push_back(mkExprStmt(mkCall("int_to_str", mkVar("e"), mkVar(pp.name))));
                body.push_back(mkAssign("e", mkBin('+', mkVar("e"), mkCall1("strlen", mkVar("e")))));
            } else {
                body.push_back(mkAssign("e", mkCall("str_copy", mkVar("e"), mkVar(pp.name))));
            }
            body.push_back(mkAssign("e", mkCall("str_copy", mkVar("e"), mkStr(prog.addString(segs[h+1])))));
        }
        body.push_back(mkExprStmt(mkCall("ai_request", mkVar("__prompt_build"), mkVar("__prompt_reply"))));
        body.push_back(mkReturn(mkVar("__prompt_reply")));

        f.body=std::move(body);
        prog.funcs.push_back(std::move(f));
    }
    // SC4: the `intent` oracle (L3). Contextual keyword (like prompt/sum) at top-level.
    //   intent NAME { goal: "..."; case fn(args) => expected; ... }
    // Desugars (ZERO codegen change) into a synthetic checker __intent_NAME() that returns
    // the 1-based index of the first failing case (0 = all pass), printing a counterexample
    // ("intent NAME case K: expected E got A") on the first failure. The goal prose is interned
    // (compile-time metadata for the AI repair driver). Cases are constant-folded pure-i64 calls.
    void parseIntent(){
        advance();   // 'intent'
        if (cur.kind!=Tok::Ident) perr("expected intent name");
        string iname=cur.text; advance();
        expect(Tok::LBrace,"'{'");
        if (!(cur.kind==Tok::Ident && cur.text=="goal")) perr("expected 'goal:' in intent '"+iname+"'");
        advance(); expect(Tok::Colon,"':'");
        if (cur.kind!=Tok::Str) perr("expected a goal string literal in intent '"+iname+"'");
        AIntent ai; ai.name=iname; ai.goalSid=prog.addString(cur.text); advance();
        expect(Tok::Semi,"';'");

        Func f; f.name="__intent_"+iname; f.retType="i64";
        vector<StmtP> body;
        int caseNo=0;
        while (cur.kind!=Tok::RBrace && cur.kind!=Tok::End){
            if (!(cur.kind==Tok::Ident && cur.text=="case")) perr("expected 'case' or '}' in intent '"+iname+"'");
            advance();
            if (cur.kind!=Tok::Ident) perr("expected a function name after 'case'");
            string fnName=cur.text; advance();
            expect(Tok::LParen,"'('");
            IntentCase ic; ic.fnName=fnName;
            auto call=std::make_unique<Expr>(); call->kind=NodeKind::Call; call->name=fnName;
            if (cur.kind!=Tok::RParen){
                for(;;){
                    i64t av=foldConst(parseExpr().get());
                    ic.args.push_back(av);
                    call->args.push_back(mkInt(av));
                    if (!accept(Tok::Comma)) break;
                }
            }
            expect(Tok::RParen,"')'");
            expect(Tok::FatArrow,"'=>'");
            i64t expected=foldConst(parseExpr().get());
            expect(Tok::Semi,"';'");
            ic.expected=expected; ai.cases.push_back(ic);
            caseNo++;
            // __a = fn(args);  if __a != expected { print "intent NAME case K: expected E got A"; return K; }
            body.push_back(mkAssign("__a", std::move(call)));
            auto ifs=std::make_unique<Stmt>(); ifs->kind=StKind::If;
            ifs->expr=mkBin('n', mkVar("__a"), mkInt(expected));
            string prefix="intent "+iname+" case "+std::to_string(caseNo)+": expected ";
            ifs->body.push_back(mkSyscall1(mkStr(prog.addString(prefix))));
            ifs->body.push_back(mkSyscall1(mkInt(expected)));
            ifs->body.push_back(mkSyscall1(mkStr(prog.addString(" got "))));
            ifs->body.push_back(mkSyscall1(mkVar("__a")));
            ifs->body.push_back(mkSyscall1(mkStr(prog.addString("\n"))));
            ifs->body.push_back(mkReturn(mkInt(caseNo)));
            body.push_back(std::move(ifs));
        }
        expect(Tok::RBrace,"'}'");
        if (caseNo==0) perr("intent '"+iname+"' has no cases");
        body.push_back(mkReturn(mkInt(0)));
        f.body=std::move(body);
        ai.checkerFuncIdx=(int)prog.funcs.size();
        prog.funcs.push_back(std::move(f));
        prog.intents.push_back(std::move(ai));
    }
    // SC4 --check: synthesize a `main` that runs every intent's checker and returns the first
    // non-zero failing-case ordinal (0 = all pass). Replaces any user main, so --check works on
    // library modules with no main of their own. The checkers themselves print the counterexamples.
    void synthesizeCheckRunner(){
        for (size_t i=0;i<prog.funcs.size();i++){ if (prog.funcs[i].name=="main"){ prog.funcs.erase(prog.funcs.begin()+(long)i); break; } }
        Func m; m.name="main"; m.retType="i64";
        vector<StmtP> body;
        for (auto& ai:prog.intents){
            auto call=std::make_unique<Expr>(); call->kind=NodeKind::Call; call->name="__intent_"+ai.name;
            body.push_back(mkAssign("r", std::move(call)));
            auto ifs=std::make_unique<Stmt>(); ifs->kind=StKind::If;
            ifs->expr=mkBin('n', mkVar("r"), mkInt(0));
            ifs->body.push_back(mkReturn(mkVar("r")));
            body.push_back(std::move(ifs));
        }
        body.push_back(mkSyscall1(mkStr(prog.addString("all intents OK\n"))));
        body.push_back(mkReturn(mkInt(0)));
        m.body=std::move(body);
        prog.funcs.push_back(std::move(m));
    }
    void parseCode() { while (cur.kind==Tok::KwFunc) parseFunc(); }   // @CODE block

    vector<StmtP> parseBlock() {
        vector<StmtP> out;
        while (cur.kind!=Tok::RBrace && cur.kind!=Tok::End)
            out.push_back(parseStmt());
        expect(Tok::RBrace, "'}'");
        return out;
    }

    StmtP parseStmt() {
        auto s = std::make_unique<Stmt>();
        // `let name = expr ;`  /  `let name : type = expr ;`
        //
        // An EXPLICIT local declaration. Codegen is byte-for-byte identical to the
        // bare `name = expr ;` form -- assignment has always been the declaration in
        // ANCL and that does not change. `let` exists to record INTENT, which is the
        // one thing the compiler could not previously see:
        //
        //   a local that shadows a module-level scalar is CORRECT and common (33 sites
        //   in this tree use short names like `nl`, `q`, `sp`), but a bare assignment
        //   MEANT as a write to that global silently creates the shadow instead and the
        //   global is never written. Those two are indistinguishable without `let`, so
        //   the duplicate-@DATA check had to stay a warning and the scalar case could
        //   not be checked at all. With `let`, "I meant a new local" is sayable, and
        //   the shadow warning below can fire only on the ambiguous case.
        //
        // `let` is OPTIONAL everywhere. Nothing already written needs to change.
        if (cur.kind==Tok::KwLet) {
            advance();
            if (cur.kind!=Tok::Ident) perr("expected a name after `let`");
            string lname = cur.text; advance();
            if (cur.kind==Tok::Colon) {                       // let name : type = expr ;
                advance();
                Type t; parseTypeSize(nullptr,&t);
                localType[lname]=t;
            }
            expect(Tok::Assign, "'=' after a `let` name");
            s->kind = StKind::Assign; s->name = lname; s->isLet = true;
            s->expr = parseExpr();
            if (s->expr && s->expr->isFloat && !localType.count(lname)) { Type ft; ft.isFloat=true; localType[lname]=ft; }
            expect(Tok::Semi, "';'");
            return s;
        }
        if (cur.kind==Tok::KwIf) {
            advance();
            s->kind = StKind::If;
            s->expr = parseExpr();
            expect(Tok::LBrace, "'{'");
            s->body = parseBlock();
            if (cur.kind==Tok::KwElse) {
                advance();
                if (cur.kind==Tok::KwIf) {            // else if ...  -> nested if as the else body
                    s->elseBody.push_back(parseStmt());
                } else {
                    expect(Tok::LBrace, "'{'");
                    s->elseBody = parseBlock();
                }
            }
            return s;
        }
        if (cur.kind==Tok::KwLoop || cur.kind==Tok::KwWhile) {   // 'loop'/'while' are while-style
            advance();
            s->kind = StKind::Loop;
            s->expr = parseExpr();
            expect(Tok::LBrace, "'{'");
            s->body = parseBlock();
            return s;
        }
        if (cur.kind==Tok::KwBreak)    { advance(); expect(Tok::Semi,"';'"); s->kind=StKind::Break;    return s; }
        if (cur.kind==Tok::KwContinue) { advance(); expect(Tok::Semi,"';'"); s->kind=StKind::Continue; return s; }
        if (cur.kind==Tok::KwReturn) {
            advance();
            s->kind = StKind::Return;
            s->expr = parseExpr();
            expect(Tok::Semi, "';'");
            return s;
        }
        if (cur.kind==Tok::KwSyscall) {
            advance();
            if (cur.kind==Tok::LParen) {   // M1: raw syscall(nr, a0..a5); as an expression statement
                advance();
                auto call=std::make_unique<Expr>(); call->kind=NodeKind::Call; call->name="syscall";
                if (cur.kind!=Tok::RParen) { for(;;){ call->args.push_back(parseExpr()); if(!accept(Tok::Comma)) break; } }
                expect(Tok::RParen, "')'"); expect(Tok::Semi, "';'");
                s->kind = StKind::ExprStmt; s->expr = std::move(call);
                return s;
            }
            s->kind = StKind::Syscall;     // legacy print convenience: syscall N, <expr>...
            if (cur.kind!=Tok::Int) perr("expected syscall number");
            s->sysNo = cur.ival; advance();
            while (accept(Tok::Comma)) s->sysArgs.push_back(parseExpr());
            expect(Tok::Semi, "';'");
            return s;
        }
        // feature #5: `match` is CONTEXTUAL â€” a keyword only when followed by an identifier (the
        // scrutinee). `match = â€¦` / `match(â€¦)` / `match.f` keep `match` as an ordinary identifier.
        if (cur.kind==Tok::Ident && cur.text=="match") {
            Token save=cur; advance();
            if (cur.kind==Tok::Ident) return parseMatch();
            // not a match statement: fall through treating `match` as a normal identifier
            return parseIdentStmt(save.text);
        }
        // Ident => assignment ('=') or bare call statement ('(')
        if (cur.kind==Tok::Ident) {
            string name = cur.text; advance();
            return parseIdentStmt(name);
        }
        perr("unexpected token in statement");
        return s;
    }
    // the body of an Ident-led statement (assignment / call / typed decl / field-or-index store),
    // factored out so `match` can fall back to it when used as a plain identifier.
    StmtP parseIdentStmt(const string& name) {
        auto s = std::make_unique<Stmt>();
        {
            if (cur.kind==Tok::LParen) {
                advance();
                auto call = std::make_unique<Expr>();
                call->kind = NodeKind::Call; call->name = name;
                if (cur.kind!=Tok::RParen) {
                    for(;;){ call->args.push_back(parseExpr()); if(!accept(Tok::Comma)) break; }
                }
                expect(Tok::RParen, "')'");
                expect(Tok::Semi, "';'");
                s->kind = StKind::ExprStmt; s->expr = std::move(call);
                return s;
            }
            // feature #4: typed local declaration  `name : type = expr ;`
            if (cur.kind==Tok::Colon) {
                advance();
                Type t; parseTypeSize(nullptr,&t);
                localType[name]=t;
                expect(Tok::Assign, "'='");
                // `name : type = expr` is ALREADY an explicit declaration, so it carries the
                // same intent as `let` and must not trip the shadow warning below.
                s->kind = StKind::Assign; s->name = name; s->isLet = true;
                s->expr = parseExpr(); expect(Tok::Semi, "';'");
                return s;
            }
            // feature #4 (v1.1): typed-local field/index STORE, possibly chained:
            //   p.field = v ;   p.next.tag = v ;   a[i] = v ;   rows[i].field = v ;
            if (cur.kind==Tok::Dot || cur.kind==Tok::LBracket) {
                auto lt=localType.find(name);
                if (lt==localType.end())
                    perr("'"+name+"' is not a typed local (annotate it as `"+name+": *Struct` / `"+name+": *i32`)");
                s->kind = StKind::ExprStmt;
                s->expr = parseLvalueStore(mkVar(name), lt->second);
                return s;
            }
            s->kind = StKind::Assign;
            s->name = name;
            expect(Tok::Assign, "'='");
            s->expr = parseExpr();
            if (s->expr && s->expr->isFloat) { Type ft; ft.isFloat=true; localType[name]=ft; }  // infer f64 local from a float RHS
            expect(Tok::Semi, "';'");
            return s;
        }
        perr("unexpected token in statement");
        return s;
    }

    StmtP mkIf(ExprP cond, vector<StmtP> thenB, vector<StmtP> elseB){
        auto s=std::make_unique<Stmt>(); s->kind=StKind::If; s->expr=std::move(cond);
        s->body=std::move(thenB); s->elseBody=std::move(elseB); return s;
    }
    // feature #5: `match <var> { pat => { â€¦ }, â€¦ , _ => { â€¦ } }`
    //   sum-match (var is a *Sum local): dispatch on the tag, bind variant fields as locals.
    //   int-match (otherwise): dispatch on the variable's value (int literals / @DATA consts + `_`).
    // Desugars to a nested if/else-if chain wrapped in `if 1 { â€¦ }` (one Stmt; zero codegen change).
    StmtP parseMatch(){
        string scrut=cur.text; advance();                       // scrutinee identifier
        expect(Tok::LBrace,"'{'");
        auto lt=localType.find(scrut);
        bool sumMode = (lt!=localType.end() && lt->second.isSum);
        ASum* sm = sumMode ? &prog.sums[lt->second.sumName] : nullptr;

        struct Arm { i64t cmp; vector<StmtP> body; };
        vector<Arm> cases; vector<StmtP> defBody;

        while (cur.kind!=Tok::RBrace && cur.kind!=Tok::End){
            bool isDef=false; i64t cmp=0; SumVariant* var=nullptr; vector<string> binds;
            if (cur.kind==Tok::Ident && cur.text=="_"){ advance(); isDef=true; }
            else if (sumMode){
                if (cur.kind!=Tok::Ident) perr("expected variant name in match arm");
                string vn=cur.text; advance();
                auto vit=sm->variantIndex.find(vn);
                if (vit==sm->variantIndex.end()) perr("sum '"+sm->name+"' has no variant '"+vn+"'");
                var=&sm->variants[vit->second]; cmp=var->tag;
                if (accept(Tok::LParen)){
                    if (cur.kind!=Tok::RParen){ for(;;){ if(cur.kind!=Tok::Ident) perr("expected field binding name"); binds.push_back(cur.text); advance(); if(!accept(Tok::Comma)) break; } }
                    expect(Tok::RParen,"')'");
                }
                if (!binds.empty() && binds.size()!=var->fields.size()) perr("variant '"+var->name+"' has "+std::to_string(var->fields.size())+" field(s), not "+std::to_string(binds.size()));
            } else {
                cmp=foldConst(parseExpr().get());               // int-match: a constant pattern
            }
            expect(Tok::FatArrow,"'=>'");
            expect(Tok::LBrace,"'{'");
            vector<StmtP> body=parseBlock();
            if (var && !binds.empty()){                          // prepend  bind = load{w}(scrut + off);
                vector<StmtP> bound;
                for (size_t i=0;i<binds.size();i++){
                    const Type& ft=var->fields[i].second;
                    bound.push_back(mkAssign(binds[i], mkFieldLoad(ft, mkBin('+', mkVar(scrut), mkInt(var->foff[var->fields[i].first])), "sum variant field")));
                }
                for (auto& st:body) bound.push_back(std::move(st));
                body=std::move(bound);
            }
            accept(Tok::Comma);                                 // optional arm separator
            if (isDef) defBody=std::move(body);
            else { Arm a; a.cmp=cmp; a.body=std::move(body); cases.push_back(std::move(a)); }
        }
        expect(Tok::RBrace,"'}'");

        vector<StmtP> chainElse = std::move(defBody);           // innermost else = default arm (or empty)
        for (int i=(int)cases.size()-1;i>=0;i--){
            ExprP disc = sumMode ? mkCall1("load64", mkVar(scrut)) : mkVar(scrut);
            ExprP cond = mkBin('e', std::move(disc), mkInt(cases[i].cmp));   // 'e' == EqEq
            StmtP ifst = mkIf(std::move(cond), std::move(cases[i].body), std::move(chainElse));
            chainElse.clear(); chainElse.push_back(std::move(ifst));
        }
        return mkIf(mkInt(1), std::move(chainElse), {});        // `if 1 { â€¦ }` wrapper
    }

    // Expression with standard precedence:  compare < add/sub < mul/div < term
    // (The spec lists a flat grammar; real expressions need precedence so that
    //  e.g. `c == 0 - 1` means `c == (0-1)`, not `(c == 0) - 1`.)
    ExprP mkBin(char op, ExprP l, ExprP r){
        auto b=std::make_unique<Expr>(); b->kind=NodeKind::Binary; b->op=op;
        bool anyF = (l && l->isFloat) || (r && r->isFloat);          // f64 propagation
        bool isCmp = (op=='e'||op=='n'||op=='l'||op=='L'||op=='g'||op=='G');
        b->isFloat = anyF && !isCmp;                                  // arithmetic -> f64; compare -> int boolean
        b->lhs=std::move(l); b->rhs=std::move(r); return b;
    }
    // infix bitwise operators desugar to the existing intrinsic calls (no codegen change)
    ExprP mkCall(const string& nm, ExprP a, ExprP b){
        auto e=std::make_unique<Expr>(); e->kind=NodeKind::Call; e->name=nm;
        e->args.push_back(std::move(a)); e->args.push_back(std::move(b)); return e;
    }
    // small AST builders used to desugar `prompt` declarations into an ordinary function
    ExprP mkVar(const string& n){ auto e=std::make_unique<Expr>(); e->kind=NodeKind::Var; e->name=n; return e; }
    ExprP mkStr(int sid){ auto e=std::make_unique<Expr>(); e->kind=NodeKind::Str; e->strId=sid; return e; }
    ExprP mkCall1(const string& nm, ExprP a){ auto e=std::make_unique<Expr>(); e->kind=NodeKind::Call; e->name=nm; e->args.push_back(std::move(a)); return e; }
    StmtP mkAssign(const string& n, ExprP v){ auto s=std::make_unique<Stmt>(); s->kind=StKind::Assign; s->name=n; s->expr=std::move(v); return s; }
    StmtP mkExprStmt(ExprP e){ auto s=std::make_unique<Stmt>(); s->kind=StKind::ExprStmt; s->expr=std::move(e); return s; }
    StmtP mkReturn(ExprP e){ auto s=std::make_unique<Stmt>(); s->kind=StKind::Return; s->expr=std::move(e); return s; }
    ExprP mkInt(i64t v){ auto e=std::make_unique<Expr>(); e->kind=NodeKind::Int; e->ival=v; return e; }
    StmtP mkSyscall1(ExprP e){ auto s=std::make_unique<Stmt>(); s->kind=StKind::Syscall; s->sysNo=1; s->sysArgs.push_back(std::move(e)); return s; }   // SC4: `syscall 1, <expr>` (print)
    // feature #4 helpers: scalar width + the load/store intrinsic name for a width
    static int scalarWidth(const string& nm){
        if (nm=="i8") return 1; if (nm=="i16") return 2;
        if (nm=="i32"||nm=="f32") return 4;
        return 8;   // i64/f64/ptr/str/unknown
    }
    static const char* ldName(int w){ return w==1?"load8":w==2?"load16":w==4?"load32":"load64"; }
    static const char* stName(int w){ return w==1?"store8":w==2?"store16":w==4?"store32":"store64"; }
    // A struct field's Type carries isFloat (set for f64/f32 since parseStruct), but the
    // load/store intrinsic is chosen by WIDTH alone -- so an `f64` field became a plain
    // load64/store64 and the node stayed an int. stampExpr only marks a Call float when
    // the callee is a float-returning function, and load64 is not one, so an f64 field
    // read never reached XMM: `p.x = p.x * k` evaluated the product in XMM0 and then
    // stored whatever integer happened to be in RAX. `return p.x` printed
    // 4611686018427387904 (the raw bits of 2.0) instead of the number.
    //
    // This helper keeps the width-based intrinsic and simply STAMPS the node, so
    // codegen's load*/store* know to route through XMM0. A width-8 float is an f64
    // (movq: the 8 bytes ARE the value); a width-4 float is an f32 STORAGE field --
    // the load32/store32 arms widen with cvtss2sd / narrow with cvtsd2ss, and the
    // value computes as f64 like every float in the language. (f32 was REFUSED here
    // until 2026-08-05, when the emitters gained the conversions.)
    ExprP mkFieldLoad(const Type& ft, ExprP addr, const string& what){
        ExprP e = mkCall1(ldName(ft.width), std::move(addr));
        e->isFloat = ft.isFloat;
        return e;
    }
    // single-identifier type (param / data) -> Type (struct name => dottable; else a scalar)
    Type typeFromName(const string& nm){
        Type t;
        if (prog.sums.count(nm)) { t.isSum=true; t.sumName=nm; t.width=8; }    // feature #5: sum-typed param
        else if (prog.structs.count(nm)) { t.dottable=true; t.sname=nm; t.width=8; }
        else { t.width = scalarWidth(nm); if (nm=="f64"||nm=="f32") t.isFloat=true; }
        return t;
    }
    Type scalarType(int w){ Type t; t.width=w; return t; }   // a terminal (non-dottable, non-indexable) value
    // feature #4 v1.1: walk a chain of postfix `.field` / `[i]` operators, threading the running Type.
    // Unifying rule (like C): a step whose result is a scalar/pointer is a load; one whose result is a
    // struct/array is its ADDRESS (so the next `.`/`[` chains off it). `p.next.tag`, `rows[i].port`, `p.ports[i]`.
    ExprP parsePostfix(ExprP node, Type ct){
        for(;;){
            if (cur.kind==Tok::Dot){
                advance();
                if (cur.kind!=Tok::Ident) perr("expected field name after '.'");
                string fld=cur.text; advance();
                if (!ct.dottable) perr("cannot read '."+fld+"': preceding value is not a struct pointer");
                AStruct& st=prog.structs[ct.sname];
                auto fo=st.off.find(fld);
                if (fo==st.off.end()) perr("struct '"+ct.sname+"' has no field '"+fld+"'");
                const Type& ft=st.ftype[fld];
                ExprP addr=mkBin('+', std::move(node), mkInt(fo->second));
                if (ft.isAddr) node=std::move(addr);                       // nested struct / array field -> address
                else node=mkFieldLoad(ft, std::move(addr), "struct field");  // scalar / pointer field -> load
                ct=ft;
            } else if (cur.kind==Tok::LBracket){
                advance();
                ExprP idx=parseExpr();
                expect(Tok::RBracket,"']'");
                if (!ct.indexable) perr("value is not indexable (annotate `*i32`, or index a `*Struct`)");
                int stride = ct.dottable ? prog.structs[ct.sname].size : ct.elemSize;  // live size (handles self/forward *Struct)
                ExprP addr=mkBin('+', std::move(node), mkBin('*', std::move(idx), mkInt(stride)));
                if (ct.dottable){ node=std::move(addr); }                  // struct element -> address; ct stays a *Struct
                else {
                    Type et=scalarType(ct.elemWidth); et.isFloat=ct.elemFloat;
                    node=mkFieldLoad(et, std::move(addr), "array element");   // stamps float elems (f64 AND f32)
                    ct=et;
                }
            } else break;
        }
        return node;
    }
    // feature #4 v1.1: navigate a `.field`/`[i]` chain on the LHS of an assignment; the final step
    // (the one followed by `=`) becomes a store{w}. Intermediate steps load/address exactly as the rvalue path.
    ExprP parseLvalueStore(ExprP node, Type ct){
        for(;;){
            if (cur.kind==Tok::Dot){
                advance();
                if (cur.kind!=Tok::Ident) perr("expected field name after '.'");
                string fld=cur.text; advance();
                if (!ct.dottable) perr("cannot write '."+fld+"': preceding value is not a struct pointer");
                AStruct& st=prog.structs[ct.sname];
                auto fo=st.off.find(fld);
                if (fo==st.off.end()) perr("struct '"+ct.sname+"' has no field '"+fld+"'");
                const Type& ft=st.ftype[fld];
                ExprP addr=mkBin('+', std::move(node), mkInt(fo->second));
                if (cur.kind==Tok::Assign){                                // FINAL step -> store
                    if (ft.isAddr) perr("cannot assign to array/struct field '"+fld+"' directly");
                    advance();
                    ExprP v=parseExpr(); expect(Tok::Semi, "';'");
                    return mkCall(stName(ft.width), std::move(addr), std::move(v));
                }
                if (ft.isAddr) node=std::move(addr);                       // intermediate navigation
                else node=mkFieldLoad(ft, std::move(addr), "struct field");
                ct=ft;
            } else if (cur.kind==Tok::LBracket){
                advance();
                ExprP idx=parseExpr();
                expect(Tok::RBracket,"']'");
                if (!ct.indexable) perr("value is not indexable (annotate `*i32`, or index a `*Struct`)");
                int stride = ct.dottable ? prog.structs[ct.sname].size : ct.elemSize;  // live size (handles self/forward *Struct)
                ExprP addr=mkBin('+', std::move(node), mkBin('*', std::move(idx), mkInt(stride)));
                if (cur.kind==Tok::Assign){                                // FINAL step -> store
                    if (ct.dottable) perr("cannot assign to a struct element directly (store its fields)");
                    advance();
                    ExprP v=parseExpr(); expect(Tok::Semi, "';'");
                    return mkCall(stName(ct.elemWidth), std::move(addr), std::move(v));
                }
                if (ct.dottable) node=std::move(addr);                     // struct element -> address; ct stays
                else {
                    Type et=scalarType(ct.elemWidth); et.isFloat=ct.elemFloat;
                    node=mkFieldLoad(et, std::move(addr), "array element");
                    ct=et;
                }
            } else perr("expected '.', '[', or '=' in assignment target");
        }
    }
    // precedence:  ||  <  &&  <  |  <  ^  <  &  <  (== != < <= > >=)  <  (<< >>)  <  +/-  <  */%  <  unary  <  term
    ExprP parseExpr(){ return parseOr(); }
    ExprP parseOr(){
        ExprP l=parseAnd();
        while(cur.kind==Tok::OrOr){ advance(); l=mkBin('o',std::move(l),parseAnd()); }
        return l;
    }
    ExprP parseAnd(){
        ExprP l=parseBitOr();
        while(cur.kind==Tok::AndAnd){ advance(); l=mkBin('a',std::move(l),parseBitOr()); }
        return l;
    }
    ExprP parseBitOr(){
        ExprP l=parseBitXor();
        while(cur.kind==Tok::Pipe){ advance(); l=mkCall("bor",std::move(l),parseBitXor()); }
        return l;
    }
    ExprP parseBitXor(){
        ExprP l=parseBitAnd();
        while(cur.kind==Tok::Caret){ advance(); l=mkCall("bxor",std::move(l),parseBitAnd()); }
        return l;
    }
    ExprP parseBitAnd(){
        ExprP l=parseCompare();
        while(cur.kind==Tok::Amp){ advance(); l=mkCall("band",std::move(l),parseCompare()); }
        return l;
    }
    ExprP parseCompare(){
        ExprP l=parseShift();
        for(;;){ char op=0;
            switch(cur.kind){
                case Tok::EqEq: op='e'; break;  case Tok::Ne: op='n'; break;
                case Tok::Lt:   op='l'; break;  case Tok::Le: op='L'; break;
                case Tok::Gt:   op='g'; break;  case Tok::Ge: op='G'; break;
                default: op=0;
            }
            if(!op) break;
            advance(); l=mkBin(op,std::move(l),parseShift());
        }
        return l;
    }
    ExprP parseShift(){
        ExprP l=parseAdd();
        for(;;){ const char* nm=0;
            if(cur.kind==Tok::Shl)nm="shl"; else if(cur.kind==Tok::Shr)nm="shr"; else break;
            advance(); l=mkCall(nm,std::move(l),parseAdd());
        }
        return l;
    }
    ExprP parseAdd(){
        ExprP l=parseMul();
        for(;;){ char op=0;
            if(cur.kind==Tok::Plus)op='+'; else if(cur.kind==Tok::Minus)op='-'; else break;
            advance(); l=mkBin(op,std::move(l),parseMul());
        }
        return l;
    }
    ExprP parseMul(){
        ExprP l=parseTerm();
        for(;;){ char op=0;
            if(cur.kind==Tok::Star)op='*'; else if(cur.kind==Tok::Slash)op='/';
            else if(cur.kind==Tok::Percent)op='m'; else break;
            advance(); l=mkBin(op,std::move(l),parseTerm());
        }
        return l;
    }

    ExprP parseTerm() {
        auto e = std::make_unique<Expr>();
        if (cur.kind==Tok::Amp) {       // &name  -> address of function or data
            advance();
            if (cur.kind!=Tok::Ident) perr("expected name after '&'");
            e->kind=NodeKind::Addr; e->name=cur.text; advance(); return e;
        }
        if (cur.kind==Tok::Int) { e->kind=NodeKind::Int; e->ival=cur.ival; advance(); return e; }
        if (cur.kind==Tok::Float) { e->kind=NodeKind::Float; e->dval=cur.dval; e->isFloat=true; advance(); return e; }
        if (cur.kind==Tok::Minus) { // unary minus -> 0 - term  (float-aware: 0.0 - x for f64)
            advance();
            ExprP t = parseTerm();
            bool tf = (t && t->isFloat);
            auto z = std::make_unique<Expr>(); z->kind = tf?NodeKind::Float:NodeKind::Int; z->isFloat=tf;
            e->kind=NodeKind::Binary; e->op='-'; e->isFloat=tf; e->lhs=std::move(z); e->rhs=std::move(t); return e;
        }
        if (cur.kind==Tok::Bang) {  // logical not -> (term == 0)
            advance();
            ExprP t = parseTerm();
            auto z = std::make_unique<Expr>(); z->kind=NodeKind::Int; z->ival=0;
            e->kind=NodeKind::Binary; e->op='e'; e->lhs=std::move(t); e->rhs=std::move(z); return e;
        }
        if (cur.kind==Tok::Str) { e->kind=NodeKind::Str; e->strId=prog.addString(cur.text); advance(); return e; }
        if (cur.kind==Tok::LParen) { advance(); ExprP inner=parseExpr(); expect(Tok::RParen,"')'"); return inner; }
        if (cur.kind==Tok::KwSyscall) {  // M1: raw Linux syscall as an expression -> result in RAX
            advance();
            expect(Tok::LParen, "'(' after syscall (raw form: syscall(nr, a0..a5))");
            e->kind=NodeKind::Call; e->name="syscall";
            if (cur.kind!=Tok::RParen) { for(;;){ e->args.push_back(parseExpr()); if(!accept(Tok::Comma)) break; } }
            expect(Tok::RParen, "')'");
            return e;
        }
        if (cur.kind==Tok::Ident) {
            string name = cur.text; advance();
            if (name=="sizeof" && cur.kind==Tok::LParen) {    // sizeof(typespec) -> compile-time int
                advance();
                int sz=parseTypeSize(nullptr);
                expect(Tok::RParen,"')'");
                e->kind=NodeKind::Int; e->ival=sz; return e;
            }
            // feature #5: sum construction  SumName.Variant  or  SumName.Variant(args)
            if (cur.kind==Tok::Dot && prog.sums.count(name)) {
                advance();   // '.'
                if (cur.kind!=Tok::Ident) perr("expected variant name after '"+name+".'");
                string vn=cur.text; advance();
                ASum& sm=prog.sums[name];
                auto vit=sm.variantIndex.find(vn);
                if (vit==sm.variantIndex.end()) perr("sum '"+name+"' has no variant '"+vn+"'");
                size_t nfields=sm.variants[vit->second].fields.size();
                e->kind=NodeKind::Call; e->name="__sum_"+name+"_"+vn;
                if (accept(Tok::LParen)) {
                    if (cur.kind!=Tok::RParen) { for(;;){ e->args.push_back(parseExpr()); if(!accept(Tok::Comma)) break; } }
                    expect(Tok::RParen,"')'");
                }
                if (e->args.size()!=nfields) perr("variant '"+name+"."+vn+"' expects "+std::to_string(nfields)+" field(s)");
                return e;
            }
            // (1) StructName.field -> compile-time byte offset (single-level, unchanged)
            if (cur.kind==Tok::Dot && prog.structs.count(name)) {
                advance();
                if (cur.kind!=Tok::Ident) perr("expected field name after '.'");
                string fld=cur.text; advance();
                AStruct& st=prog.structs[name];
                auto fo=st.off.find(fld);
                if (fo==st.off.end()) perr("struct '"+name+"' has no field '"+fld+"'");
                e->kind=NodeKind::Int; e->ival=fo->second; return e;
            }
            // (2) feature #4 (v1.1): a typed local followed by a postfix `.field`/`[i]` chain
            if (cur.kind==Tok::Dot || cur.kind==Tok::LBracket) {
                auto lt=localType.find(name);
                if (lt==localType.end())
                    perr("'"+name+"' is not a typed local (annotate it as `"+name+": *Struct` / `"+name+": *i32`)");
                return parsePostfix(mkVar(name), lt->second);
            }
            if (cur.kind==Tok::LParen) { // call
                advance();
                e->kind=NodeKind::Call; e->name=name;
                if (cur.kind!=Tok::RParen) {
                    for(;;){ e->args.push_back(parseExpr()); if(!accept(Tok::Comma)) break; }
                }
                expect(Tok::RParen,"')'");
                return e;
            }
            e->kind=NodeKind::Var; e->name=name;
            { auto lt=localType.find(name); if (lt!=localType.end() && lt->second.isFloat) e->isFloat=true; }  // f64 local/param -> XMM path
            return e;
        }
        perr("expected expression term");
        return e;
    }
};

// ---------------------------------------------------------------------
// 4. x86-64 EMITTER  (machine-code encoder with labels + relocations)
// ---------------------------------------------------------------------
// Register numbering (matches x86-64 encoding):
enum Reg { RAX=0,RCX=1,RDX=2,RBX=3,RSP=4,RBP=5,RSI=6,RDI=7,R8=8,R9=9,R10=10,R11=11,R12=12,R13=13,R14=14,R15=15 };
static const char* regn[16] = {"rax","rcx","rdx","rbx","rsp","rbp","rsi","rdi","r8","r9","r10","r11","r12","r13","r14","r15"};

struct Fixup {
    size_t pos;     // file position of the 4-byte disp field within code buffer
    int    kind;    // 0=rel32->label, 1=rip->string, 2=rip->dataOff, 3=rip->IAT(import)
    long   target;  // labelId / stringId / dataOffset / importIndex
};

struct Emitter {
    vector<u8>     code;
    vector<long>   labelPos;     // -1 until placed
    vector<string> labelName;
    vector<Fixup>  fixups;
    vector<string> asmLines;     // human-readable listing

    int  newLabel(const string& nm){ labelPos.push_back(-1); labelName.push_back(nm); return (int)labelPos.size()-1; }
    void placeLabel(int id){ labelPos[id]=(long)code.size(); asmLines.push_back(labelName[id]+":"); }
    void note(const string& s){ asmLines.push_back("    "+s); }

    void b(u8 x){ code.push_back(x); }
    void d32(u32 v){ b(v&0xff); b((v>>8)&0xff); b((v>>16)&0xff); b((v>>24)&0xff); }
    void d64(u64 v){ for(int k=0;k<8;k++) b((v>>(8*k))&0xff); }
    void rex(int W,int R,int X,int B){ b(0x40 | (W<<3)|(R<<2)|(X<<1)|B); }

    // ModRM + optional SIB + disp32 for [base + disp]  (mod=10)
    void memOperand(int regField,int base,int disp){
        int rm = base & 7;
        b(0x80 | ((regField&7)<<3) | rm);
        if (rm==4) b(0x24);          // SIB: scale0 index=none base=rsp/r12
        d32((u32)disp);
    }

    // ---- moves ----
    void mov_ri(int r, i64t imm){                       // movabs r64, imm64
        rex(1,0,0, r>=8?1:0); b(0xB8 + (r&7)); d64((u64)imm);
        note(string("mov ")+regn[r]+", "+std::to_string(imm));
    }
    void mov_rr(int dst,int src){                        // mov r/m64,r64  (rm=dst,reg=src)
        rex(1, src>=8?1:0, 0, dst>=8?1:0); b(0x89); b(0xC0 | ((src&7)<<3) | (dst&7));
        note(string("mov ")+regn[dst]+", "+regn[src]);
    }
    void mov_rm(int dst,int base,int disp){              // load: mov r64,[base+disp]
        rex(1, dst>=8?1:0, 0, base>=8?1:0); b(0x8B); memOperand(dst,base,disp);
        note(string("mov ")+regn[dst]+", ["+regn[base]+"+"+std::to_string(disp)+"]");
    }
    void mov_mr(int base,int disp,int src){              // store: mov [base+disp],r64
        rex(1, src>=8?1:0, 0, base>=8?1:0); b(0x89); memOperand(src,base,disp);
        note(string("mov [")+regn[base]+"+"+std::to_string(disp)+"], "+regn[src]);
    }
    // store an immediate straight to memory: mov qword [base+disp], imm32 (sign-extended
    // to 64). Lever G2 uses it for `x = <constant>` into a stack local, which otherwise
    // costs a 10-byte movabs into RAX plus an 8-byte store; this is 12 bytes and one insn.
    void mov_mi32(int base,int disp,int32_t imm){
        rex(1,0,0, base>=8?1:0); b(0xC7); memOperand(0,base,disp); d32((u32)imm);
        note(string("mov qword [")+regn[base]+"+"+std::to_string(disp)+"], "+std::to_string(imm));
    }
    void mov_mr8(int base,int disp,int src){             // store byte: mov [base+disp],r8
        if (base>=8 || src>=8) rex(0, src>=8?1:0,0, base>=8?1:0);
        b(0x88); memOperand(src,base,disp);
        note(string("mov byte [")+regn[base]+"+"+std::to_string(disp)+"], "+regn[src]+"b");
    }
    void movzx_rm8(int dst,int base,int disp){           // movzx r64, byte[base+disp]
        rex(1, dst>=8?1:0,0, base>=8?1:0); b(0x0F); b(0xB6); memOperand(dst,base,disp);
        note(string("movzx ")+regn[dst]+", byte ["+regn[base]+"+"+std::to_string(disp)+"]");
    }
    void mov_r8i(int r,u8 imm){                          // mov r8, imm8
        if (r>=8) rex(0,0,0,1); b(0xB0+(r&7)); b(imm);
        note(string("mov ")+regn[r]+"b, "+std::to_string((int)imm));
    }
    void lea_rip(int dst,int kind,long target,const string& sym){ // lea r64,[rip+disp]
        rex(1, dst>=8?1:0,0,0); b(0x8D); b(0x00 | ((dst&7)<<3) | 0x05);
        fixups.push_back({code.size(),kind,target}); d32(0);
        note(string("lea ")+regn[dst]+", ["+sym+"]");
    }
    void lea_mem(int dst,int base,int disp){             // lea r64,[base+disp]
        rex(1, dst>=8?1:0,0, base>=8?1:0); b(0x8D); memOperand(dst,base,disp);
        note(string("lea ")+regn[dst]+", ["+regn[base]+"+"+std::to_string(disp)+"]");
    }

    // ---- ALU reg,reg ----
    void alu_rr(u8 opc,const char* mn,int dst,int src){
        rex(1, src>=8?1:0,0, dst>=8?1:0); b(opc); b(0xC0 | ((src&7)<<3)|(dst&7));
        note(string(mn)+" "+regn[dst]+", "+regn[src]);
    }
    void add_rr(int d,int s){ alu_rr(0x01,"add",d,s); }
    void sub_rr(int d,int s){ alu_rr(0x29,"sub",d,s); }
    void xor_rr(int d,int s){ alu_rr(0x31,"xor",d,s); }
    void and_rr(int d,int s){ alu_rr(0x21,"and",d,s); }
    void or_rr (int d,int s){ alu_rr(0x09,"or", d,s); }
    void cmp_rr(int a,int bb){ alu_rr(0x39,"cmp",a,bb); }
    void test_rr(int a,int bb){ alu_rr(0x85,"test",a,bb); }
    void imul_rr(int d,int s){ rex(1,d>=8?1:0,0,s>=8?1:0); b(0x0F); b(0xAF); b(0xC0|((d&7)<<3)|(s&7));
        note(string("imul ")+regn[d]+", "+regn[s]); }

    // imul r64, r/m64, imm32 (lever A rule 3).  add/sub/cmp with an immediate
    // already exist below as grp1_ri wrappers; only the 3-operand imul was missing.
    void imul_rri(int d,int s,int imm){
        // LEVER H (3). `0x6B /r ib` is the same 3-operand imul with a SIGN-EXTENDED
        // imm8 -- three bytes shorter, identical result in [-128,127]. Lever A's
        // rule 3 routes every `x * <const>` through here, and those constants are
        // overwhelmingly small (element strides, scale factors, powers of two).
        if (imm >= -128 && imm <= 127){
            rex(1, d>=8?1:0,0, s>=8?1:0); b(0x6B); b(0xC0|((d&7)<<3)|(s&7)); b((u8)(int8_t)imm);
            note(string("imul ")+regn[d]+", "+regn[s]+", "+std::to_string(imm));
            return;
        }
        rex(1, d>=8?1:0,0, s>=8?1:0); b(0x69); b(0xC0|((d&7)<<3)|(s&7)); d32((u32)imm);
        note(string("imul ")+regn[d]+", "+regn[s]+", "+std::to_string(imm));
    }
    void shl_cl(int r){ rex(1,0,0,r>=8?1:0); b(0xD3); b(0xC0|(4<<3)|(r&7)); note(string("shl ")+regn[r]+", cl"); }
    void shr_cl(int r){ rex(1,0,0,r>=8?1:0); b(0xD3); b(0xC0|(5<<3)|(r&7)); note(string("shr ")+regn[r]+", cl"); }

    // ---- sized memory load/store at [base+disp] ----
    void movzx_rm16(int dst,int base,int disp){           // movzx r64, word[base+disp]
        rex(1,dst>=8?1:0,0,base>=8?1:0); b(0x0F); b(0xB7); memOperand(dst,base,disp);
        note(string("movzx ")+regn[dst]+", word ["+regn[base]+"+"+std::to_string(disp)+"]");
    }
    void mov_r32m(int dst,int base,int disp){             // mov r32,[base+disp]  (zero-extends to 64)
        if (dst>=8||base>=8) rex(0,dst>=8?1:0,0,base>=8?1:0);
        b(0x8B); memOperand(dst,base,disp);
        note(string("mov ")+regn[dst]+"d, ["+regn[base]+"+"+std::to_string(disp)+"]");
    }
    void mov_mr16(int base,int disp,int src){             // mov word[base+disp], r16
        b(0x66); if (src>=8||base>=8) rex(0,src>=8?1:0,0,base>=8?1:0);
        b(0x89); memOperand(src,base,disp);
        note(string("mov word [")+regn[base]+"+"+std::to_string(disp)+"], "+regn[src]+"w");
    }
    void mov_mr32(int base,int disp,int src){             // mov dword[base+disp], r32
        if (src>=8||base>=8) rex(0,src>=8?1:0,0,base>=8?1:0);
        b(0x89); memOperand(src,base,disp);
        note(string("mov dword [")+regn[base]+"+"+std::to_string(disp)+"], "+regn[src]+"d");
    }
    // normalize a function's 32-bit return value in EAX to a full 64-bit RAX
    void movsxd_rax_eax(){ rex(1,0,0,0); b(0x63); b(0xC0); note("movsxd rax, eax"); }   // signed int
    void zext_eax(){ b(0x89); b(0xC0); note("mov eax, eax  ; zero-extend rax"); }        // unsigned

    // ---- ALU reg,imm32  (0x81 /ext) ----
    // LEVER H. `0x83 /ext ib` is the same operation with a SIGN-EXTENDED imm8:
    // identical result for anything in [-128,127], and three bytes shorter than
    // the `0x81 /ext id` form this always used to emit. Small immediates dominate
    // -- loop bounds, struct field offsets, tag values, +1/-1 -- so this is pure
    // size for zero semantic change: the CPU sign-extends the byte to 64 bits
    // exactly as it sign-extends the dword.
    void grp1_ri(int ext,const char* mn,int r,int32_t imm){
        if (imm >= -128 && imm <= 127){
            rex(1,0,0,r>=8?1:0); b(0x83); b(0xC0 | (ext<<3) | (r&7)); b((u8)(int8_t)imm);
            note(string(mn)+" "+regn[r]+", "+std::to_string(imm));
            return;
        }
        rex(1,0,0,r>=8?1:0); b(0x81); b(0xC0 | (ext<<3) | (r&7)); d32((u32)imm);
        note(string(mn)+" "+regn[r]+", "+std::to_string(imm));
    }
    void add_ri(int r,int32_t imm){ grp1_ri(0,"add",r,imm); }
    void sub_ri(int r,int32_t imm){ grp1_ri(5,"sub",r,imm); }
    // LEVER H (2). Comparing against zero is the single most common comparison in
    // the tree, and `test r,r` is one byte shorter still. The flags are
    // bit-identical for everything this compiler reads: both give CF=0, OF=0,
    // SF=sign(r), ZF=(r==0), PF=parity(low byte). Only AF differs (undefined for
    // TEST), and nothing here reads AF. The condition-code byte the caller pairs
    // with it is unchanged, so lever F's derived jump is unaffected.
    void cmp_ri(int r,int32_t imm){
        if (imm==0){ alu_rr(0x85,"test",r,r); return; }
        grp1_ri(7,"cmp",r,imm);
    }

    // out dx, al  -- the ONLY port I/O the compiler emits, used by the --target=bare
    // console to mirror output to COM1. Serial is the standard kernel debug channel:
    // VGA needs a screen, serial can be captured to a file by an emulator.
    void outb_dx_al(){ b(0xEE); note("out dx, al"); }
    void inb_al_dx(){ b(0xEC); note("in al, dx"); }

    void neg_r(int r){ rex(1,0,0,r>=8?1:0); b(0xF7); b(0xC0|(3<<3)|(r&7)); note(string("neg ")+regn[r]); }
    void idiv_r(int r){ rex(1,0,0,r>=8?1:0); b(0xF7); b(0xC0|(7<<3)|(r&7)); note(string("idiv ")+regn[r]); }
    void cqo(){ rex(1,0,0,0); b(0x99); note("cqo"); }
    void div_r(int r){ rex(1,0,0,r>=8?1:0); b(0xF7); b(0xC0|(6<<3)|(r&7)); note(string("div ")+regn[r]); }   // UNSIGNED rdx:rax / r

    // ---- setcc al + movzx rax,al ----
    void setcc_movzx(u8 cc,const char* mn){
        b(0x0F); b(cc); b(0xC0);                  // setcc al  (rm=al)
        rex(1,0,0,0); b(0x0F); b(0xB6); b(0xC0);  // movzx rax, al
        note(string(mn)+" al ; movzx rax, al");
    }

    // ---- SSE2 scalar-double (f64) for Phase: floating point -----------------
    // legacy mandatory prefix (66/F2/F3) first, then REX, then 0F, opcode, ModRM.
    void sse_rr(u8 pre,u8 op,const char* mn,int d,int s){
        b(pre); if(d>=8||s>=8) rex(0,d>=8?1:0,0,s>=8?1:0); b(0x0F); b(op);
        b(0xC0|((d&7)<<3)|(s&7));
        note(string(mn)+" xmm"+std::to_string(d)+", xmm"+std::to_string(s));
    }
    void addsd  (int d,int s){ sse_rr(0xF2,0x58,"addsd",  d,s); }
    void subsd  (int d,int s){ sse_rr(0xF2,0x5C,"subsd",  d,s); }
    void mulsd  (int d,int s){ sse_rr(0xF2,0x59,"mulsd",  d,s); }
    void divsd  (int d,int s){ sse_rr(0xF2,0x5E,"divsd",  d,s); }
    void sqrtsd (int d,int s){ sse_rr(0xF2,0x51,"sqrtsd", d,s); }
    void ucomisd(int d,int s){ sse_rr(0x66,0x2E,"ucomisd",d,s); }   // 66 0F 2E (unordered cmp -> flags)
    void movsd_xx(int d,int s){ sse_rr(0xF2,0x10,"movsd", d,s); }   // xmm <- xmm
    // f64 load/store at [base+disp]  (caller-side stack slots)
    void movsd_xm(int d,int base,int disp){                        // movsd xmm, [base+disp]   F2 0F 10
        b(0xF2); if(d>=8||base>=8) rex(0,d>=8?1:0,0,base>=8?1:0); b(0x0F); b(0x10); memOperand(d,base,disp);
        note(string("movsd xmm")+std::to_string(d)+", ["+regn[base]+"+"+std::to_string(disp)+"]");
    }
    void movsd_mx(int base,int disp,int s){                        // movsd [base+disp], xmm   F2 0F 11
        b(0xF2); if(s>=8||base>=8) rex(0,s>=8?1:0,0,base>=8?1:0); b(0x0F); b(0x11); memOperand(s,base,disp);
        note(string("movsd [")+regn[base]+"+"+std::to_string(disp)+"], xmm"+std::to_string(s));
    }
    // f32 STORAGE support: 4-byte single-precision moves + the width conversions.
    // f32 is a storage width only -- every value COMPUTES as f64; these four are
    // the entire machine surface of the feature (widen on load, narrow on store).
    void movss_xm(int d,int base,int disp){                        // movss xmm, [base+disp]   F3 0F 10
        b(0xF3); if(d>=8||base>=8) rex(0,d>=8?1:0,0,base>=8?1:0); b(0x0F); b(0x10); memOperand(d,base,disp);
        note(string("movss xmm")+std::to_string(d)+", ["+regn[base]+"+"+std::to_string(disp)+"]");
    }
    void movss_mx(int base,int disp,int s){                        // movss [base+disp], xmm   F3 0F 11
        b(0xF3); if(s>=8||base>=8) rex(0,s>=8?1:0,0,base>=8?1:0); b(0x0F); b(0x11); memOperand(s,base,disp);
        note(string("movss [")+regn[base]+"+"+std::to_string(disp)+"], xmm"+std::to_string(s));
    }
    void cvtss2sd(int d,int s){ sse_rr(0xF3,0x5A,"cvtss2sd",d,s); }   // single -> double
    void cvtsd2ss(int d,int s){ sse_rr(0xF2,0x5A,"cvtsd2ss",d,s); }   // double -> single (round to nearest)
    // int <-> double conversions
    void cvtsi2sd(int xd,int gs){                                  // cvtsi2sd xmm, r64   F2 REX.W 0F 2A
        b(0xF2); rex(1,xd>=8?1:0,0,gs>=8?1:0); b(0x0F); b(0x2A); b(0xC0|((xd&7)<<3)|(gs&7));
        note(string("cvtsi2sd xmm")+std::to_string(xd)+", "+regn[gs]);
    }
    void cvttsd2si(int gd,int xs){                                 // cvttsd2si r64, xmm (trunc)  F2 REX.W 0F 2C
        b(0xF2); rex(1,gd>=8?1:0,0,xs>=8?1:0); b(0x0F); b(0x2C); b(0xC0|((gd&7)<<3)|(xs&7));
        note(string("cvttsd2si ")+regn[gd]+", xmm"+std::to_string(xs));
    }
    // raw 64-bit move between GP and XMM (load a const: mov rax,bits; movq xmm,rax)
    void movq_xr(int xd,int gs){                                   // movq xmm, r64   66 REX.W 0F 6E
        b(0x66); rex(1,xd>=8?1:0,0,gs>=8?1:0); b(0x0F); b(0x6E); b(0xC0|((xd&7)<<3)|(gs&7));
        note(string("movq xmm")+std::to_string(xd)+", "+regn[gs]);
    }
    void movq_rx(int gd,int xs){                                   // movq r64, xmm   66 REX.W 0F 7E
        b(0x66); rex(1,xs>=8?1:0,0,gd>=8?1:0); b(0x0F); b(0x7E); b(0xC0|((xs&7)<<3)|(gd&7));
        note(string("movq ")+regn[gd]+", xmm"+std::to_string(xs));
    }

    // ---- control flow (rel32) ----
    void jmp(int label){ b(0xE9); fixups.push_back({code.size(),0,label}); d32(0); note("jmp "+labelName[label]); }
    void jcc(u8 cc,const char* mn,int label){ b(0x0F); b(cc); fixups.push_back({code.size(),0,label}); d32(0);
        note(string(mn)+" "+labelName[label]); }
    void je (int l){ jcc(0x84,"je",l); }
    void jne(int l){ jcc(0x85,"jne",l); }
    void jz (int l){ jcc(0x84,"jz",l); }
    void jnz(int l){ jcc(0x85,"jnz",l); }
    void jl (int l){ jcc(0x8C,"jl",l); }
    void jg (int l){ jcc(0x8F,"jg",l); }
    void jge(int l){ jcc(0x8D,"jge",l); }
    void jle(int l){ jcc(0x8E,"jle",l); }
    void jns(int l){ jcc(0x89,"jns",l); }
    // UNSIGNED below-or-equal. Added for the bare allocator's bound check, where the
    // operands are POINTERS and the signed forms would be the wrong comparison in
    // principle even though this heap sits far below 2^63. Emits nothing unless called,
    // and it is called only under --target=bare, so hosted codegen is byte-identical.
    void jbe(int l){ jcc(0x86,"jbe",l); }

    void call(int label){ b(0xE8); fixups.push_back({code.size(),0,label}); d32(0); note("call "+labelName[label]); }
    void call_import(int idx,const string& nm){ b(0xFF); b(0x15); fixups.push_back({code.size(),3,(long)idx}); d32(0);
        note("call ["+nm+"]"); }
    // --target=linux-dyn only: indirect call through the .got.plt slot for a dynamic (libc/.so) import,
    // resolved by ld.so at load under BIND_NOW. FF 15 rip-relative, fixup kind 4 -> ELFWriterDyn .got.plt.
    // Byte-shape is identical to call_import; only the fixup kind differs (never emitted for PE/static ELF).
    void call_dynimport(int idx,const string& nm){ b(0xFF); b(0x15); fixups.push_back({code.size(),4,(long)idx}); d32(0);
        note("call ["+nm+"@got.plt]"); }
    void call_rax(){ b(0xFF); b(0xD0); note("call rax"); }   // indirect call through a runtime pointer (callp / COM vtable)
    void syscallInsn(){ b(0x0F); b(0x05); note("syscall"); } // Linux x86-64 syscall (clobbers RCX, R11)
    void ret(){ b(0xC3); note("ret"); }

    // rip-relative loads from .data
    void mov_rdata(int dst,int dataOff,const string& sym){ // mov r64,[rip+dataOff]
        rex(1,dst>=8?1:0,0,0); b(0x8B); b(0x00|((dst&7)<<3)|0x05);
        fixups.push_back({code.size(),2,(long)dataOff}); d32(0);
        note(string("mov ")+regn[dst]+", ["+sym+"]");
    }
    void mov_data_r(int dataOff,int src,const string& sym){ // mov [rip+dataOff],r64
        rex(1,src>=8?1:0,0,0); b(0x89); b(0x00|((src&7)<<3)|0x05);
        fixups.push_back({code.size(),2,(long)dataOff}); d32(0);
        note(string("mov [")+sym+"], "+regn[src]);
    }
    void lea_data(int dst,int dataOff,const string& sym){ // lea r64,[rip+dataOff]
        rex(1,dst>=8?1:0,0,0); b(0x8D); b(0x00|((dst&7)<<3)|0x05);
        fixups.push_back({code.size(),2,(long)dataOff}); d32(0);
        note(string("lea ")+regn[dst]+", ["+sym+"]");
    }
};

// ---------------------------------------------------------------------
// 5. CODEGEN
// ---------------------------------------------------------------------
struct Codegen {
    Program& prog;
    Emitter  em;

    // Imports: indices 0..3 MUST be GetStdHandle/WriteFile/ReadFile/ExitProcess
    // (the runtime helpers call them by those fixed indices).
    enum { IMP_GetStdHandle=0, IMP_WriteFile=1, IMP_ReadFile=2, IMP_ExitProcess=3 };
    std::map<string,string> importDll;          // master table: importable Win32 func -> dll
    vector<std::pair<string,string>> imports;   // actually-used imports; index == IAT slot id
    std::map<string,int> impIdx;
    int useImport(const string& fn){            // lazily add on first use; return IAT slot index
        auto it=impIdx.find(fn); if(it!=impIdx.end()) return it->second;
        int id=(int)imports.size(); imports.push_back({importDll[fn],fn}); impIdx[fn]=id; return id;
    }
    bool isImport(const string& n){ return importDll.count(n)!=0; }
    // ---- --target=linux-dyn dynamic imports (dlopen/dlsym/... via .rela.plt) ----
    // Parallel to imports/useImport, but resolved by ld.so through the ELF .got.plt (SysV ABI) instead of
    // the Win32 IAT. Populated lazily as dl* externs are called; ELFWriterDyn consumes it. Empty (and inert)
    // for PE and plain --target=linux -- keeps their output byte-identical (fixpoint-safe).
    vector<std::pair<string,string>> dynImports;   // {soname, fnname}; index == .dynsym(1+idx)/.got.plt(3+idx) slot
    std::map<string,int> dynIdx;
    int useDynImport(const string& fn){
        auto it=dynIdx.find(fn); if(it!=dynIdx.end()) return it->second;
        string so = prog.externs.count(fn) ? prog.externs[fn] : string("libc.so.6");
        int id=(int)dynImports.size(); dynImports.push_back({so,fn}); dynIdx[fn]=id; return id;
    }
    // Imports return a 32-bit int by default (sign-extend EAX->RAX so comparisons
    // against -1 / 0 work). Pointer/handle/LRESULT/SOCKET returns are true 64-bit
    // (leave RAX as-is); a few return unsigned 16/32-bit values (zero-extend).
    void extendRet(const string& nm){
        if (prog.externPtrRet.count(nm)) return;        // user FFI declared '-> ptr'
        // '-> f32': the import left a SINGLE in XMM0 -- widen it to the f64 every
        // float consumer expects. Before f32 storage landed this was silently read
        // as a double, i.e. garbage bits with a plausible-looking magnitude.
        if (prog.externFloat32Ret.count(nm)) { em.cvtss2sd(0,0); return; }
        if (prog.externFloatRet.count(nm)) return;      // '-> f64': result is in XMM0, RAX is meaningless
        static const char* ret64[]={"GetStdHandle","GetModuleHandleA","CreateWindowExA",
            "LoadCursorA","DefWindowProcA","DispatchMessageA","socket","accept","SetTimer",
            "GetProcessHeap","HeapAlloc",0};
        static const char* retU[]={"htons","GetTickCount","RegisterClassExA",0};
        for(int i=0;ret64[i];i++) if(nm==ret64[i]) return;
        for(int i=0;retU[i];i++)  if(nm==retU[i]){ em.zext_eax(); return; }
        em.movsxd_rax_eax();
    }
    void registerImports(){
        // master table - ONLY these three DLLs are linkable
        const char* k32[]={"GetStdHandle","WriteFile","ReadFile","ExitProcess",
            "GetModuleHandleA","GetTickCount","GetProcessHeap","HeapAlloc","HeapFree",
            "Sleep","GetLastError",0};
        const char* ws2[]={"WSAStartup","socket","bind","listen","accept","recv","send",
            "closesocket","ioctlsocket","htons",0};
        const char* u32[]={"RegisterClassExA","CreateWindowExA","ShowWindow","UpdateWindow",
            "GetMessageA","TranslateMessage","DispatchMessageA","DefWindowProcA",
            "SetWindowTextA","GetWindowTextA","PostQuitMessage","SetTimer","LoadCursorA",
            "MessageBoxA","KillTimer",0};
        for(int i=0;k32[i];i++) importDll[k32[i]]="kernel32.dll";
        for(int i=0;ws2[i];i++) importDll[ws2[i]]="ws2_32.dll";
        for(int i=0;u32[i];i++) importDll[u32[i]]="user32.dll";
        // the always-emitted runtime helpers reference these by fixed index 0..3
        useImport("GetStdHandle"); useImport("WriteFile"); useImport("ReadFile"); useImport("ExitProcess");
        // user-declared FFI imports (extern "dll" fn;)
        for (auto& kv : prog.externs) importDll[kv.first]=kv.second;
    }

    // .data layout: fixed stdin globals first, then user buffers appended.
    enum { DAT_INBUF=0, DAT_INLEN=256, DAT_INPOS=264, DAT_BASE=272, DAT_ARGV=272,
       // --target=bare only: VGA cursor + bump-allocator head, reserved at [272,296)
       DAT_VGA_ROW=272, DAT_VGA_COL=280, DAT_HEAP=288, DAT_HEAPEND=296, DAT_MBINFO=304 };  // DAT_ARGV: Linux-only slot holding the entry rsp (argc/argv); reserved at [272,280) ONLY under --target=linux
    int dataSize = DAT_BASE;
    bool subsystemGui = false;   // set true when the program creates a window
    bool targetLinux  = false;   // --target=linux: emit a static x86-64 ELF using Linux syscalls (no kernel32/IAT)
    // --target=bare (lever C): a FREESTANDING Multiboot image. No PE, no ELF, no loader,
    // no Win32, no libc, no OS at all -- the binary IS the kernel. print goes to the VGA
    // text buffer and alloc is a bump allocator over a static heap. This is the first rung
    // of the ANCL OS dream: the same codegen, with the bottom layer retargeted.
    std::set<string> warnedPortIO;   // warn once per name, not once per call site
    bool targetBare   = false;
    bool targetLinuxDyn = false; // --target=linux-dyn: additionally, a DYNAMIC ELF (PT_INTERP + libc dl* imports via .rela.plt/GOT under BIND_NOW). Implies targetLinux.

    // function/runtime labels
    std::map<string,int> funcLabel;
    std::map<string,int> funcArity;   // user function name -> declared param count (light type check)

    // ---- f64 signature threading (Win64 XMM calling convention) ----
    // The parser stamps the float-ness it can see lexically (literals, typed locals, local
    // inference); CALLS need the callee's signature, which may be declared later in the file.
    // So before emission a fixpoint pass walks every body: stamps Call nodes from the signature
    // tables, re-propagates Binary float-ness (mirroring mkBin), grows each function's float-local
    // set across assignments, and marks Assign targets so an int RHS converts into an f64 slot.
    std::map<string,vector<char>> funcParamFloat;   // user func -> per-param "is f64/f32"
    std::set<string> funcRetFloat;                  // user funcs + externs whose result is in XMM0
    std::set<string> dataFloat;                     // @DATA f64 consts (load as bits + movq -> XMM0)
    static bool typeIsFloat(const string& t){ return t=="f64"||t=="f32"; }
    static bool intrinRetFloat(const string& n){ return n=="sqrt"||n=="itof"||n=="ffrombits"; }
    bool paramIsFloat(const string& fn,int k){
        auto it=funcParamFloat.find(fn);
        if (it==funcParamFloat.end()) return false;            // import/helper: all-int params
        return k<(int)it->second.size() && it->second[k]!=0;
    }
    // Every name that is a LOCAL of the function currently being stamped: its
    // parameters plus every assignment target (assignment IS declaration in ANCL).
    // Mirrors collectNames(), which builds the same set for the frame layout.
    std::set<string> stampLocalNames;
    void collectLocalNames(const vector<StmtP>& body, std::set<string>& out){
        for (auto& s:body){
            if (s->kind==StKind::Assign) out.insert(s->name);
            if (s->kind==StKind::If){ collectLocalNames(s->body,out); collectLocalNames(s->elseBody,out); }
            if (s->kind==StKind::Loop) collectLocalNames(s->body,out);
        }
    }
    // Names this function declared EXPLICITLY with `let`.
    void collectLetNames(const vector<StmtP>& body, std::set<string>& out){
        for (auto& s:body){
            if (s->kind==StKind::Assign && s->isLet) out.insert(s->name);
            if (s->kind==StKind::If){ collectLetNames(s->body,out); collectLetNames(s->elseBody,out); }
            if (s->kind==StKind::Loop) collectLetNames(s->body,out);
        }
    }
    // ---- THE UNREAD-LOCAL WARNING -------------------------------------------
    // The typo half of the scoping class. `let` closed the case where a bare
    // assignment COLLIDES with module state; it does nothing for `cont = 5;` when
    // `count` was meant -- a fresh local appears, the intended one keeps its old
    // value, and nothing is said. A local written and never READ is the signature.
    //
    // MEASURED BEFORE BUILT, exactly as the shadow warning was, across 15 real
    // binaries and ~4,400 functions:
    //
    //   38 unread locals, of which 19 are `w = SomeCall(...)` -- the DELIBERATE
    //   discard idiom, which must never warn or this is noise on working code.
    //   The other 19 discard a PURE computation, and every one of them is
    //   genuinely dead. Three are a real bug (multi_tester computes an IEC-61850
    //   Functional Constraint from a combo box and never sends it).
    //
    // So: warn only when EVERY write to the name is a non-call expression. That
    // rule had a 0% false-positive rate on the tree it was measured against.
    void collectReadNames(const vector<StmtP>& body, std::set<string>& out){
        for (auto& s:body){
            if (s->expr) collectReadExpr(s->expr.get(), out);
            for (auto& a:s->sysArgs) collectReadExpr(a.get(), out);
            collectReadNames(s->body, out);
            collectReadNames(s->elseBody, out);
        }
    }
    void collectReadExpr(Expr* e, std::set<string>& out){
        if (!e) return;
        if (e->kind==NodeKind::Var || e->kind==NodeKind::Addr) out.insert(e->name);
        collectReadExpr(e->lhs.get(), out);
        collectReadExpr(e->rhs.get(), out);
        for (auto& a:e->args) collectReadExpr(a.get(), out);
    }
    // Is EVERY assignment to `nm` a discarded CALL result? `w = WSAStartup(..)` is the
    // deliberate-discard idiom and is not a typo; a discarded pure COMPUTATION is.
    bool allWritesAreCalls(const vector<StmtP>& body, const string& nm, bool& sawAny){
        bool ok = true;
        for (auto& s:body){
            if (s->kind==StKind::Assign && s->name==nm){
                sawAny = true;
                if (!s->expr || s->expr->kind!=NodeKind::Call) ok = false;
            }
            if (!allWritesAreCalls(s->body, nm, sawAny))     ok = false;
            if (!allWritesAreCalls(s->elseBody, nm, sawAny)) ok = false;
        }
        return ok;
    }
    void warnUnreadLocals(Func& f){
        std::set<string> writes; collectLocalNames(f.body, writes);
        std::set<string> reads;  collectReadNames(f.body, reads);
        std::set<string> params; for (auto& p:f.params) params.insert(p.name);
        for (auto& nm : writes){
            if (params.count(nm)) continue;          // a param is read by being passed
            if (reads.count(nm))  continue;
            bool sawAny=false;
            if (allWritesAreCalls(f.body, nm, sawAny) && sawAny) continue;   // deliberate discard
            warnDiag("anclc: warning: " + f.name + ": '" + nm +
                     "' is assigned but never read -- the value is computed "
                     "and thrown away. If another name was meant, this is that typo; if the "
                     "computation is dead, delete it.");
        }
    }
    // âš  THE SHADOW WARNING, and the reason it waited for `let`.
    //
    // A local that shadows a module-level scalar is CORRECT -- verified: the local wins
    // inside its function and the global is untouched elsewhere -- and it is common, with
    // 33 sites in this tree using short names like `nl`, `q`, `sp`, `b1`. So warning on
    // every shadow would have fired 33 times on working code: noise, and it would have
    // diluted the duplicate-@DATA warning that actually found two real bugs.
    //
    // The DANGEROUS case is the other intent: an assignment MEANT as a write to the
    // module-level scalar, which silently creates a local shadow instead and leaves the
    // global untouched. That is the documented PNG/DEFLATE bit-reader footgun. The two
    // are indistinguishable from the source -- which is exactly why lever B left the
    // scalar case unchecked.
    //
    // `let` resolves it: a declared local is deliberate and says nothing; a BARE
    // assignment that collides with a module-level scalar is the ambiguous one, and only
    // that fires. Fix it either by writing `let` (the local was intended) or by using a
    // `buf` + store64 (module state was intended -- scalar @DATA is immutable).
    void warnShadowedGlobals(Func& f){
        std::set<string> lets; collectLetNames(f.body, lets);
        std::set<string> warned;
        warnShadowWalk(f, f.body, lets, warned);
    }
    void warnShadowWalk(Func& f, const vector<StmtP>& body, std::set<string>& lets, std::set<string>& warned){
        for (auto& s:body){
            if (s->kind==StKind::Assign && !s->isLet && !lets.count(s->name) && !warned.count(s->name)){
                for (auto& d:prog.data){
                    if (d.name != s->name) continue;
                    if (d.isBuf) break;                  // already a hard error in collectNames
                    warned.insert(s->name);
                    warnDiag("anclc: warning: " + f.name + ": '" + s->name +
                             "' assigns a LOCAL that shadows the @DATA scalar '" + s->name +
                             "' -- the global is never written. Write `let " + s->name +
                             " = ...` if the local is intended, "
                             "or make the global a `buf` and use store64 for mutable module state.");
                    break;
                }
            }
            if (s->kind==StKind::If){ warnShadowWalk(f,s->body,lets,warned); warnShadowWalk(f,s->elseBody,lets,warned); }
            if (s->kind==StKind::Loop) warnShadowWalk(f,s->body,lets,warned);
        }
    }
    bool stampExpr(Expr* e, std::set<string>& fl){
        if(!e) return false;
        bool ch=false;
        switch(e->kind){
            case NodeKind::Var:
                // âš  A LOCAL SHADOWS A @DATA NAME, and the float stamping must not reach
                // through the shadow. This used to consult dataFloat for any name, so a
                // plain integer local that merely SHARED a name with a module-level f64
                // constant was stamped float on every read -- while lever D, which
                // consults only `fl`, still handed it a general-purpose register. Reads
                // then took genExpr's `movsd [rsp+off]` branch against a slot nothing had
                // written: `scale = 5; t = t + scale;` under a module-level
                // `scale: f64 = 2.5` printed 0 instead of 20, silently, no diagnostic.
                // Modules merge flat here and short names collide constantly (see the
                // FOOTGUN 2 note in collectNames), so this was reachable in real code.
                if(!e->isFloat && (fl.count(e->name) ||
                                   (!stampLocalNames.count(e->name) && dataFloat.count(e->name)))){
                    e->isFloat=true; ch=true;
                }
                break;
            case NodeKind::Call:
                for (auto& a:e->args) ch |= stampExpr(a.get(), fl);
                if(!e->isFloat && (funcRetFloat.count(e->name) || intrinRetFloat(e->name))){ e->isFloat=true; ch=true; }
                break;
            case NodeKind::Binary: {
                ch |= stampExpr(e->lhs.get(), fl);
                ch |= stampExpr(e->rhs.get(), fl);
                bool anyF=(e->lhs&&e->lhs->isFloat)||(e->rhs&&e->rhs->isFloat);
                bool isCmp=(e->op=='e'||e->op=='n'||e->op=='l'||e->op=='L'||e->op=='g'||e->op=='G');
                // mirrors mkBin, except &&/|| never become float (they are 0/1 ints in codegen)
                if(anyF && !isCmp && e->op!='a' && e->op!='o' && !e->isFloat){ e->isFloat=true; ch=true; }
                break;
            }
            default: break;
        }
        return ch;
    }
    bool stampStmt(Stmt* s, std::set<string>& fl){
        bool ch=false;
        switch(s->kind){
            case StKind::Assign:
                ch |= stampExpr(s->expr.get(), fl);
                if (s->expr && s->expr->isFloat && !fl.count(s->name)){ fl.insert(s->name); ch=true; }
                if (fl.count(s->name) && !s->targetFloat){ s->targetFloat=true; ch=true; }
                break;
            case StKind::Return: case StKind::ExprStmt:
                ch |= stampExpr(s->expr.get(), fl); break;
            case StKind::If:
                ch |= stampExpr(s->expr.get(), fl);
                for(auto&t:s->body)     ch|=stampStmt(t.get(),fl);
                for(auto&t:s->elseBody) ch|=stampStmt(t.get(),fl);
                break;
            case StKind::Loop:
                ch |= stampExpr(s->expr.get(), fl);
                for(auto&t:s->body) ch|=stampStmt(t.get(),fl);
                break;
            case StKind::Syscall:
                for(auto&a:s->sysArgs) ch|=stampExpr(a.get(),fl);
                break;
            default: break;
        }
        return ch;
    }
    void stampFloats(){
        for (auto& f:prog.funcs){
            vector<char> pf;
            for (auto& p:f.params) pf.push_back(typeIsFloat(p.type)?1:0);
            funcParamFloat[f.name]=pf;
            if (typeIsFloat(f.retType)) funcRetFloat.insert(f.name);
        }
        for (auto& nm:prog.externFloatRet) funcRetFloat.insert(nm);
        for (auto& d:prog.data) if (d.isFloat) dataFloat.insert(d.name);
        for (auto& f:prog.funcs){
            std::set<string> fl(f.floatLocals.begin(), f.floatLocals.end());
            for (auto& p:f.params) if (typeIsFloat(p.type)) fl.insert(p.name);
            stampLocalNames.clear();                         // the shadow set, for this function only
            for (auto& p:f.params) stampLocalNames.insert(p.name);
            collectLocalNames(f.body, stampLocalNames);
            warnShadowedGlobals(f);
            warnUnreadLocals(f);
            bool ch=true; int guard=0;                       // monotone -> terminates; guard is belt+braces
            while (ch && guard++<64){ ch=false; for (auto& st:f.body) ch|=stampStmt(st.get(),fl); }
            funcFloatLocals[f.name]=fl;   // lever D needs this: an f64 local can never live in a GP register
        }
    }
    int L_start=-1, L_print_str=-1, L_print_int=-1, L_getch=-1, L_read_char=-1, L_read_int=-1, L_int_to_str=-1, L_puts_cstr=-1, L_str_to_int=-1, L_str_copy=-1;
    int L_memcpy=-1, L_memset=-1, L_strlen=-1, L_strcmp=-1;

    std::map<string,std::set<string>> funcFloatLocals;   // per function: locals that hold f64

    // ===== LEVER D: register-resident locals =====
    // The frame is fixed and rsp-relative, so every local lived in memory and every use
    // was a load or a store. Here the hottest few locals in each function are promoted
    // into CALLEE-SAVED registers instead.
    //
    // Register choice is forced by portability, not preference: RBX/RBP/R12-R15 are the
    // only registers callee-saved in BOTH the Win64 and SysV ABIs, so the same choice is
    // correct for --target=windows, --target=linux AND --target=bare. RDI/RSI are
    // callee-saved on Windows but are ARGUMENT registers on SysV, so they are unusable.
    // RBP is left alone. Crucially the compiler emitted NONE of these registers before
    // this change, so nothing can collide with them.
    //
    // Callee-saved also means a promoted local SURVIVES A CALL for free -- no save/reload
    // around call sites, which is most of the win. In exchange the function must preserve
    // them for ITS caller, which the prologue/epilogue below do via reserved frame slots
    // (never push/pop -- this codegen relies on rsp staying fixed for the whole body).
    static const int NPROMO = 5;
    int promoRegs[NPROMO] = {RBX,R12,R13,R14,R15};
    std::map<string,int> localReg;    // local name -> physical register, when promoted
    int nPromoted = 0;                // how many of promoRegs[] this function uses
    int calleeSaveBase = 0;           // frame offset where the originals are parked

    // Weighted use count. A statement inside a loop is weighted heavily -- picking the
    // loop counter and accumulator is where nearly all of the benefit is.
    void countUses(Expr* e, std::map<string,long>& c, long w){
        if(!e) return;
        if (e->kind==NodeKind::Var) c[e->name]+=w;
        countUses(e->lhs.get(),c,w); countUses(e->rhs.get(),c,w);
        for(auto& a:e->args) countUses(a.get(),c,w);
    }
    void countUses(Stmt* s, std::map<string,long>& c, long w){
        if(!s) return;
        if (s->kind==StKind::Assign) c[s->name]+=w;
        long inner = (s->kind==StKind::Loop) ? w*8 : w;      // loop bodies dominate the profile
        // A loop CONDITION runs once per iteration, so it belongs at the inner weight --
        // otherwise the loop bound (`i < n`) looks cold and stays in memory while the
        // counter beside it gets a register.
        countUses(s->expr.get(), c, (s->kind==StKind::Loop) ? inner : w);
        for(auto& t:s->body)     countUses(t.get(),c,inner);
        for(auto& t:s->elseBody) countUses(t.get(),c,w);
        for(auto& a:s->sysArgs)  countUses(a.get(),c,w);
    }

    // per-function state
    std::map<string,int> localSlot;
    bool curRetFloat=false;   // current function returns f64 (drives Return conversion + fallthrough)
    int numLocals=0, scratchTop=0, scratchBaseOff=0, frameArgBase=32, frameN=0, retLabel=0;
    vector<std::pair<int,int>> loopStack;   // (continueLabel, breakLabel) for break/continue

    // ---- tool registry (feature #2): tools are ordinary funcs PLUS a discoverable JSON-Schema set ----
    vector<int> toolFuncIdx;            // prog.funcs indices that are `tool`s, in declaration order
    int         toolsJsonSid = -1;      // interned "[{schema},...]" array string id
    vector<int> toolNameSid, toolSchemaSid;   // per-tool interned name / schema-object string ids

    Codegen(Program& p):prog(p){}

    // ANCL type -> JSON-Schema type (author-written annotations, so no inference needed)
    static string jsonType(const string& t){
        if (t=="i8"||t=="i16"||t=="i32"||t=="i64") return "integer";
        if (t=="f32"||t=="f64") return "number";
        return "string";                 // str / ptr / struct* -> opaque "string"
    }
    static string jsonEsc(const string& s){
        string o;
        for (char c:s){
            unsigned char u=(unsigned char)c;
            if      (c=='"')  o+="\\\"";
            else if (c=='\\') o+="\\\\";
            else if (c=='\n') o+="\\n";
            else if (c=='\r') o+="\\r";
            else if (c=='\t') o+="\\t";
            else if (u<0x20){ char b[8]; snprintf(b,sizeof(b),"\\u%04x",u); o+=b; }
            else o+=c;
        }
        return o;
    }
    string toolSchemaJson(const Func& f){
        string s="{\"name\":\""+jsonEsc(f.name)+"\",\"description\":\""+jsonEsc(f.toolDesc)
                +"\",\"input_schema\":{\"type\":\"object\",\"properties\":{";
        for (size_t k=0;k<f.params.size();k++){ if(k) s+=",";
            s+="\""+jsonEsc(f.params[k].name)+"\":{\"type\":\""+jsonType(f.params[k].type)+"\"}"; }
        s+="},\"required\":[";
        for (size_t k=0;k<f.params.size();k++){ if(k) s+=","; s+="\""+jsonEsc(f.params[k].name)+"\""; }
        s+="]}}";
        return s;
    }
    // scan tools, synthesize their JSON, intern the strings (run() prologue, before label creation)
    void buildToolRegistry(){
        for (size_t i=0;i<prog.funcs.size();i++) if (prog.funcs[i].isTool) toolFuncIdx.push_back((int)i);
        if (toolFuncIdx.empty()) return;
        static const char* reserved[]={"tool_count","tools_json","tool_name","tool_schema","tool_fn",0};
        for (auto& f:prog.funcs) for (int r=0;reserved[r];r++) if (f.name==reserved[r])
            fail("'"+f.name+"' is reserved by the tool registry; rename your function");
        string arr="[";
        for (size_t k=0;k<toolFuncIdx.size();k++){
            const Func& f=prog.funcs[toolFuncIdx[k]];
            string js=toolSchemaJson(f);
            toolNameSid.push_back(prog.addString(f.name));
            toolSchemaSid.push_back(prog.addString(js));
            if (k) arr+=",";
            arr+=js;
        }
        arr+="]";
        toolsJsonSid=prog.addString(arr);
    }

    bool isDataStr(const string& n,int& strId,int& len){
        for (auto& d:prog.data) if(d.name==n && d.isStr){ strId=d.strId; len=(int)prog.strings[d.strId].size(); return true; }
        return false;
    }
    bool isDataInt(const string& n,i64t& v){
        for (auto& d:prog.data) if(d.name==n && !d.isStr && !d.isBuf){ v=d.ival; return true; }
        return false;
    }
    bool isDataFloat(const string& n,i64t& bits){   // f64 const: ival holds the IEEE-754 pattern
        for (auto& d:prog.data) if(d.name==n && d.isFloat){ bits=d.ival; return true; }
        return false;
    }
    bool isDataBuf(const string& n,int& off){
        for (auto& d:prog.data) if(d.name==n && d.isBuf){ off=d.dataOff; return true; }
        return false;
    }
    int localOff(int slot){ return frameArgBase + slot*8; }
    int scratchOff(int j){ return scratchBaseOff + j*8; }
    int allocScratch(){ return scratchTop++; }
    void freeScratch(int n){ scratchTop-=n; }

    // ---- frame layout: collect params + assigned identifiers ----
    void collectNames(const vector<StmtP>& body){
        for (auto& s:body){
            if (s->kind==StKind::Assign){
                // FOOTGUN 2: assigning to a @DATA name silently created a LOCAL that
                // SHADOWS it, so the store never reached the global -- "stores are
                // silently dropped". That cost a debug cycle on the PNG/DEFLATE work,
                // where the bit-reader kept its state in scalar @DATA globals and every
                // update no-op'd. Mutable module state must be a `buf` + load/store.
                if (!localSlot.count(s->name)){
                    // FOOTGUN 2 (partial): assigning to a @DATA BUFFER name is always a
                    // mistake -- the name is an ADDRESS, so the assignment silently
                    // created a local shadow and the buffer was never written.
                    //
                    // Deliberately NOT extended to scalar @DATA constants, even though
                    // that is the documented "stores are silently dropped" footgun (it
                    // cost a debug cycle on the PNG/DEFLATE bit-reader). ANCL has no
                    // local declaration syntax -- assignment IS the declaration -- so a
                    // function-local named `nl` is indistinguishable from an intended
                    // write to a module-level `nl: str`. Modules are merged flat, so
                    // short names collide constantly and erroring here rejects correct
                    // code (ai_core/anomalybrain/anomaly_features.ancl uses `nl` as a
                    // local while another merged module defines an `nl` string const).
                    // Catching the real case needs a language-level fix, not a check.
                    for (auto& d0 : prog.data)
                        if (d0.name == s->name && d0.isBuf)
                            fail("cannot assign to the @DATA buffer '"+s->name+"' (it is an address; use store64("+s->name+", value))");
                    localSlot[s->name]=numLocals++;
                }
            }
            if (s->kind==StKind::If){ collectNames(s->body); collectNames(s->elseBody); }
            if (s->kind==StKind::Loop){ collectNames(s->body); }
        }
    }

    // ---- compute max outgoing argument count (to size the stack frame) ----
    void scanExprArgs(Expr* e,int& mx){
        if(!e) return;
        if (e->kind==NodeKind::Call){
            static const char* inl[]={"load8","load16","load32","load64","store8","store16",
                "store32","store64","shl","shr","band","bor","bxor","read_int","read_char",
                "alloc","free","memcpy","memset","strlen","strcmp",
                "sqrt","ftoi","itof","fbits","ffrombits","syscall","__argv_base",
                "outb","inb","__mb_info",0};
            bool inlne=false; for(int i=0;inl[i];i++) if(e->name==inl[i]) inlne=true;
            if(!inlne){ int n=(int)e->args.size(); if(n>mx) mx=n; }
            for(auto& a:e->args) scanExprArgs(a.get(),mx);
        } else if (e->kind==NodeKind::Binary){
            scanExprArgs(e->lhs.get(),mx); scanExprArgs(e->rhs.get(),mx);
        }
    }
    void scanStmtArgs(Stmt* s,int& mx){
        if (s->kind==StKind::Assign||s->kind==StKind::Return||s->kind==StKind::ExprStmt) scanExprArgs(s->expr.get(),mx);
        else if (s->kind==StKind::If){ scanExprArgs(s->expr.get(),mx);
            for(auto&t:s->body)scanStmtArgs(t.get(),mx); for(auto&t:s->elseBody)scanStmtArgs(t.get(),mx); }
        else if (s->kind==StKind::Loop){ scanExprArgs(s->expr.get(),mx);
            for(auto&t:s->body)scanStmtArgs(t.get(),mx); }
        else if (s->kind==StKind::Syscall){ for(auto&a:s->sysArgs) scanExprArgs(a.get(),mx); }
    }

    // ---- assign .data offsets for declared buffers ----
    void assignBufferOffsets(){
        dataSize = DAT_BASE;
        if (targetBare)  dataSize += 40;  // VGA row/col + heap head + heap LIMIT + multiboot info ptr (bare only)
        if (targetLinux) dataSize += 8;   // reserve [DAT_ARGV,DAT_ARGV+8) for the entry-stack pointer (Linux only; Windows .data layout stays byte-identical)
        for (auto& d:prog.data){
            if (d.isBuf){
                d.dataOff = dataSize;
                int sz=(int)((d.bufSize+7)&~7); if(sz<8) sz=8;   // 8-byte align, min 8
                dataSize += sz;
            }
        }
    }

    // ---- expression -> result in RAX ----
    // =================================================================
    //  PEEPHOLE SUPPORT (lever A).
    //
    //  Historically EVERY binary operation went through the same shape:
    //      eval L -> rax ; spill rax to a stack scratch slot ; eval R -> rax ;
    //      mov rcx,rax ; reload L from the scratch slot ; <op> rax,rcx
    //  which is 6 instructions for something like `i + 1`.  The spill exists
    //  because genExpr always targets RAX and evaluating R would clobber L.
    //  But when R cannot clobber anything -- a literal, a local, a @DATA
    //  constant, an address -- the spill is pure waste: R can be materialized
    //  straight into RCX with one instruction.
    //
    //  Two rules are implemented, both of which preserve evaluation ORDER
    //  (L before R) and emit no new instruction encodings:
    //    1. constant folding  : `3 * 4`      -> mov rax,12
    //    2. no-clobber-leaf R : `s + i`      -> mov rax,[s] ; mov rcx,[i] ; add
    // =================================================================

    // Fold an integer expression built only from literals.  Deliberately
    // conservative: literals and operators over literals ONLY -- no variables,
    // so there is no question of reading a @DATA slot that a store might have
    // changed.  Returns false (and leaves `out` untouched) if not foldable.
    bool foldIntConst(Expr* e, i64t& out){
        if (!e || e->isFloat) return false;
        if (e->kind==NodeKind::Int){ out=e->ival; return true; }
        if (e->kind==NodeKind::Binary){
            if (e->op=='a' || e->op=='o') return false;          // &&/|| keep their 0/1 codegen
            i64t a,bb;
            if (!foldIntConst(e->lhs.get(),a)) return false;
            if (!foldIntConst(e->rhs.get(),bb)) return false;
            switch(e->op){
                case '+': out=a+bb; return true;
                case '-': out=a-bb; return true;
                case '*': out=a*bb; return true;
                case '/': if(bb==0) return false; out=a/bb; return true;   // never fold a trap
                case 'm': if(bb==0) return false; out=a%bb; return true;
                case 'e': out=(a==bb); return true;
                case 'n': out=(a!=bb); return true;
                case 'l': out=(a<bb);  return true;
                case 'L': out=(a<=bb); return true;
                case 'g': out=(a>bb);  return true;
                case 'G': out=(a>=bb); return true;
                default: return false;
            }
        }
        // infix bitwise (feature #1) desugars to intrinsic Call nodes, so fold those too
        if (e->kind==NodeKind::Call && e->args.size()==2){
            const string& nm=e->name;
            i64t a,bb;
            if (nm!="band" && nm!="bor" && nm!="bxor" && nm!="shl" && nm!="shr") return false;
            if (!foldIntConst(e->args[0].get(),a)) return false;
            if (!foldIntConst(e->args[1].get(),bb)) return false;
            if (nm=="band"){ out=a&bb; return true; }
            if (nm=="bor") { out=a|bb; return true; }
            if (nm=="bxor"){ out=a^bb; return true; }
            if (bb<0 || bb>63) return false;                     // UB shift: leave it to runtime
            if (nm=="shl") { out=(i64t)((uint64_t)a<<bb); return true; }
            out=(i64t)((uint64_t)a>>bb); return true;            // shr (logical, matches shr_cl)
        }
        return false;
    }

    // Can `e` be materialized into ANY register with one instruction and no
    // side effects?  Mirrors exactly the cases genExpr handles for Int/Str/
    // Var/Addr.  f64 is excluded: those go through XMM, not a GP register.
    bool isNoClobberLeaf(Expr* e){
        if (!e || e->isFloat) return false;
        int sid,len,boff; i64t v;
        switch(e->kind){
            case NodeKind::Int: return true;
            case NodeKind::Str: return true;
            case NodeKind::Var:
                // a float local is always stamped isFloat by stampFloats(), so the
                // `e->isFloat` guard above has already excluded those
                if (localSlot.count(e->name)) return true;
                if (isDataStr(e->name,sid,len)) return true;
                if (isDataBuf(e->name,boff))    return true;
                if (isDataFloat(e->name,v))     return false;    // f64 const -> XMM
                if (isDataInt(e->name,v))       return true;
                return false;                                    // unknown: let genExpr diagnose it
            case NodeKind::Addr:
                if (funcLabel.count(e->name))   return true;
                if (isDataStr(e->name,sid,len)) return true;
                if (isDataBuf(e->name,boff))    return true;
                return false;
            default: return false;
        }
    }

    // Materialize a no-clobber leaf into register `r` (byte-for-byte the same
    // instruction genExpr would emit, just with a different destination).
    void genLeafInto(Expr* e, int r){
        int sid,len,boff; i64t v;
        switch(e->kind){
            case NodeKind::Int: em.mov_ri(r, e->ival); return;
            case NodeKind::Str: em.lea_rip(r,1,e->strId,"str"+std::to_string(e->strId)); return;
            case NodeKind::Var:
                if (localReg.count(e->name)){ em.mov_rr(r, localReg[e->name]); return; }   // lever D
                if (localSlot.count(e->name)){ em.mov_rm(r,RSP,localOff(localSlot[e->name])); return; }
                if (isDataStr(e->name,sid,len)){ em.lea_rip(r,1,sid,"str"+std::to_string(sid)); return; }
                if (isDataBuf(e->name,boff)){ em.lea_data(r,boff,e->name); return; }
                if (isDataInt(e->name,v)){ em.mov_ri(r,v); return; }
                fail("undefined variable '"+e->name+"'");
            case NodeKind::Addr:
                if (funcLabel.count(e->name)){ em.lea_rip(r,0,funcLabel[e->name],e->name); return; }
                if (isDataStr(e->name,sid,len)){ em.lea_rip(r,1,sid,"str"+std::to_string(sid)); return; }
                if (isDataBuf(e->name,boff)){ em.lea_data(r,boff,e->name); return; }
                fail("cannot take address of '"+e->name+"'");
            default: fail("internal: genLeafInto called on a non-leaf");
        }
    }

    // LEVER F. When ccOut is non-null AND this node turns out to be a relational
    // comparison, we emit the cmp/ucomisd but NOT the setcc+movzx, and hand the
    // caller the setcc opcode byte instead. The caller then branches on the flags
    // directly. ccOut stays 0 for every other node -- including a comparison that
    // got constant-folded, where no cmp is emitted at all and the flags belong to
    // whatever ran last.
    //
    // It is a DEFAULTED parameter, so every recursive call below passes nullptr
    // implicitly: fusion can only ever be requested for the TOP node of a
    // condition, never for a subexpression whose value is actually needed.
    void genExpr(Expr* e, u8* ccOut){ genExprImpl(e, ccOut); }
    void genExpr(Expr* e){ genExprImpl(e, nullptr); }
    void genExprImpl(Expr* e, u8* ccOut){
        switch(e->kind){
            case NodeKind::Int: em.mov_ri(RAX, e->ival); return;
            case NodeKind::Float: {                                  // f64 literal: materialize IEEE-754 bits -> XMM0
                union { double d; i64t u; } cv; cv.d = e->dval;
                em.mov_ri(RAX, cv.u); em.movq_xr(0, RAX); return;
            }
            case NodeKind::Str: em.lea_rip(RAX,1,e->strId,"str"+std::to_string(e->strId)); return;
            case NodeKind::Var: {
                if (e->isFloat && localSlot.count(e->name)){ em.movsd_xm(0,RSP,localOff(localSlot[e->name])); return; }  // f64 local -> XMM0
                if (localReg.count(e->name)){ em.mov_rr(RAX, localReg[e->name]); return; }   // lever D
                if (localSlot.count(e->name)){ em.mov_rm(RAX,RSP,localOff(localSlot[e->name])); return; }
                int sid,len,boff; i64t v;
                if (isDataStr(e->name,sid,len)){ em.lea_rip(RAX,1,sid,"str"+std::to_string(sid)); return; }
                if (isDataBuf(e->name,boff)){ em.lea_data(RAX,boff,e->name); return; }     // buffer -> address
                if (isDataFloat(e->name,v)){ em.mov_ri(RAX,v); em.movq_xr(0,RAX); return; }  // f64 const -> XMM0 (checked before isDataInt: it matches too)
                if (isDataInt(e->name,v)){ em.mov_ri(RAX,v); return; }
                fail("undefined variable '"+e->name+"'");
            }
            case NodeKind::Addr: {
                if (funcLabel.count(e->name)){ em.lea_rip(RAX,0,funcLabel[e->name],e->name); return; } // &func
                int sid,len,boff;
                if (isDataStr(e->name,sid,len)){ em.lea_rip(RAX,1,sid,"str"+std::to_string(sid)); return; }
                if (isDataBuf(e->name,boff)){ em.lea_data(RAX,boff,e->name); return; }
                fail("cannot take address of '"+e->name+"'");
            }
            case NodeKind::Call: {
                const string& nm=e->name;
                int n=(int)e->args.size();
                if (nm=="read_int"){ em.call(L_read_int); return; }
                if (nm=="read_char"){ em.call(L_read_char); return; }
                // M1: raw Linux syscall.  syscall(nr, a0..a5) -> result in RAX.  Linux target only.
                if (nm=="syscall"){
                    if (!targetLinux) fail("raw syscall(nr, a0..a5) requires --target=linux (use `syscall 1, \"...\"` for portable print)");
                    if (n<1 || n>7) fail("syscall takes 1..7 args: the number + up to 6 arguments");
                    // evaluate each arg into its own scratch slot first (genExpr clobbers RAX/volatiles),
                    // then load the slots into the SYSCALL register order. NOTE: the 4th syscall arg is
                    // R10 (NOT RCX as in the function ABI); `syscall` (0F 05) also clobbers RCX and R11.
                    int sl[7];
                    for (int i=0;i<n;i++){ sl[i]=allocScratch(); genExpr(e->args[i].get()); em.mov_mr(RSP,scratchOff(sl[i]),RAX); }
                    static const int sreg[7]={RAX,RDI,RSI,RDX,R10,R8,R9};   // nr, a0, a1, a2, a3, a4, a5
                    for (int i=0;i<n;i++){ em.mov_rm(sreg[i],RSP,scratchOff(sl[i])); }
                    em.syscallInsn();
                    freeScratch(n);
                    return;                                                  // result already in RAX
                }
                // M4: __argv_base() -> the entry stack pointer captured at _start (Linux), i.e. &argc.
                // A liblinux.ancl GetCommandLineA shim reads argc = load64(__argv_base()) and
                // argv[i] = load64(__argv_base()+8+8*i). Linux target only.
                if (nm=="__argv_base"){
                    if (!targetLinux) fail("__argv_base() requires --target=linux");
                    if (n!=0) fail("__argv_base() takes no arguments");
                    em.mov_rdata(RAX, DAT_ARGV, "argv");
                    return;
                }
                if (nm=="puts_cstr"){ if(n!=1) fail("puts_cstr takes 1 arg");
                    genExpr(e->args[0].get()); em.mov_rr(RCX,RAX); em.call(L_puts_cstr); return; }
                if (nm=="str_to_int"){ if(n!=1) fail("str_to_int takes 1 arg");
                    genExpr(e->args[0].get()); em.mov_rr(RCX,RAX); em.call(L_str_to_int); return; }
                if (nm=="str_copy"){ if(n!=2) fail("str_copy takes 2 args");
                    genExpr(e->args[0].get()); int s=allocScratch(); em.mov_mr(RSP,scratchOff(s),RAX);
                    genExpr(e->args[1].get()); em.mov_rr(RDX,RAX); em.mov_rm(RCX,RSP,scratchOff(s));
                    em.call(L_str_copy); freeScratch(1); return; }
                // heap: alloc(n) = HeapAlloc(GetProcessHeap(), HEAP_ZERO_MEMORY, n)   [Windows]
                //               = mmap-backed block with an 8-byte length header     [Linux, M2]
                if (nm=="alloc"){ if(n!=1) fail("alloc takes 1 arg");
                    if (targetBare){
                        // Freestanding bump allocator: DAT_HEAP holds the next free address,
                        // initialised by the boot stub to the end of .bss. There is no OS to
                        // ask, and no free list -- free() is a no-op. Zeroed because the whole
                        // .bss region is zero-filled by the loader/stub.
                        genExpr(e->args[0].get());                       // RAX = n
                        em.add_ri(RAX,15);
                        em.mov_ri(RCX,(i64t)-16); em.and_rr(RAX,RCX);    // round up to 16
                        em.lea_data(R8,DAT_HEAP,"__heap");
                        em.mov_rm(RDX,R8,0);                             // rdx = current head
                        em.add_rr(RAX,RDX);                              // new head
                        // BOUND CHECK. Without it this was add-store-return: alloc(4 MB) on the
                        // 1 MB heap SUCCEEDED and returned a pointer past bss_end, and a store
                        // through it landed in whatever followed the image. Windows and Linux
                        // both return NULL when a request cannot be met, so bare was quietly
                        // breaking a contract every caller already relies on. Mirrors the mmap
                        // path's shape above: NULL on failure, head left untouched.
                        em.lea_data(R9,DAT_HEAPEND,"__heapend");
                        em.mov_rm(RCX,R9,0);                             // rcx = heap limit
                        {   int Lok  =em.newLabel(".balloc_ok"+std::to_string(em.code.size()));
                            int Ldone=em.newLabel(".balloc_done"+std::to_string(em.code.size()));
                            em.cmp_rr(RAX,RCX); em.jbe(Lok);             // new head <= limit -> fits
                            em.xor_rr(RAX,RAX); em.jmp(Ldone);           // OOM -> NULL, head untouched
                            em.placeLabel(Lok);
                            em.mov_mr(R8,0,RAX);                         // commit the new head
                            em.mov_rr(RAX,RDX);                          // return the OLD head
                            em.placeLabel(Ldone); }
                        return;
                    }
                    if (targetLinux){
                        // mmap(NULL, n+16, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0).
                        // store the mmap length in an 8-byte header so free() can munmap, return base+16
                        // (base is page-aligned -> base+16 stays 16-aligned and leaves room for the header).
                        // MAP_ANONYMOUS zero-fills, matching HEAP_ZERO_MEMORY.
                        genExpr(e->args[0].get());                          // RAX = n
                        em.add_ri(RAX,16);                                  // len = n + 16
                        int s=allocScratch(); em.mov_mr(RSP,scratchOff(s),RAX);   // save len
                        em.mov_rr(RSI,RAX);                                 // a1 = length
                        em.xor_rr(RDI,RDI);                                 // a0 = addr = NULL
                        em.mov_ri(RDX,3);                                   // a2 = PROT_READ|PROT_WRITE
                        em.mov_ri(R10,0x22);                                // a3 = MAP_PRIVATE|MAP_ANONYMOUS
                        em.mov_ri(R8,(i64t)-1);                             // a4 = fd = -1
                        em.xor_rr(R9,R9);                                   // a5 = offset = 0
                        em.mov_ri(RAX,9);                                   // sys_mmap
                        em.syscallInsn();                                   // RAX = base addr, or -errno
                        int Lok  =em.newLabel(".alloc_ok"+std::to_string(em.code.size()));
                        int Ldone=em.newLabel(".alloc_done"+std::to_string(em.code.size()));
                        em.test_rr(RAX,RAX); em.jns(Lok);                   // addr >= 0 -> success (errno is in [-4095,-1])
                        em.xor_rr(RAX,RAX); em.jmp(Ldone);                  // failure -> return NULL (preserves the 0-check convention)
                        em.placeLabel(Lok);
                        em.mov_rm(RCX,RSP,scratchOff(s));                   // len
                        em.mov_mr(RAX,0,RCX);                               // store64(base, len)
                        em.add_ri(RAX,16);                                  // user ptr = base + 16
                        em.placeLabel(Ldone);
                        freeScratch(1); return;
                    }
                    genExpr(e->args[0].get()); int s=allocScratch(); em.mov_mr(RSP,scratchOff(s),RAX);
                    em.call_import(useImport("GetProcessHeap"),"GetProcessHeap");   // rax = heap
                    em.mov_rr(RCX,RAX); em.mov_ri(RDX,8); em.mov_rm(R8,RSP,scratchOff(s));
                    em.call_import(useImport("HeapAlloc"),"HeapAlloc");             // rax = ptr (zeroed)
                    freeScratch(1); return; }
                if (nm=="free"){ if(n!=1) fail("free takes 1 arg");
                    if (targetBare){
                        genExpr(e->args[0].get());   // bump allocator: nothing to give back
                        em.xor_rr(RAX,RAX);
                        return;
                    }
                    if (targetLinux){
                        // munmap(p-16, header_len).  free(NULL) is a no-op.
                        genExpr(e->args[0].get());                          // RAX = p
                        int Ldone=em.newLabel(".free_done"+std::to_string(em.code.size()));
                        em.test_rr(RAX,RAX); em.jz(Ldone);                  // free(NULL) -> skip
                        em.sub_ri(RAX,16);                                  // base = p - 16
                        em.mov_rm(RSI,RAX,0);                               // a1 = length = load64(base)
                        em.mov_rr(RDI,RAX);                                 // a0 = addr = base
                        em.mov_ri(RAX,11);                                  // sys_munmap
                        em.syscallInsn();
                        em.placeLabel(Ldone);
                        return;
                    }
                    genExpr(e->args[0].get()); int s=allocScratch(); em.mov_mr(RSP,scratchOff(s),RAX);
                    em.call_import(useImport("GetProcessHeap"),"GetProcessHeap");
                    em.mov_rr(RCX,RAX); em.xor_rr(RDX,RDX); em.mov_rm(R8,RSP,scratchOff(s));
                    em.call_import(useImport("HeapFree"),"HeapFree");
                    freeScratch(1); return; }
                // mem/string runtime helpers (call by Win64 ABI into emitted routines)
                {
                    int hl=-1;
                    int want=-1;
                    if(nm=="memcpy"){hl=L_memcpy; want=3;} else if(nm=="memset"){hl=L_memset; want=3;}
                    else if(nm=="strlen"){hl=L_strlen; want=1;} else if(nm=="strcmp"){hl=L_strcmp; want=2;}
                    if(hl>=0){
                        // Audit #18: this was the ONE builtin group with no arity check in
                        // either compiler -- every neighbour has one. `memset(p, 0)` (length
                        // forgotten) emitted a call with R8 untouched, so __memset filled
                        // memory for whatever count was left in that register: heap corruption
                        // or a segfault, from a program that compiled clean and exited 0.
                        // Arguments past the 4th were evaluated, spilled, and dropped.
                        if(n!=want) fail(nm+" takes "+std::to_string(want)+(want==1?" arg":" args"));
                        vector<int> sl;
                        for(int k=0;k<n;k++){ genExpr(e->args[k].get()); int s=allocScratch(); sl.push_back(s); em.mov_mr(RSP,scratchOff(s),RAX); }
                        int ar[4]={RCX,RDX,R8,R9};
                        for(int k=0;k<n&&k<4;k++) em.mov_rm(ar[k],RSP,scratchOff(sl[k]));
                        em.call(hl); freeScratch(n); return;
                    }
                }
                // memory loads: load8/16/32/64(addr)
                if (nm=="load8"||nm=="load16"||nm=="load32"||nm=="load64"){
                    if(n!=1) fail(nm+" takes 1 arg");
                    genExpr(e->args[0].get());
                    // An f32 STORAGE field/element (mkFieldLoad stamped a width-4 float):
                    // the 4 bytes are a SINGLE, so an integer load + movq would hand the
                    // float path garbage bits. Widen through XMM instead; RAX gets the
                    // widened f64's bits, mirroring the load64-float contract below.
                    if (e->isFloat && nm=="load32"){
                        em.movss_xm(0,RAX,0); em.cvtss2sd(0,0); em.movq_rx(RAX,0);
                        return;
                    }
                    if(nm=="load8")       em.movzx_rm8(RAX,RAX,0);
                    else if(nm=="load16") em.movzx_rm16(RAX,RAX,0);
                    else if(nm=="load32") em.mov_r32m(RAX,RAX,0);
                    else                  em.mov_rm(RAX,RAX,0);
                    // An f64 struct field read (mkFieldLoad stamped the node): the loaded
                    // 8 bytes ARE the IEEE-754 value, but every float consumer expects it
                    // in XMM0, so move it across. Without this the value stayed in RAX and
                    // any arithmetic on it silently used the integer path.
                    if (e->isFloat) em.movq_xr(0,RAX);
                    return;
                }
                // memory stores: store8/16/32/64(addr,val)
                if (nm=="store8"||nm=="store16"||nm=="store32"||nm=="store64"){
                    if(n!=2) fail(nm+" takes 2 args");
                    genExpr(e->args[0].get()); int s=allocScratch(); em.mov_mr(RSP,scratchOff(s),RAX);
                    genExpr(e->args[1].get());
                    // Symmetric to the load: a float RHS left its result in XMM0, and RAX
                    // holds nothing meaningful. Storing RAX is exactly the bug -- it wrote
                    // a stale integer over the field.
                    if (e->args[1]->isFloat) em.movq_rx(RCX,0); else em.mov_rr(RCX,RAX);
                    em.mov_rm(RAX,RSP,scratchOff(s));
                    freeScratch(1);
                    // An f32 STORAGE store: narrow the f64 in XMM0 to a single, store the
                    // 4 bytes, then RE-WIDEN so XMM0/RAX carry the value AS STORED (the
                    // rounded one) -- deterministic for any consumer of the expression.
                    if (e->args[1]->isFloat && nm=="store32"){
                        em.cvtsd2ss(0,0); em.movss_mx(RAX,0,0); em.cvtss2sd(0,0); em.movq_rx(RAX,0);
                        return;
                    }
                    if(nm=="store8")       em.mov_mr8(RAX,0,RCX);
                    else if(nm=="store16") em.mov_mr16(RAX,0,RCX);
                    else if(nm=="store32") em.mov_mr32(RAX,0,RCX);
                    else                   em.mov_mr(RAX,0,RCX);
                    em.mov_rr(RAX,RCX);
                    return;
                }
                // bitwise / shift: shl/shr/band/bor/bxor(x,y)
                if (nm=="shl"||nm=="shr"||nm=="band"||nm=="bor"||nm=="bxor"){
                    if(n!=2) fail(nm+" takes 2 args");
                    // LEVER I.  The parser desugars infix `& | ^ << >>` into THESE
                    // intrinsic calls (parseBitOr/parseBitXor/parseBitAnd/parseShift),
                    // so they never reach the Binary switch and therefore never saw
                    // lever-A rule 2 -- while the self-hosted compiler, which keeps
                    // them as ND_BIN opcodes, has had it since lever A.  Measured
                    // cost of that asymmetry: -8.1% of .text across the ten
                    // bare-clean crypto/TLS gates, with `mov` the ONLY mnemonic whose
                    // count differed in all ten.  Same three-way dispatch as the
                    // Binary arm (see the rule 2 / 2b block below), and note the
                    // scratch slot is now allocated ONLY on the path that spills --
                    // an unconditional freeScratch(1) here would underflow the
                    // counter and corrupt an unrelated expression downstream.
                    if (isNoClobberLeaf(e->args[1].get())){
                        genExpr(e->args[0].get());                 // L -> rax
                        genLeafInto(e->args[1].get(), RCX);        // R -> rcx, one instruction
                    } else if (isNoClobberLeaf(e->args[0].get())){
                        // rule 2b: L is a side-effect-free leaf, so evaluating R
                        // first is observationally identical -- and skips the spill.
                        genExpr(e->args[1].get());                 // R -> rax
                        em.mov_rr(RCX,RAX);                        // R -> rcx
                        genLeafInto(e->args[0].get(), RAX);        // L -> rax
                    } else {
                        genExpr(e->args[0].get()); int s=allocScratch(); em.mov_mr(RSP,scratchOff(s),RAX);
                        genExpr(e->args[1].get()); em.mov_rr(RCX,RAX); em.mov_rm(RAX,RSP,scratchOff(s));
                        freeScratch(1);
                    }
                    if(nm=="shl")       em.shl_cl(RAX);
                    else if(nm=="shr")  em.shr_cl(RAX);
                    else if(nm=="band") em.and_rr(RAX,RCX);
                    else if(nm=="bor")  em.or_rr(RAX,RCX);
                    else                em.xor_rr(RAX,RCX);
                    return;
                }
                // ---- f64 intrinsics (SSE2, no DLL) ----
                // sqrt(x) -> f64 ; ftoi(x) f64 -> i64 truncate ; itof(n) i64 -> f64 ;
                // fbits(x) raw IEEE-754 bits as i64 (feeds numfmt's R8 formatter) ;
                // ffrombits(n) bits -> f64. Int args to sqrt/itof promote; float args
                // to ftoi/fbits pass through the appropriate converter/mov.
                if (nm=="sqrt"||nm=="ftoi"||nm=="itof"||nm=="fbits"||nm=="ffrombits"){
                    if(n!=1) fail(nm+" takes 1 arg");
                    genExpr(e->args[0].get());
                    bool af = e->args[0]->isFloat;
                    if (nm=="sqrt"){ if(!af) em.cvtsi2sd(0,RAX); em.sqrtsd(0,0); }
                    else if (nm=="ftoi"){ if(af) em.cvttsd2si(RAX,0); }            // already int: identity
                    else if (nm=="itof"){ if(!af) em.cvtsi2sd(0,RAX); }            // already f64: identity
                    else if (nm=="fbits"){ if(af) em.movq_rx(RAX,0); }             // int arg: its own bits
                    else /*ffrombits*/  { if(!af) em.movq_xr(0,RAX); }             // f64 arg: identity
                    return;
                }
                // ---- __mb_info() : the Multiboot information structure ----------------
                // BARE ONLY, and refused elsewhere -- unlike outb/inb there is nothing to
                // byte-compare across compilers here (it is one slot read that exists only
                // on this target), so the honest behaviour is to refuse rather than emit
                // something that reads a slot no other target reserves.
                if (nm=="__mb_info"){
                    if(n!=0) fail("__mb_info takes no arguments");
                    if(!targetBare) fail("__mb_info() is --target=bare only: it returns the Multiboot "
                                        "information pointer the boot loader passed in EBX, and no hosted "
                                        "target has one");
                    em.lea_data(RAX,DAT_MBINFO,"__mb_info");
                    em.mov_rm(RAX,RAX,0);
                    return;
                }
                // ---- PORT I/O: outb(port, value) / inb(port) -------------------------
                // The only privileged instructions ANCL can spell. They exist so a device
                // driver -- a UART, the PIT, the CRTC -- can be written in ORDINARY ANCL
                // rather than as compiler work per register. Together with user-func-wins
                // on bare (M2) that is what makes the driver layer a library campaign.
                //
                // NOT gated to --target=bare, deliberately, and it costs a warning instead:
                // the self-hosted compiler has no bare back end until M6, so refusing here
                // would leave its encodings untestable for a whole milestone. Compiling for
                // a hosted target lets diff_codegen TIER 3 byte-compare the two emitters
                // without ever running the result -- which is exactly the parity check the
                // invariant needs. Executing one outside ring 0 is a #GP, so say so.
                if (nm=="outb"||nm=="inb"){
                    if (!targetBare && !warnedPortIO.count(nm)){
                        warnedPortIO.insert(nm);
                        warnDiag("anclc: warning: " + nm + "() emits a PRIVILEGED instruction (" +
                                 (nm=="outb"?"out dx,al":"in al,dx") + ") and this is not "
                                 "--target=bare -- it will fault with #GP outside ring 0. Intended only for "
                                 "freestanding code, or for a compile-only parity probe.");
                    }
                    if (nm=="inb"){
                        if(n!=1) fail("inb takes 1 arg (port)");
                        genExpr(e->args[0].get());
                        em.mov_rr(RDX,RAX);
                        em.xor_rr(RAX,RAX);          // zero-extend: the port yields one BYTE
                        em.inb_al_dx();
                        return;
                    }
                    if(n!=2) fail("outb takes 2 args (port, value)");
                    genExpr(e->args[0].get()); int s=allocScratch(); em.mov_mr(RSP,scratchOff(s),RAX);
                    genExpr(e->args[1].get());
                    em.mov_rr(RCX,RAX);              // value
                    em.mov_rm(RDX,RSP,scratchOff(s));// port  (RDX, because OUT reads DX)
                    freeScratch(1);
                    em.mov_rr(RAX,RCX);              // AL = value
                    em.outb_dx_al();
                    em.xor_rr(RAX,RAX);              // outb() has no value; do not leak AL
                    return;
                }
                // int_to_str(addr,value)
                if (nm=="int_to_str"){
                    if(n!=2) fail("int_to_str takes 2 args");
                    genExpr(e->args[0].get()); int s0=allocScratch(); em.mov_mr(RSP,scratchOff(s0),RAX);
                    genExpr(e->args[1].get()); int s1=allocScratch(); em.mov_mr(RSP,scratchOff(s1),RAX);
                    em.mov_rm(RCX,RSP,scratchOff(s0));
                    em.mov_rm(RDX,RSP,scratchOff(s1));
                    em.call(L_int_to_str);
                    freeScratch(2);
                    return;
                }
                // callp(fnptr, args...) : indirect call through a RUNTIME pointer (COM vtable / GetProcAddress).
                // arg[0] is the target address; arg[1..] are passed by the Win64 ABI (RCX/RDX/R8/R9 + stack).
                // The 32-bit return is sign-extended (HRESULTs are 32-bit, so FAILED(hr) == hr < 0 works).
                if (nm=="callp"){
                    if(n<1) fail("callp needs a target pointer: callp(ptr, args...)");
                    int ncall=n-1;
                    vector<int> cs;
                    for(int k=0;k<n;k++){ genExpr(e->args[k].get()); int s=allocScratch(); cs.push_back(s); em.mov_mr(RSP,scratchOff(s),RAX); }
                    int cr[4]={RCX,RDX,R8,R9};
                    for(int j=0;j<ncall && j<4;j++) em.mov_rm(cr[j],RSP,scratchOff(cs[1+j]));
                    for(int j=4;j<ncall;j++){ em.mov_rm(RAX,RSP,scratchOff(cs[1+j])); em.mov_mr(RSP, 8*j, RAX); }
                    em.mov_rm(RAX,RSP,scratchOff(cs[0]));   // target pointer -> RAX
                    em.call_rax();
                    em.movsxd_rax_eax();                    // HRESULT / 32-bit int return -> sign-extended
                    freeScratch(n);
                    return;
                }
                // callpp(fnptr, args...) : identical to callp but the return is a full 64-bit
                // POINTER/handle, left in RAX UNCHANGED (no sign-extension). For indirect calls
                // that return a pointer the caller must keep intact - e.g. a GetProcAddress'd
                // wpcap pcap_open_live/pcap_next, or any allocator reached via a runtime pointer.
                if (nm=="callpp"){
                    if(n<1) fail("callpp needs a target pointer: callpp(ptr, args...)");
                    int ncall=n-1;
                    vector<int> cs;
                    for(int k=0;k<n;k++){ genExpr(e->args[k].get()); int s=allocScratch(); cs.push_back(s); em.mov_mr(RSP,scratchOff(s),RAX); }
                    int cr[4]={RCX,RDX,R8,R9};
                    for(int j=0;j<ncall && j<4;j++) em.mov_rm(cr[j],RSP,scratchOff(cs[1+j]));
                    for(int j=4;j<ncall;j++){ em.mov_rm(RAX,RSP,scratchOff(cs[1+j])); em.mov_mr(RSP, 8*j, RAX); }
                    em.mov_rm(RAX,RSP,scratchOff(cs[0]));   // target pointer -> RAX
                    em.call_rax();                          // RAX = full 64-bit return, kept as-is
                    freeScratch(n);
                    return;
                }
                // ---- tool registry accessors (feature #2) ----
                // tool_count() -> i64 ; tools_json() -> ptr ; tool_name|schema|fn(i) -> ptr (0 if oob)
                if (nm=="tool_count"){ if(n!=0) fail("tool_count takes 0 args");
                    em.mov_ri(RAX,(i64t)toolFuncIdx.size()); return; }
                if (nm=="tools_json"){ if(n!=0) fail("tools_json takes 0 args");
                    if(toolsJsonSid<0) fail("tools_json: no `tool` declarations in program");
                    em.lea_rip(RAX,1,toolsJsonSid,"tools_json"); return; }
                if (nm=="tool_name"||nm=="tool_schema"||nm=="tool_fn"){
                    if(n!=1) fail(nm+" takes 1 arg (tool index)");
                    if(toolFuncIdx.empty()) fail(nm+": no `tool` declarations in program");
                    genExpr(e->args[0].get());                  // index -> RAX
                    em.xor_rr(RCX,RCX);                          // RCX = result (0 = out-of-range default)
                    int Lend=em.newLabel(".tool_end"+std::to_string(em.code.size()));
                    for (size_t k=0;k<toolFuncIdx.size();k++){
                        int Lnx=em.newLabel(".tool_nx"+std::to_string(em.code.size()));
                        em.cmp_ri(RAX,(int32_t)k); em.jne(Lnx);
                        if      (nm=="tool_name")   em.lea_rip(RCX,1,toolNameSid[k],"tname");
                        else if (nm=="tool_schema") em.lea_rip(RCX,1,toolSchemaSid[k],"tschema");
                        else /*tool_fn*/            em.lea_rip(RCX,0,funcLabel[prog.funcs[toolFuncIdx[k]].name],"tfn");
                        em.jmp(Lend);
                        em.placeLabel(Lnx);
                    }
                    em.placeLabel(Lend);
                    em.mov_rr(RAX,RCX);                          // result -> RAX
                    return;
                }
                // general call: imported function OR user function (Win64 ABI, >4 args via stack)
                bool isImp=isImport(nm), isUser=funcLabel.count(nm)!=0;
                if(!isImp && !isUser) fail("call to undefined function '"+nm+"'");
                // Dispatch precedence: on Windows an import wins over a same-named user func (byte-identical
                // to before). On --target=linux there are NO imports in a static ELF, so a user-defined func
                // ALWAYS wins -- e.g. a core_lib/liblinux.ancl `func ReadFile(...)` IS the shim (M4). A
                // Windows-import name with NO such shim is a clean compile error, not a broken ELF.
                // BARE JOINS LINUX HERE, and it is the one line that decides whether the driver
                // layer is a LIBRARY campaign or an INTRINSIC one. User-func-wins is what makes
                // core_lib/liblinux.ancl possible: a `func ReadFile(...)` written in ANCL IS the
                // shim. Bare was excluded, so a user-defined ExitProcess was silently ignored,
                // the import was emitted anyway, and the failure surfaced much later in the
                // image writer with a message naming neither symbol nor line. Measured before
                // landing: with this flipped a bare program defining its own ExitProcess
                // compiles, boots, and prints from the user's function.
                bool callImport = (targetLinux || targetBare) ? false : isImp;
                bool callDynImport = false;
                if(targetLinux && isImp && !isUser){
                    // --target=linux-dyn: a user-declared `extern "libX.so" fn` (e.g. dlopen/dlsym) is a DYNAMIC
                    // import resolved by ld.so through .rela.plt/GOT (SysV ABI). Plain --target=linux keeps the
                    // original hard-fail EXACTLY (byte-identical), so its static-ELF fixpoint is untouched.
                    if(targetLinuxDyn && prog.externs.count(nm)) callDynImport = true;
                    else fail("--target=linux: '"+nm+"' is a Windows import with no Linux shim "
                         "(define it, e.g. in core_lib/liblinux.ancl, or use the raw syscall(...) primitive)");
                }
                // The same diagnostic for bare, AT THE CALL SITE, where the name and the line
                // are still known. It used to surface in the image writer as "a Windows import
                // fixup reached the image" -- true, useless, and it named neither.
                if(targetBare && isImp && !isUser)
                    fail("--target=bare: '"+nm+"' is a Windows import and there is no OS to import from "
                         "(define it, e.g. in core_lib/libbare.ancl -- a user `func "+nm+"(...)` wins over the import)");
                if(isUser && n!=funcArity[nm])
                    fail("function '"+nm+"' expects "+std::to_string(funcArity[nm])+" argument(s), got "+std::to_string(n));
                if(isImp && nm=="CreateWindowExA") subsystemGui=true;   // -> GUI subsystem
                // ================= LEVER E, PHASE 1: EVAL =================
                // Every argument used to be evaluated into RAX, spilled to a scratch slot,
                // and reloaded into its ABI register -- ten instructions for add3(i,2,3)
                // where four suffice. Measured across the self-hosted compiler: 6,883
                // spills + 8,119 reloads over 2,953 call sites, ~30% of all instructions.
                //
                // The safety argument rests on ANCL having no assignment-EXPRESSION, so the
                // only side-effecting expression node is a call. Every node that
                // isNoClobberLeaf accepts is therefore value-invariant across the evaluation
                // of any sibling argument: literals and &fn are compile-time constants; a
                // local can only be written by a STATEMENT and is non-addressable; and a
                // lever-D-promoted local lives in RBX/R12-R15, callee-saved under Win64 and
                // SysV alike.
                //
                // So a leaf may be SUNK past everything else. Phase 1 emits and spills ONLY
                // the non-leaves, in their original left-to-right order, preserving every
                // side effect. A leaf gets no slot at all and is materialised in phase 2.
                //
                // A leaf is disqualified when the callee declares that parameter f64: an int
                // leaf then needs cvtsi2sd out of RAX, so it takes the normal path.
                vector<int> slots(n, -1); vector<char> argf(n, 0); vector<char> leafArg(n, 0);
                int nSpilled = 0;
                for (int k=0;k<n;k++){
                    Expr* a=e->args[k].get();
                    if (isNoClobberLeaf(a) && !(isUser && paramIsFloat(nm,k))){
                        leafArg[k]=1; continue;                 // sunk to phase 2
                    }
                    genExpr(a);
                    // converge the arg onto the callee's declared param kind (C-style):
                    // int -> f64 param promotes, f64 -> int param truncates. Imports declare no
                    // param types, so a float arg to an import stays f64 (placed in XMM below).
                    bool pf = isUser && paramIsFloat(nm,k);
                    bool af = a->isFloat;
                    if (pf && !af){ em.cvtsi2sd(0,RAX); af=true; }
                    else if (!pf && af && isUser){ em.cvttsd2si(RAX,0); af=false; }
                    int s=allocScratch(); slots[k]=s; argf[k]=af?1:0; nSpilled++;
                    if (af) em.movsd_mx(RSP,scratchOff(s),0);
                    else    em.mov_mr(RSP,scratchOff(s),RAX);
                }
                if (callDynImport){
                    // System V AMD64: integer args in RDI,RSI,RDX,RCX,R8,R9 (NO 32B shadow space), overflow at
                    // [rsp+0..]. rsp is 16-aligned at the call here (genFunc prologue invariant, line ~2329),
                    // which is exactly the SysV alignment rule. The dl* callees take <=2 integer args; the
                    // general 6-reg+stack form is future-proof. No float args on this path (dl* are int/ptr).
                    // LEVER E, PHASE 2 -- SysV shape: SIX registers, and overflow at
                    // [rsp+8*(k-6)], NOT the Win64 four-and-[rsp+8k].
                    int sysvReg[6]={RDI,RSI,RDX,RCX,R8,R9};
                    for (int k=0;k<n && k<6;k++){
                        if (leafArg[k]) genLeafInto(e->args[k].get(), sysvReg[k]);
                        else            em.mov_rm(sysvReg[k],RSP,scratchOff(slots[k]));
                    }
                    for (int k=6;k<n;k++){
                        if (leafArg[k]) genLeafInto(e->args[k].get(), RAX);
                        else            em.mov_rm(RAX,RSP,scratchOff(slots[k]));
                        em.mov_mr(RSP, 8*(k-6), RAX);
                    }
                    em.xor_rr(RAX,RAX);                              // AL=0: zero vector regs passed (SysV varargs rule)
                    em.call_dynimport(useDynImport(nm), nm);
                    extendRet(nm);                                   // '-> ptr' externs keep the full 64-bit RAX
                    freeScratch(nSpilled);
                    return;
                }
                int argReg[4]={RCX,RDX,R8,R9};
                // Win64 is POSITIONAL: arg k rides XMMk if float, else GP reg k; stack args are just
                // bits. A float to an IMPORT also mirrors into the GP reg (the varargs convention -
                // harmless for fixed signatures, required for printf-style callees).
                // ================= LEVER E, PHASE 2: PLACE =================
                // Reached only after every instruction that could clobber a volatile
                // register -- crucially after any call emitted while evaluating a non-leaf
                // argument, since RCX/RDX/R8/R9 are all caller-saved. Placing a leaf at its
                // own argument position instead would let add3(i, side(i), 3) hand the
                // callee whatever the inner call happened to leave in RCX.
                //
                // The 5th-and-later slots are written HERE for that reason plus one more:
                // [rsp, argbase) is a single outgoing-argument area shared by EVERY call
                // this function makes, so an early write can be overwritten by an inner
                // call staging its own arguments.
                //
                // Order within this phase is free, and that is a property of the CURRENT
                // leaf predicate rather than of the scheme: no accepted leaf materialises
                // out of a volatile register (its sources are an immediate, a rip-relative
                // lea, [rsp+localOff], or a lever-D register RBX/R12-R15), none writes
                // memory, and each destination register is written exactly once. Widening
                // isNoClobberLeaf to anything read out of RAX/RCX/RDX/R8-R11 invalidates
                // that and would need a real ordering pass.
                for (int k=0;k<n && k<4;k++){
                    if (leafArg[k]){ genLeafInto(e->args[k].get(), argReg[k]); continue; }
                    if (argf[k]){
                        em.movsd_xm(k,RSP,scratchOff(slots[k]));
                        if (callImport) em.mov_rm(argReg[k],RSP,scratchOff(slots[k]));
                    }
                    else em.mov_rm(argReg[k],RSP,scratchOff(slots[k]));
                }
                for (int k=4;k<n;k++){
                    if (leafArg[k]) genLeafInto(e->args[k].get(), RAX);
                    else            em.mov_rm(RAX,RSP,scratchOff(slots[k]));
                    em.mov_mr(RSP, 8*k, RAX);
                }
                if (callImport){ em.call_import(useImport(nm), nm); extendRet(nm); }
                else            em.call(funcLabel[nm]);
                freeScratch(nSpilled);
                return;
            }
            case NodeKind::Binary: {
                // PEEPHOLE (lever A, rule 1): a wholly-constant subexpression becomes
                // one `mov rax, imm`.  Checked before everything else so that e.g.
                // `i * (4 * 8)` collapses its right side instead of emitting a
                // multiply chain.  &&/|| are excluded inside foldIntConst.
                { i64t cv;
                  if (!e->isFloat && foldIntConst(e,cv)){ em.mov_ri(RAX,cv); return; } }
                // short-circuit logical operators evaluate to 0/1 without computing both sides
                if (e->op=='a' || e->op=='o'){
                    int Lshort=em.newLabel(".sc_short"+std::to_string(em.code.size()));
                    int Lend  =em.newLabel(".sc_end"+std::to_string(em.code.size()));
                    genExpr(e->lhs.get()); em.test_rr(RAX,RAX);
                    if (e->op=='a') em.jz(Lshort); else em.jnz(Lshort);   // &&: short on false; ||: short on true
                    genExpr(e->rhs.get()); em.test_rr(RAX,RAX);
                    em.setcc_movzx(0x95,"setne");                          // normalize R to 0/1
                    em.jmp(Lend);
                    em.placeLabel(Lshort);
                    em.mov_ri(RAX, e->op=='a' ? 0 : 1);                    // &&->0, ||->1
                    em.placeLabel(Lend);
                    return;
                }
                // ---- f64 path: arithmetic with a float result, or a compare of float operands ----
                {
                    bool isCmp = (e->op=='e'||e->op=='n'||e->op=='l'||e->op=='L'||e->op=='g'||e->op=='G');
                    bool fcmp  = isCmp && ((e->lhs && e->lhs->isFloat) || (e->rhs && e->rhs->isFloat));
                    if (e->isFloat || fcmp){
                        genExpr(e->lhs.get());                            // L
                        if (!e->lhs->isFloat) em.cvtsi2sd(0,RAX);         // promote an int operand to f64
                        int s=allocScratch();
                        em.movsd_mx(RSP,scratchOff(s),0);                 // save L (xmm0)
                        genExpr(e->rhs.get());                            // R
                        if (!e->rhs->isFloat) em.cvtsi2sd(0,RAX);
                        em.movsd_xx(1,0);                                 // R -> xmm1
                        em.movsd_xm(0,RSP,scratchOff(s));                 // reload L -> xmm0
                        freeScratch(1);
                        switch(e->op){
                            case '+': em.addsd(0,1); break;
                            case '-': em.subsd(0,1); break;
                            case '*': em.mulsd(0,1); break;
                            case '/': em.divsd(0,1); break;
                            case 'm': fail("'%' is not defined for f64 operands"); break;
                            // ucomisd sets CF/ZF/PF -> UNSIGNED setcc (not signed setl/setg). NaN ignored in v1.
                            // âš  UNSIGNED condition codes: ucomisd reports through CF/ZF and
                            // CLEARS OF and SF. A signed cc here (setl/jge/...) is always-taken
                            // nonsense -- see tests/test_cmpbranch.ancl block C.
                            case 'e': em.ucomisd(0,1); if(ccOut){*ccOut=0x94;return;} em.setcc_movzx(0x94,"sete");  break;  // ==
                            case 'n': em.ucomisd(0,1); if(ccOut){*ccOut=0x95;return;} em.setcc_movzx(0x95,"setne"); break;  // !=
                            case 'l': em.ucomisd(0,1); if(ccOut){*ccOut=0x92;return;} em.setcc_movzx(0x92,"setb");  break;  // <
                            case 'L': em.ucomisd(0,1); if(ccOut){*ccOut=0x96;return;} em.setcc_movzx(0x96,"setbe"); break;  // <=
                            case 'g': em.ucomisd(0,1); if(ccOut){*ccOut=0x97;return;} em.setcc_movzx(0x97,"seta");  break;  // >
                            case 'G': em.ucomisd(0,1); if(ccOut){*ccOut=0x93;return;} em.setcc_movzx(0x93,"setae"); break;  // >=
                        }
                        return;
                    }
                }
                // PEEPHOLE (lever A, rule 3): a constant R that fits in imm32 goes
                // straight into the instruction -- no scratch register at all.
                {
                    bool opImmOk = (e->op=='+'||e->op=='-'||e->op=='*'||
                                    e->op=='e'||e->op=='n'||e->op=='l'||
                                    e->op=='L'||e->op=='g'||e->op=='G');
                    i64t iv;
                    if (opImmOk && foldIntConst(e->rhs.get(), iv) &&
                        iv >= -2147483648LL && iv <= 2147483647LL){
                        genExpr(e->lhs.get());                  // L -> rax
                        int im=(int)iv;
                        switch(e->op){
                            case '+': em.add_ri(RAX,im); return;
                            case '-': em.sub_ri(RAX,im); return;
                            case '*': em.imul_rri(RAX,RAX,im); return;
                            case 'e': em.cmp_ri(RAX,im); if(ccOut){*ccOut=0x94;return;} em.setcc_movzx(0x94,"sete");  return;
                            case 'n': em.cmp_ri(RAX,im); if(ccOut){*ccOut=0x95;return;} em.setcc_movzx(0x95,"setne"); return;
                            case 'l': em.cmp_ri(RAX,im); if(ccOut){*ccOut=0x9C;return;} em.setcc_movzx(0x9C,"setl");  return;
                            case 'L': em.cmp_ri(RAX,im); if(ccOut){*ccOut=0x9E;return;} em.setcc_movzx(0x9E,"setle"); return;
                            case 'g': em.cmp_ri(RAX,im); if(ccOut){*ccOut=0x9F;return;} em.setcc_movzx(0x9F,"setg");  return;
                            case 'G': em.cmp_ri(RAX,im); if(ccOut){*ccOut=0x9D;return;} em.setcc_movzx(0x9D,"setge"); return;
                        }
                    }
                }
                // PEEPHOLE (lever A, rule 2): when R cannot clobber L there is no
                // reason to round-trip L through the stack.  Evaluation order is
                // unchanged (L first, then R) -- only the spill/reload disappears.
                if (isNoClobberLeaf(e->rhs.get())){
                    genExpr(e->lhs.get());              // L -> rax
                    genLeafInto(e->rhs.get(), RCX);     // R -> rcx, one instruction
                } else if (isNoClobberLeaf(e->lhs.get())){
                    // rule 2b: L is a side-effect-free leaf, so evaluating R first is
                    // observationally identical -- and lets us skip the spill too.
                    genExpr(e->rhs.get());              // R -> rax
                    em.mov_rr(RCX,RAX);                 // R -> rcx
                    genLeafInto(e->lhs.get(), RAX);     // L -> rax
                } else {
                    genExpr(e->lhs.get());                 // L -> rax
                    int s=allocScratch();
                    em.mov_mr(RSP,scratchOff(s),RAX);      // save L
                    genExpr(e->rhs.get());                 // R -> rax
                    em.mov_rr(RCX,RAX);                    // R -> rcx
                    em.mov_rm(RAX,RSP,scratchOff(s));      // L -> rax
                    freeScratch(1);
                }
                switch(e->op){
                    case '+': em.add_rr(RAX,RCX); break;
                    case '-': em.sub_rr(RAX,RCX); break;
                    case '*': em.imul_rr(RAX,RCX); break;
                    case '/': em.cqo(); em.idiv_r(RCX); break;
                    case 'm': em.cqo(); em.idiv_r(RCX); em.mov_rr(RAX,RDX); break;  // remainder
                    case 'e': em.cmp_rr(RAX,RCX); if(ccOut){*ccOut=0x94;return;} em.setcc_movzx(0x94,"sete"); break;
                    case 'n': em.cmp_rr(RAX,RCX); if(ccOut){*ccOut=0x95;return;} em.setcc_movzx(0x95,"setne"); break;
                    case 'l': em.cmp_rr(RAX,RCX); if(ccOut){*ccOut=0x9C;return;} em.setcc_movzx(0x9C,"setl"); break;
                    case 'L': em.cmp_rr(RAX,RCX); if(ccOut){*ccOut=0x9E;return;} em.setcc_movzx(0x9E,"setle"); break;
                    case 'g': em.cmp_rr(RAX,RCX); if(ccOut){*ccOut=0x9F;return;} em.setcc_movzx(0x9F,"setg"); break;
                    case 'G': em.cmp_rr(RAX,RCX); if(ccOut){*ccOut=0x9D;return;} em.setcc_movzx(0x9D,"setge"); break;
                }
                return;
            }
        }
    }

    // LEVER F. Evaluate `cond` and jump to `lbl` when it is FALSE.
    //
    // Before this, EVERY condition went: <cmp> / setcc al ; movzx rax,al /
    // test rax,rax / jz -- four instructions where two do, and a five-link serial
    // dependency (cmp -> setcc -> movzx -> test -> jcc) on the critical path of
    // every loop. Measured across the self-hosted compiler's own listing: 1,694
    // such windows, 7.0% of the binary.
    //
    // The jump opcode is DERIVED from the setcc opcode the comparison itself
    // chose -- jcc = setcc - 0x10 -- rather than looked up from the operator.
    // That is what keeps f64 correct: its comparisons pick UNSIGNED codes after
    // ucomisd, and re-deriving from the operator would silently emit a signed
    // jump whose condition is always true. XOR 1 inverts any condition code, so
    // "jump when false" is one more arithmetic step, not a second table.
    //
    // cc == 0 means the condition was not a comparison at all (a call, a plain
    // local, a folded constant, an && / || result): the value is in RAX and the
    // flags mean nothing, so keep the old test+jz.
    static const char* ccName(u8 j){
        switch(j){ case 0x84: return "je";  case 0x85: return "jne";
                   case 0x8C: return "jl";  case 0x8D: return "jge";
                   case 0x8F: return "jg";  case 0x8E: return "jle";
                   case 0x82: return "jb";  case 0x83: return "jae";
                   case 0x87: return "ja";  case 0x86: return "jbe"; }
        return "jcc";
    }
    void genBranchFalse(Expr* cond, int lbl){
        u8 cc = 0;
        genExpr(cond, &cc);
        if (cc) { u8 j = (u8)((cc - 0x10) ^ 1); em.jcc(j, ccName(j), lbl); return; }
        em.test_rr(RAX,RAX);
        em.jz(lbl);
    }
    // =================================================================
    //  LEVER G2 -- assignment without the RAX funnel.
    //
    //  Every assignment used to evaluate its RHS into RAX and then move RAX to
    //  the destination, even when the RHS was a single leaf and the destination
    //  a lever-D register:
    //      x = 1        ->  mov rax, 1   ; mov rbx, rax
    //      x = x + 1    ->  mov rax, rbx ; add rax, 1 ; mov rbx, rax
    //      n = 0        ->  mov rax, 0   ; mov [rsp+N], rax      (10+8 bytes)
    //  In the compiler's own listing that is 913 + 256 + 449 sites -- 4.3% of
    //  ALL instructions -- and the last of the three is the only one that also
    //  removes a memory operand rather than just a register shuffle.
    //
    //  Returns true when it has emitted the whole assignment, false to fall
    //  back to the general evaluate-into-RAX path.  Deliberately narrow: only
    //  integer destinations, and only RHS shapes that isNoClobberLeaf() already
    //  certifies as side-effect-free and materializable in one instruction, so
    //  evaluation ORDER can never be observed to change.
    // =================================================================
    bool genAssignFast(Stmt* s){
        if (s->targetFloat) return false;                    // f64 slot: goes through XMM
        Expr* e = s->expr.get();
        if (!e || e->isFloat) return false;

        // ---- destination is a stack slot: only the constant store is a win ----
        if (!localReg.count(s->name)){
            if (!localSlot.count(s->name)) return false;
            i64t k;
            if (!foldIntConst(e,k)) return false;
            if (k < -2147483648LL || k > 2147483647LL) return false;   // needs the movabs
            em.mov_mi32(RSP, localOff(localSlot[s->name]), (int32_t)k);
            return true;
        }

        // ---- destination is a lever-D register ----
        int R = localReg[s->name];

        // x = <leaf>
        if (isNoClobberLeaf(e)){
            if (e->kind==NodeKind::Var && e->name==s->name) return true;   // x = x : nothing to do
            genLeafInto(e, R);
            return true;
        }

        // x = x <op> <leaf>, and for commutative ops also x = <leaf> <op> x.
        // Collapses a 4-instruction read-modify-write into one in-place ALU op,
        // which also shortens the dependency chain of every loop counter.
        if (e->kind!=NodeKind::Binary) return false;
        char op = e->op;
        if (op!='+' && op!='-' && op!='*') return false;      // '/'/'%' need RAX:RDX
        Expr* L = e->lhs.get(); Expr* Rr = e->rhs.get();
        if (!L || !Rr || L->isFloat || Rr->isFloat) return false;
        Expr* other = nullptr;
        if (L->kind==NodeKind::Var && L->name==s->name)                    other = Rr;
        else if ((op=='+'||op=='*') && Rr->kind==NodeKind::Var && Rr->name==s->name) other = L;
        if (!other || !isNoClobberLeaf(other)) return false;

        i64t k;
        if (foldIntConst(other,k) && k>=-2147483648LL && k<=2147483647LL){
            if      (op=='+') em.add_ri(R,(int32_t)k);
            else if (op=='-') em.sub_ri(R,(int32_t)k);
            else              em.imul_rri(R,R,(int32_t)k);
            return true;
        }
        // a register-resident local can be the source operand directly; anything
        // else is materialized into RCX, which is dead between statements
        int src;
        if (other->kind==NodeKind::Var && localReg.count(other->name)) src = localReg[other->name];
        else { genLeafInto(other, RCX); src = RCX; }
        if      (op=='+') em.add_rr(R,src);
        else if (op=='-') em.sub_rr(R,src);
        else              em.imul_rr(R,src);
        return true;
    }

    void genStmt(Stmt* s){
        switch(s->kind){
            case StKind::Assign: {
                if (genAssignFast(s)) return;                 // lever G2
                genExpr(s->expr.get());
                if (s->expr && s->expr->isFloat) em.movsd_mx(RSP,localOff(localSlot[s->name]),0);  // f64 result in XMM0
                else if (s->targetFloat){ em.cvtsi2sd(0,RAX); em.movsd_mx(RSP,localOff(localSlot[s->name]),0); }  // int RHS into an f64 slot
                else if (localReg.count(s->name)) em.mov_rr(localReg[s->name], RAX);   // lever D
                else                             em.mov_mr(RSP,localOff(localSlot[s->name]),RAX);
                return;
            }
            case StKind::ExprStmt: {
                genExpr(s->expr.get());   // evaluate for side effects; discard result
                return;
            }
            case StKind::Return: {
                genExpr(s->expr.get());
                // converge onto the declared return kind: f64 funcs return in XMM0, int funcs in RAX
                bool ef = s->expr && s->expr->isFloat;
                if      (curRetFloat && !ef) em.cvtsi2sd(0,RAX);
                else if (!curRetFloat && ef) em.cvttsd2si(RAX,0);
                em.jmp(retLabel);
                return;
            }
            case StKind::If: {
                // LEVER G1. An `if` with no `else` used to emit the full two-label shape
                // anyway:  jcc Lelse / body / jmp Lend / Lelse: / Lend:  -- where `jmp Lend`
                // targets the very next instruction. 1,481 such jumps in the compiler's own
                // listing (3.8% of ALL instructions), 5 bytes each, on a path where the
                // false branch already jumps to the same place. With no else body there is
                // nothing to skip over, so one label does the whole job.
                if (s->elseBody.empty()){
                    int Lend=em.newLabel(".Lendif"+std::to_string(em.code.size()));
                    genBranchFalse(s->expr.get(), Lend);
                    for (auto& st:s->body) genStmt(st.get());
                    em.placeLabel(Lend);
                    return;
                }
                int Lelse=em.newLabel(".Lelse"+std::to_string(em.code.size()));
                int Lend =em.newLabel(".Lendif"+std::to_string(em.code.size()));
                genBranchFalse(s->expr.get(), Lelse);
                for (auto& st:s->body) genStmt(st.get());
                em.jmp(Lend);
                em.placeLabel(Lelse);
                for (auto& st:s->elseBody) genStmt(st.get());
                em.placeLabel(Lend);
                return;
            }
            case StKind::Loop: {
                int Ltop=em.newLabel(".Ltop"+std::to_string(em.code.size()));
                int Lend=em.newLabel(".Lendlp"+std::to_string(em.code.size()));
                em.placeLabel(Ltop);
                genBranchFalse(s->expr.get(), Lend);
                loopStack.push_back({Ltop,Lend});       // continue->cond reeval, break->end
                for (auto& st:s->body) genStmt(st.get());
                loopStack.pop_back();
                em.jmp(Ltop);
                em.placeLabel(Lend);
                return;
            }
            case StKind::Break: {
                if (loopStack.empty()) fail("'break' outside of a loop");
                em.jmp(loopStack.back().second);
                return;
            }
            case StKind::Continue: {
                if (loopStack.empty()) fail("'continue' outside of a loop");
                em.jmp(loopStack.back().first);
                return;
            }
            case StKind::Syscall: {
                if (s->sysNo!=1) fail("only syscall 1 (print) is supported");
                for (auto& a:s->sysArgs){
                    // string argument? (data str var OR string literal) -> print as text
                    if (a->kind==NodeKind::Str){
                        int len=(int)prog.strings[a->strId].size();
                        em.lea_rip(RCX,1,a->strId,"str"+std::to_string(a->strId));
                        em.mov_ri(RDX,len);
                        em.call(L_print_str);
                        continue;
                    }
                    int sid,len;
                    if (a->kind==NodeKind::Var && isDataStr(a->name,sid,len)){
                        em.lea_rip(RCX,1,sid,"str"+std::to_string(sid));
                        em.mov_ri(RDX,len);
                        em.call(L_print_str);
                        continue;
                    }
                    // âš  An f64 operand here was SILENTLY WRONG in three different ways,
                    // and this is the path every test prints through:
                    //   syscall 1, <f64 local>    -> printed 1        (stale RAX; the
                    //                                value never left XMM0)
                    //   syscall 1, 4.5            -> 4616752568008179712  (the raw
                    //                                IEEE-754 bits, read as an integer)
                    //   syscall 1, <@DATA f64>    -> 4613374868287651840  (likewise)
                    // A test printing a plausible-looking integer that is actually
                    // nonsense is exactly the failure this project keeps paying for, so
                    // it is a hard error rather than a silent truncation: truncating
                    // would quietly discard the fraction the caller asked to see.
                    if (a->isFloat)
                        fail("syscall 1 cannot print an f64 -- it prints integers, and an "
                             "f64 operand would emit its raw IEEE-754 bits. Use ftoi(x) for "
                             "the truncated integer value.");
                    // otherwise integer expression -> print decimal
                    genExpr(a.get());
                    em.mov_rr(RCX,RAX);
                    em.call(L_print_int);
                }
                return;
            }
        }
    }

    void genFunc(Func& f){
        em.placeLabel(funcLabel[f.name]);
        localSlot.clear(); numLocals=0; scratchTop=0;
        curRetFloat = typeIsFloat(f.retType);
        for (size_t k=0;k<f.params.size();k++) localSlot[f.params[k].name]=numLocals++;
        collectNames(f.body);
        int maxArgs=4; for (auto& st:f.body) scanStmtArgs(st.get(),maxArgs);
        frameArgBase = (maxArgs<4?4:maxArgs)*8;            // outgoing-arg area (>=32B shadow), at [rsp,frameArgBase)
        scratchBaseOff = frameArgBase + numLocals*8;
        const int RESERVE_SCRATCH = 48;

        // ---- LEVER D: choose which locals live in registers ----
        // Eligibility is simple because ANCL has no way to take the address of a local
        // (`&name` only ever names a function or a @DATA object), so a local can NEVER be
        // aliased through a pointer -- there is no escape analysis to do. The only
        // exclusion is f64 locals, which live in XMM registers and move via movsd.
        localReg.clear(); nPromoted=0;
        {
            std::map<string,long> uses;
            for (auto& st:f.body) countUses(st.get(), uses, 1);
            const std::set<string>& fl = funcFloatLocals[f.name];
            vector<std::pair<long,string>> cand;
            for (auto& kv : localSlot){
                if (fl.count(kv.first)) continue;                 // f64 -> XMM, not a GP register
                long n = uses.count(kv.first) ? uses[kv.first] : 0;
                if (n >= 2) cand.push_back({n, kv.first});         // one use gains nothing
            }
            // Deterministic -- the self-host fixpoint would notice map iteration order
            // immediately -- AND IDENTICAL TO THE SELF-HOSTED COMPILER: by weight
            // descending, then by the local's SLOT INDEX, which is its order of first
            // appearance with parameters first.
            //
            // âš  THIS USED TO BREAK TIES BY NAME. cg_select_promotions() has always
            // broken them by the LOWER LOCAL INDEX (it takes the first maximum while
            // scanning slots ascending). Same weights, same candidate set, different
            // register assignment -- and r12/r13 are the ModRM SIB and RIP-relative
            // escapes, so they cost an extra byte as a base. That made the two
            // compilers emit different SIZES for identical source, and it was the last
            // cause of kernel-shaped parity divergence: exactly 20 bytes on 3 of the
            // 10 crypto gates, with identical instruction counts and mnemonics.
            //
            // Slot order is the better rule on its own merits, not just for parity:
            // under name order, RENAMING A LOCAL reshuffled register allocation.
            std::sort(cand.begin(), cand.end(), [this](const std::pair<long,string>& a, const std::pair<long,string>& b){
                if (a.first != b.first) return a.first > b.first;
                return localSlot.at(a.second) < localSlot.at(b.second);
            });
            for (size_t k=0; k<cand.size() && (int)k<NPROMO; k++){
                localReg[cand[k].second] = promoRegs[k];
                nPromoted = (int)k + 1;
            }
        }

        calleeSaveBase = frameArgBase + numLocals*8 + RESERVE_SCRATCH*8;
        frameN = calleeSaveBase + nPromoted*8;
        if ((frameN % 16)==0) frameN += 8;   // ensure rsp%16==0 at call sites
        retLabel = em.newLabel(".Lret_"+f.name);

        em.sub_ri(RSP, frameN);
        // preserve the callee-saved registers we are about to take over, for OUR caller
        for (int k=0;k<nPromoted;k++) em.mov_mr(RSP, calleeSaveBase + k*8, promoRegs[k]);
        // spill incoming params: first 4 from RCX/RDX/R8/R9 (f64 params ride XMM0-3, positional),
        // rest from the caller's stack
        int argReg[4]={RCX,RDX,R8,R9};
        for (size_t k=0;k<f.params.size() && k<4;k++){
            if (typeIsFloat(f.params[k].type)) em.movsd_mx(RSP, localOff((int)k), (int)k);
            else if (localReg.count(f.params[k].name))
                em.mov_rr(localReg[f.params[k].name], argReg[k]);      // straight into its register
            else                               em.mov_mr(RSP, localOff((int)k), argReg[k]);
        }
        for (size_t k=4;k<f.params.size();k++){
            em.mov_rm(RAX, RSP, frameN + 8 + 8*(int)k);   // [ret_addr(8) + shadow/args]
            if (localReg.count(f.params[k].name)) em.mov_rr(localReg[f.params[k].name], RAX);
            else                                  em.mov_mr(RSP, localOff((int)k), RAX);
        }

        for (auto& st:f.body) genStmt(st.get());

        // fallthrough safety: return 0 (an f64 func also zeroes XMM0)
        em.mov_ri(RAX,0);
        if (curRetFloat) em.movq_xr(0,RAX);
        em.placeLabel(retLabel);
        // hand the callee-saved registers back exactly as we found them. Every `return`
        // jumps to retLabel, so this one site covers all exit paths.
        for (int k=0;k<nPromoted;k++) em.mov_rm(promoRegs[k], RSP, calleeSaveBase + k*8);
        em.add_ri(RSP, frameN);
        em.ret();
    }

    // ============ runtime helper routines (hand-written) ============
    // __print_str(rcx=ptr, rdx=len) : WriteFile(GetStdHandle(-11), ptr, len, &n, 0)
    void emit_print_str(){
        em.placeLabel(L_print_str);
        if (targetBare){
            // Freestanding console: write straight into the VGA text buffer at 0xB8000.
            // Cursor row/col live in two reserved .data slots (DAT_VGA_ROW / DAT_VGA_COL).
            // 80x25, attribute 0x07 (grey on black). LF moves to the next row; the row
            // wraps at 25 (no scrolling in v1 -- that is a screenful of output, plenty to
            // prove the boot path).
            //   in: RCX = ptr, RDX = len
            em.mov_rr(RSI,RCX);                       // rsi = ptr
            em.mov_rr(RCX,RDX);                       // rcx = remaining
            int Ltop=em.newLabel(".vga_top"), Lend=em.newLabel(".vga_end");
            int Lnl =em.newLabel(".vga_nl"),  Lput=em.newLabel(".vga_put");
            int Lnowrap=em.newLabel(".vga_nowrap"), Lnorow=em.newLabel(".vga_norow");
            int Lnorow2=em.newLabel(".vga_norow2");
            em.placeLabel(Ltop);
            em.test_rr(RCX,RCX); em.jz(Lend);
            em.movzx_rm8(RAX,RSI,0);                  // al = *ptr
            em.add_ri(RSI,1);
            em.sub_ri(RCX,1);
            // mirror every byte to COM1 (0x3F8). QEMU/GRUB can capture serial to a file,
            // which is how a headless kernel is actually observed -- VGA needs a screen.
            em.mov_ri(RDX,0x3F8); em.outb_dx_al();
            em.cmp_ri(RAX,10); em.jne(Lput);          // LF?
            em.placeLabel(Lnl);
            em.lea_data(R8,DAT_VGA_COL,"__vga_col"); em.xor_rr(RDX,RDX); em.mov_mr(R8,0,RDX);   // col = 0
            em.lea_data(R8,DAT_VGA_ROW,"__vga_row"); em.mov_rm(RDX,R8,0); em.add_ri(RDX,1);
            em.cmp_ri(RDX,25); em.jne(Lnorow); em.xor_rr(RDX,RDX);
            em.placeLabel(Lnorow);
            em.mov_mr(R8,0,RDX);
            em.jmp(Ltop);
            em.placeLabel(Lput);
            // idx = row*80 + col ; addr = 0xB8000 + idx*2
            em.lea_data(R8,DAT_VGA_ROW,"__vga_row"); em.mov_rm(R9,R8,0);      // r9 = row
            em.mov_ri(R11,80); em.imul_rr(R9,R11);                            // r9 = row*80
            em.lea_data(R8,DAT_VGA_COL,"__vga_col"); em.mov_rm(R10,R8,0);     // r10 = col
            em.add_rr(R9,R10);
            em.add_rr(R9,R9);                                                 // *2 (2 bytes/cell)
            em.mov_ri(R11,0xB8000); em.add_rr(R9,R11);                        // r9 = cell addr
            em.mov_mr8(R9,0,RAX);                                             // character
            em.mov_ri(RDX,0x07); em.mov_mr8(R9,1,RDX);                        // attribute
            em.add_ri(R10,1);                                                 // col++
            em.cmp_ri(R10,80); em.jne(Lnowrap);
            em.xor_rr(R10,R10);
            em.lea_data(R8,DAT_VGA_ROW,"__vga_row"); em.mov_rm(RDX,R8,0); em.add_ri(RDX,1);
            em.cmp_ri(RDX,25); em.jne(Lnorow2); em.xor_rr(RDX,RDX);
            em.placeLabel(Lnorow2);
            em.mov_mr(R8,0,RDX);
            em.placeLabel(Lnowrap);
            em.lea_data(R8,DAT_VGA_COL,"__vga_col"); em.mov_mr(R8,0,R10);
            em.jmp(Ltop);
            em.placeLabel(Lend);
            em.ret();
            return;
        }
        if (targetLinux){
            // write(rdi=1 stdout, rsi=ptr, rdx=len) ; called with RCX=ptr, RDX=len
            em.mov_rr(RSI,RCX);                // rsi = ptr
            em.mov_ri(RDI,1);                  // fd = STDOUT_FILENO
            em.mov_ri(RAX,1);                  // sys_write  (rdx already = len)
            em.syscallInsn();
            em.ret();
            return;
        }
        em.sub_ri(RSP,72);
        em.mov_mr(RSP,48,RCX);                 // save ptr
        em.mov_mr(RSP,56,RDX);                 // save len
        em.mov_ri(RCX,(i64t)-11);              // STD_OUTPUT_HANDLE
        em.call_import(IMP_GetStdHandle,"GetStdHandle");
        em.mov_rr(RCX,RAX);                    // handle
        em.xor_rr(RAX,RAX);
        em.mov_mr(RSP,32,RAX);                 // 5th arg (lpOverlapped)=NULL
        em.mov_rm(RDX,RSP,48);                 // ptr
        em.mov_rm(R8,RSP,56);                  // len
        em.lea_mem(R9,RSP,40);                 // &bytesWritten
        em.call_import(IMP_WriteFile,"WriteFile");
        em.add_ri(RSP,72);
        em.ret();
    }

    // __print_int(rcx=value, signed) : itoa10 then __print_str
    void emit_print_int(){
        em.placeLabel(L_print_int);
        // frame: [0..32) shadow, [32..64) buffer, [64..72) value, [72..80) p, [80..88) isNeg
        em.sub_ri(RSP,88);
        em.mov_mr(RSP,64,RCX);                 // value
        em.xor_rr(RAX,RAX);
        em.mov_mr(RSP,80,RAX);                 // isNeg=0
        em.lea_mem(RAX,RSP,64);                // p = &buffer_end (=rsp+64)
        em.mov_mr(RSP,72,RAX);                 // p
        em.mov_rm(RAX,RSP,64);                 // value
        em.test_rr(RAX,RAX);
        int Lpos=em.newLabel(".pi_pos");
        em.jns(Lpos);
        em.mov_ri(RCX,1); em.mov_mr(RSP,80,RCX);   // isNeg=1
        em.mov_rm(RAX,RSP,64); em.neg_r(RAX); em.mov_mr(RSP,64,RAX); // value=-value
        em.placeLabel(Lpos);
        int Lloop=em.newLabel(".pi_loop");
        em.placeLabel(Lloop);
        em.mov_rm(RAX,RSP,64);                 // value
        em.mov_ri(RCX,10);
        em.cqo(); em.idiv_r(RCX);              // rax=val/10, rdx=val%10
        em.mov_mr(RSP,64,RAX);                 // value=quotient
        em.add_ri(RDX,48);                     // '0'+digit
        em.mov_rm(RAX,RSP,72); em.sub_ri(RAX,1); em.mov_mr(RSP,72,RAX); // p--
        em.mov_mr8(RAX,0,RDX);                 // *p = digit
        em.mov_rm(RAX,RSP,64); em.test_rr(RAX,RAX);
        em.jnz(Lloop);
        // sign
        em.mov_rm(RAX,RSP,80); em.test_rr(RAX,RAX);
        int Lprint=em.newLabel(".pi_print");
        em.jz(Lprint);
        em.mov_rm(RAX,RSP,72); em.sub_ri(RAX,1); em.mov_mr(RSP,72,RAX);
        em.mov_r8i(RCX,45);                    // '-'
        em.mov_mr8(RAX,0,RCX);
        em.placeLabel(Lprint);
        em.mov_rm(RDX,RSP,72);                 // p (ptr)
        em.lea_mem(RAX,RSP,64);                // end
        em.sub_rr(RAX,RDX);                    // len = end - p
        em.mov_rr(RCX,RDX);                    // ptr
        em.mov_rr(RDX,RAX);                    // len
        em.call(L_print_str);
        em.add_ri(RSP,88);
        em.ret();
    }

    // __getch() -> rax (0..255 byte, or -1 on EOF)
    void emit_getch(){
        em.placeLabel(L_getch);
        em.sub_ri(RSP,56);
        int Lcheck=em.newLabel(".gc_check");
        int Lhave =em.newLabel(".gc_have");
        int Leof  =em.newLabel(".gc_eof");
        em.placeLabel(Lcheck);
        em.mov_rdata(RAX,DAT_INPOS,"inpos");
        em.mov_rdata(RCX,DAT_INLEN,"inlen");
        em.cmp_rr(RAX,RCX);
        em.jl(Lhave);                          // pos < len -> data available
        // refill: read 256 bytes into inbuf -> RAX = bytesRead
        if (targetLinux){
            em.mov_ri(RDI,0);                  // fd = STDIN_FILENO
            em.lea_data(RSI,DAT_INBUF,"inbuf");// buffer
            em.mov_ri(RDX,256);                // count
            em.mov_ri(RAX,0);                  // sys_read  -> RAX = bytesRead
            em.syscallInsn();
        } else if (targetBare){
            // No console input freestanding in v1 (a PS/2 driver is a later rung), so
            // report end-of-input rather than reaching for a Win32 import that cannot
            // exist here. read_int/read_char therefore yield 0.
            em.xor_rr(RAX,RAX);
        } else {
            // ReadFile(GetStdHandle(-10), inbuf, 256, &n, 0)
            em.mov_ri(RCX,(i64t)-10);          // STD_INPUT_HANDLE
            em.call_import(IMP_GetStdHandle,"GetStdHandle");
            em.mov_rr(RCX,RAX);                // handle
            em.lea_data(RDX,DAT_INBUF,"inbuf");// buffer
            em.mov_ri(R8,256);                 // count
            em.lea_mem(R9,RSP,40);             // &bytesRead
            em.xor_rr(RAX,RAX);
            em.mov_mr(RSP,32,RAX);             // overlapped=NULL
            em.mov_mr(RSP,40,RAX);             // bytesRead=0 (clears full qword)
            em.call_import(IMP_ReadFile,"ReadFile");
            em.mov_rm(RAX,RSP,40);             // bytesRead
        }
        em.mov_data_r(DAT_INLEN,RAX,"inlen");  // inlen = n
        em.xor_rr(RAX,RAX);
        em.mov_data_r(DAT_INPOS,RAX,"inpos");  // inpos = 0
        em.mov_rdata(RAX,DAT_INLEN,"inlen"); em.test_rr(RAX,RAX);
        em.jz(Leof);
        em.jmp(Lcheck);
        em.placeLabel(Leof);
        em.mov_ri(RAX,(i64t)-1);
        em.add_ri(RSP,56); em.ret();
        em.placeLabel(Lhave);
        em.mov_rdata(RAX,DAT_INPOS,"inpos");
        em.lea_data(RCX,DAT_INBUF,"inbuf");
        em.add_rr(RCX,RAX);                    // &inbuf[pos]
        em.movzx_rm8(RDX,RCX,0);               // ch
        em.add_ri(RAX,1);
        em.mov_data_r(DAT_INPOS,RAX,"inpos");  // pos++
        em.mov_rr(RAX,RDX);                    // return ch
        em.add_ri(RSP,56); em.ret();
    }

    // __read_char() -> rax  (first non-whitespace char, 0 on EOF)
    void emit_read_char(){
        em.placeLabel(L_read_char);
        em.sub_ri(RSP,40);
        int Lloop=em.newLabel(".rc_loop");
        int Leof =em.newLabel(".rc_eof");
        int Ldone=em.newLabel(".rc_done");
        em.placeLabel(Lloop);
        em.call(L_getch);
        em.cmp_ri(RAX,-1); em.je(Leof);
        em.cmp_ri(RAX,32); em.je(Lloop);
        em.cmp_ri(RAX,10); em.je(Lloop);
        em.cmp_ri(RAX,13); em.je(Lloop);
        em.cmp_ri(RAX,9);  em.je(Lloop);
        em.jmp(Ldone);
        em.placeLabel(Leof);
        em.xor_rr(RAX,RAX);
        em.placeLabel(Ldone);
        em.add_ri(RSP,40); em.ret();
    }

    // __read_int() -> rax  (parse optional sign + decimal digits)
    void emit_read_int(){
        em.placeLabel(L_read_int);
        // frame: [0..32) shadow, [32..40) result, [40..48) sign, [48..56) curchar
        em.sub_ri(RSP,56);
        em.xor_rr(RAX,RAX);
        em.mov_mr(RSP,32,RAX);                 // result=0
        em.mov_mr(RSP,40,RAX);                 // sign=0
        int Lskip=em.newLabel(".ri_skip");
        int Ldone0=em.newLabel(".ri_done0");
        int Lcheckdigit=em.newLabel(".ri_chk");
        int Ldloop=em.newLabel(".ri_dloop");
        int Lend=em.newLabel(".ri_end");
        int Lpos=em.newLabel(".ri_pos");
        em.placeLabel(Lskip);
        em.call(L_getch);
        em.cmp_ri(RAX,-1); em.je(Ldone0);
        em.cmp_ri(RAX,32); em.je(Lskip);
        em.cmp_ri(RAX,10); em.je(Lskip);
        em.cmp_ri(RAX,13); em.je(Lskip);
        em.cmp_ri(RAX,9);  em.je(Lskip);
        em.cmp_ri(RAX,45);                     // '-'
        em.jne(Lcheckdigit);
        em.mov_ri(RCX,1); em.mov_mr(RSP,40,RCX);   // sign=1
        em.call(L_getch);                      // first digit
        em.placeLabel(Lcheckdigit);
        em.placeLabel(Ldloop);
        em.mov_mr(RSP,48,RAX);                 // curchar
        em.mov_rr(RCX,RAX);
        em.cmp_ri(RCX,48); em.jl(Lend);
        em.cmp_ri(RCX,57); em.jg(Lend);
        em.mov_rm(RAX,RSP,32);                 // result
        em.mov_ri(RCX,10); em.imul_rr(RAX,RCX);    // result*10
        em.mov_rm(RCX,RSP,48); em.sub_ri(RCX,48);  // digit
        em.add_rr(RAX,RCX);
        em.mov_mr(RSP,32,RAX);                 // result
        em.call(L_getch);
        em.jmp(Ldloop);
        em.placeLabel(Lend);
        em.mov_rm(RAX,RSP,32);                 // result
        em.mov_rm(RCX,RSP,40);                 // sign
        em.test_rr(RCX,RCX); em.jz(Lpos);
        em.neg_r(RAX);
        em.placeLabel(Lpos);
        em.add_ri(RSP,56); em.ret();
        em.placeLabel(Ldone0);
        em.xor_rr(RAX,RAX);
        em.add_ri(RSP,56); em.ret();
    }

    // __int_to_str(rcx=dest, rdx=value) : write signed decimal + NUL terminator at dest (leaf)
    void emit_int_to_str(){
        em.placeLabel(L_int_to_str);
        // frame: [0..32) digit scratch, [32..40) value, [40..48) p, [48..56) dest, [56..64) isNeg
        em.sub_ri(RSP,64);
        em.mov_mr(RSP,48,RCX);                          // dest
        em.mov_mr(RSP,32,RDX);                          // value
        em.xor_rr(RAX,RAX); em.mov_mr(RSP,56,RAX);      // isNeg=0
        em.lea_mem(RAX,RSP,32); em.mov_mr(RSP,40,RAX);  // p = end of digit scratch (rsp+32)
        em.mov_rm(RAX,RSP,32); em.test_rr(RAX,RAX);
        int Lpos=em.newLabel(".its_pos");
        em.jns(Lpos);
        em.mov_ri(RCX,1); em.mov_mr(RSP,56,RCX);        // isNeg=1
        em.mov_rm(RAX,RSP,32); em.neg_r(RAX); em.mov_mr(RSP,32,RAX);
        em.placeLabel(Lpos);
        int Lloop=em.newLabel(".its_loop");
        em.placeLabel(Lloop);
        // UNSIGNED divide: the value was made positive above, and -INT64_MIN is INT64_MIN
        // again; unsigned 2^63 yields the correct decimal digits.
        // Every other value divides the same way.
        em.mov_rm(RAX,RSP,32); em.mov_ri(RCX,10); em.xor_rr(RDX,RDX); em.div_r(RCX);
        em.mov_mr(RSP,32,RAX);                          // value/=10
        em.add_ri(RDX,48);                              // '0'+digit
        em.mov_rm(RAX,RSP,40); em.sub_ri(RAX,1); em.mov_mr(RSP,40,RAX);  // p--
        em.mov_mr8(RAX,0,RDX);                          // *p = digit
        em.mov_rm(RAX,RSP,32); em.test_rr(RAX,RAX); em.jnz(Lloop);
        em.mov_rm(RAX,RSP,56); em.test_rr(RAX,RAX);     // sign?
        int Lcopy=em.newLabel(".its_copy");
        em.jz(Lcopy);
        em.mov_rm(RAX,RSP,40); em.sub_ri(RAX,1); em.mov_mr(RSP,40,RAX);
        em.mov_r8i(RCX,45); em.mov_mr8(RAX,0,RCX);      // '-'
        em.placeLabel(Lcopy);
        int Lcl=em.newLabel(".its_cl");
        int Ldone=em.newLabel(".its_done");
        em.placeLabel(Lcl);
        em.mov_rm(RAX,RSP,40);                          // src = p
        em.lea_mem(RCX,RSP,32);                         // end
        em.cmp_rr(RAX,RCX); em.jge(Ldone);
        em.movzx_rm8(RDX,RAX,0);                        // ch = *src
        em.mov_rm(RCX,RSP,48);                          // dest
        em.mov_mr8(RCX,0,RDX);                          // *dest = ch
        em.add_ri(RCX,1); em.mov_mr(RSP,48,RCX);        // dest++
        em.mov_rm(RAX,RSP,40); em.add_ri(RAX,1); em.mov_mr(RSP,40,RAX); // src++
        em.jmp(Lcl);
        em.placeLabel(Ldone);
        em.mov_rm(RCX,RSP,48); em.xor_rr(RAX,RAX); em.mov_mr8(RCX,0,RAX); // *dest = 0
        em.add_ri(RSP,64); em.ret();
    }

    // __puts_cstr(rcx=addr) : print a NUL-terminated string (strlen + __print_str)
    void emit_puts_cstr(){
        em.placeLabel(L_puts_cstr);
        em.sub_ri(RSP,40);
        em.mov_mr(RSP,32,RCX);                 // save addr
        em.mov_rr(RAX,RCX);                    // p = addr
        int Llen=em.newLabel(".pc_len");
        int Lend=em.newLabel(".pc_end");
        em.placeLabel(Llen);
        em.movzx_rm8(RDX,RAX,0); em.test_rr(RDX,RDX); em.jz(Lend);
        em.add_ri(RAX,1); em.jmp(Llen);
        em.placeLabel(Lend);
        em.mov_rm(RCX,RSP,32);                 // addr (ptr)
        em.sub_rr(RAX,RCX);                    // len = p - addr
        em.mov_rr(RDX,RAX);                    // len
        em.call(L_print_str);                  // rcx=addr, rdx=len
        em.add_ri(RSP,40); em.ret();
    }

    // __str_to_int(rcx=addr) -> rax : parse a signed decimal from a C-string buffer
    void emit_str_to_int(){
        em.placeLabel(L_str_to_int);
        // frame: [32)=result [40)=sign [48)=cursor
        em.sub_ri(RSP,56);
        em.mov_mr(RSP,48,RCX);                          // cursor = addr
        em.xor_rr(RAX,RAX); em.mov_mr(RSP,32,RAX); em.mov_mr(RSP,40,RAX); // result=0, sign=0
        int Lskip=em.newLabel(".si_skip");
        int Lsign=em.newLabel(".si_sign");
        int Ldloop=em.newLabel(".si_dloop");
        int Lend=em.newLabel(".si_end");
        int Lpos=em.newLabel(".si_pos");
        em.placeLabel(Lskip);
        em.mov_rm(RAX,RSP,48); em.movzx_rm8(RDX,RAX,0);
        em.cmp_ri(RDX,32); em.jne(Lsign);               // skip spaces
        em.mov_rm(RAX,RSP,48); em.add_ri(RAX,1); em.mov_mr(RSP,48,RAX); em.jmp(Lskip);
        em.placeLabel(Lsign);
        em.mov_rm(RAX,RSP,48); em.movzx_rm8(RDX,RAX,0);
        em.cmp_ri(RDX,45); em.jne(Ldloop);              // optional '-'
        em.mov_ri(RCX,1); em.mov_mr(RSP,40,RCX);
        em.mov_rm(RAX,RSP,48); em.add_ri(RAX,1); em.mov_mr(RSP,48,RAX);
        em.placeLabel(Ldloop);
        em.mov_rm(RAX,RSP,48); em.movzx_rm8(RDX,RAX,0);  // ch
        em.cmp_ri(RDX,48); em.jl(Lend);
        em.cmp_ri(RDX,57); em.jg(Lend);
        em.mov_rm(RAX,RSP,32); em.mov_ri(RCX,10); em.imul_rr(RAX,RCX);
        em.sub_ri(RDX,48); em.add_rr(RAX,RDX);
        em.mov_mr(RSP,32,RAX);
        em.mov_rm(RAX,RSP,48); em.add_ri(RAX,1); em.mov_mr(RSP,48,RAX);
        em.jmp(Ldloop);
        em.placeLabel(Lend);
        em.mov_rm(RAX,RSP,32); em.mov_rm(RCX,RSP,40); em.test_rr(RCX,RCX); em.jz(Lpos);
        em.neg_r(RAX);
        em.placeLabel(Lpos);
        em.add_ri(RSP,56); em.ret();
    }

    // __str_copy(rcx=dst, rdx=src) -> rax : copy C-string, return ptr to the NUL in dst (leaf)
    void emit_str_copy(){
        em.placeLabel(L_str_copy);
        int Lcs=em.newLabel(".sc_loop");
        int Lend=em.newLabel(".sc_end");
        em.placeLabel(Lcs);
        em.movzx_rm8(RAX,RDX,0);                         // ch = *src
        em.mov_mr8(RCX,0,RAX);                           // *dst = ch
        em.test_rr(RAX,RAX); em.jz(Lend);
        em.add_ri(RCX,1); em.add_ri(RDX,1); em.jmp(Lcs);
        em.placeLabel(Lend);
        em.mov_rr(RAX,RCX);                              // return ptr to NUL
        em.ret();
    }

    // __memcpy(rcx=dst, rdx=src, r8=n) -> rax=dst  (leaf)
    void emit_memcpy(){
        em.placeLabel(L_memcpy);
        em.mov_rr(R9,RCX);
        int L=em.newLabel(".mc"); int D=em.newLabel(".mcd");
        em.placeLabel(L);
        em.test_rr(R8,R8); em.jz(D);
        em.movzx_rm8(RAX,RDX,0); em.mov_mr8(RCX,0,RAX);
        em.add_ri(RCX,1); em.add_ri(RDX,1); em.sub_ri(R8,1); em.jmp(L);
        em.placeLabel(D); em.mov_rr(RAX,R9); em.ret();
    }
    // __memset(rcx=dst, rdx=val, r8=n) -> rax=dst  (leaf)
    void emit_memset(){
        em.placeLabel(L_memset);
        em.mov_rr(R9,RCX);
        int L=em.newLabel(".ms"); int D=em.newLabel(".msd");
        em.placeLabel(L);
        em.test_rr(R8,R8); em.jz(D);
        em.mov_mr8(RCX,0,RDX);
        em.add_ri(RCX,1); em.sub_ri(R8,1); em.jmp(L);
        em.placeLabel(D); em.mov_rr(RAX,R9); em.ret();
    }
    // __strlen(rcx=s) -> rax=len  (leaf)
    void emit_strlen(){
        em.placeLabel(L_strlen);
        em.mov_rr(RAX,RCX);
        int L=em.newLabel(".sl"); int D=em.newLabel(".sld");
        em.placeLabel(L);
        em.movzx_rm8(RDX,RAX,0); em.test_rr(RDX,RDX); em.jz(D);
        em.add_ri(RAX,1); em.jmp(L);
        em.placeLabel(D); em.sub_rr(RAX,RCX); em.ret();
    }
    // __strcmp(rcx=a, rdx=b) -> rax (0 if equal)  (leaf)
    void emit_strcmp(){
        em.placeLabel(L_strcmp);
        int L=em.newLabel(".sx"); int D=em.newLabel(".sxd");
        em.placeLabel(L);
        em.movzx_rm8(R8,RCX,0); em.movzx_rm8(R9,RDX,0);
        em.mov_rr(RAX,R8); em.sub_rr(RAX,R9);
        em.test_rr(RAX,RAX); em.jnz(D);
        em.test_rr(R8,R8); em.jz(D);
        em.add_ri(RCX,1); em.add_ri(RDX,1); em.jmp(L);
        em.placeLabel(D); em.ret();
    }

    void emit_start(){
        em.placeLabel(L_start);
        if(!funcLabel.count("main")) fail("no main() function");
        if (targetLinux){
            // System V: kernel hands _start a 16-aligned stack (argc at [rsp], argv[] at [rsp+8..], NO return addr).
            // Save the entry rsp into DAT_ARGV so a GetCommandLineA shim can read argc/argv (M4). Must be the
            // FIRST thing -- `call main` below pushes 8 and shifts rsp.
            em.mov_data_r(DAT_ARGV, RSP, "argv");
            // `call main` pushes 8 -> main entry rsp%16==8, matching the genFunc prologue invariant.
            em.call(funcLabel["main"]);
            em.mov_rr(RDI,RAX);                // exit code = main()'s return
            em.mov_ri(RAX,231);               // exit_group (231) -- terminates ALL threads + reports the
                                              // status reliably to the shell ($? via direct exec AND $(...)
                                              // capture); raw sys_exit(60) only reports via $(...) in bash.
            em.syscallInsn();
            return;                           // never returns
        }
        if (targetBare){
            // Freestanding: main() returns to the boot stub, which halts. There is no
            // process to exit and no OS to return a status to.
            em.sub_ri(RSP,40);
            em.call(funcLabel["main"]);
            em.add_ri(RSP,40);
            em.ret();
            return;
        }
        em.sub_ri(RSP,40);
        em.call(funcLabel["main"]);
        em.mov_rr(RCX,RAX);                    // exit code = main()'s return
        em.call_import(IMP_ExitProcess,"ExitProcess");
        em.ret();                              // unreachable
    }

    void run(){
        stampFloats();                // resolve f64 call/var float-ness program-wide (needs all signatures)
        registerImports();
        assignBufferOffsets();
        buildToolRegistry();          // intern tool JSON schemas before strings are emitted
        // pre-create labels so calls can be forward-referenced
        L_start     = em.newLabel("_start");
        L_print_str = em.newLabel("__print_str");
        L_print_int = em.newLabel("__print_int");
        L_getch     = em.newLabel("__getch");
        L_read_char = em.newLabel("__read_char");
        L_read_int  = em.newLabel("__read_int");
        L_int_to_str= em.newLabel("__int_to_str");
        L_puts_cstr = em.newLabel("__puts_cstr");
        L_str_to_int= em.newLabel("__str_to_int");
        L_str_copy  = em.newLabel("__str_copy");
        L_memcpy    = em.newLabel("__memcpy");
        L_memset    = em.newLabel("__memset");
        L_strlen    = em.newLabel("__strlen");
        L_strcmp    = em.newLabel("__strcmp");
        for (auto& f:prog.funcs){ funcLabel[f.name]=em.newLabel(f.name); funcArity[f.name]=(int)f.params.size(); }

        emit_start();
        for (auto& f:prog.funcs) genFunc(f);
        emit_print_str();
        emit_print_int();
        emit_getch();
        emit_read_char();
        emit_read_int();
        emit_int_to_str();
        emit_puts_cstr();
        emit_str_to_int();
        emit_str_copy();
        emit_memcpy();
        emit_memset();
        emit_strlen();
        emit_strcmp();
    }
};

// ---------------------------------------------------------------------
// 6. PE32+ WRITER
// ---------------------------------------------------------------------
static u32 alignUp(u32 v,u32 a){ return (v + a - 1) & ~(a - 1); }

struct PEWriter {
    Program& prog;
    Codegen& cg;
    string iconPath;            // optional .ico embedded as a .rsrc icon resource (opt-in 4th arg)
    PEWriter(Program& p,Codegen& c):prog(p),cg(c){}

    void putLE(vector<u8>& v,u64 val,int n){ for(int k=0;k<n;k++) v.push_back((val>>(8*k))&0xff); }

    // Build a .rsrc section embedding the icons from a .ico file as
    // RT_GROUP_ICON(id 1) + RT_ICON(id 1..N).  Data-entry RVAs use rsrc_rva.
    // Returns an empty vector on any parse problem (caller then skips the icon).
    vector<u8> buildIconRsrc(const vector<u8>& ico, u32 rsrc_rva){
        vector<u8> empty;
        if (ico.size()<6) return empty;
        u16 type = ico[2] | (ico[3]<<8);
        int N    = ico[4] | (ico[5]<<8);
        if (type!=1 || N<1 || N>64) return empty;
        if (ico.size() < (size_t)6 + (size_t)N*16) return empty;
        struct Img { u8 w,h,cc,res; u16 planes,bits; u32 size,off; };
        vector<Img> imgs(N);
        for (int i=0;i<N;i++){
            const u8* e=&ico[6+i*16];
            Img m; m.w=e[0]; m.h=e[1]; m.cc=e[2]; m.res=e[3];
            m.planes=e[4]|(e[5]<<8); m.bits=e[6]|(e[7]<<8);
            m.size=e[8]|(e[9]<<8)|(e[10]<<16)|((u32)e[11]<<24);
            m.off =e[12]|(e[13]<<8)|(e[14]<<16)|((u32)e[15]<<24);
            if ((size_t)m.off+m.size > ico.size()) return empty;
            imgs[i]=m;
        }
        auto a8=[&](u32 x){ return (x+7)&~7u; };
        u32 off_icondir=32;                      // root dir(16)+2 type entries(16) = 32
        u32 sz_icondir=16+8u*N;
        u32 off_grpdir=off_icondir+sz_icondir;
        u32 cur=off_grpdir+(16+8);
        vector<u32> off_icon_lang(N);
        for (int i=0;i<N;i++){ off_icon_lang[i]=cur; cur+=24; }   // lang dir(16)+entry(8)
        u32 off_grp_lang=cur; cur+=24;
        vector<u32> off_icon_de(N);
        for (int i=0;i<N;i++){ off_icon_de[i]=cur; cur+=16; }     // IMAGE_RESOURCE_DATA_ENTRY
        u32 off_grp_de=cur; cur+=16;
        cur=a8(cur);
        vector<u32> off_icon_data(N);
        for (int i=0;i<N;i++){ off_icon_data[i]=cur; cur=a8(cur+imgs[i].size); }
        u32 off_grp_data=cur;
        u32 grp_size=6+14u*N;
        cur+=grp_size; cur=a8(cur);
        vector<u8> r(cur,0);
        auto p16=[&](u32 at,u16 v){ r[at]=v&0xff; r[at+1]=(v>>8)&0xff; };
        auto p32=[&](u32 at,u32 v){ for(int k=0;k<4;k++) r[at+k]=(v>>(8*k))&0xff; };
        // root directory: 2 ID entries (RT_ICON=3 sorts before RT_GROUP_ICON=14)
        p16(12,0); p16(14,2);
        p32(16+0,3);  p32(16+4,0x80000000u|off_icondir);
        p32(24+0,14); p32(24+4,0x80000000u|off_grpdir);
        // RT_ICON type dir: one named-by-id entry per image
        p16(off_icondir+12,0); p16(off_icondir+14,(u16)N);
        for (int i=0;i<N;i++){ u32 e=off_icondir+16+i*8; p32(e+0,(u32)(i+1)); p32(e+4,0x80000000u|off_icon_lang[i]); }
        // RT_GROUP_ICON type dir: one entry (group id 1)
        p16(off_grpdir+12,0); p16(off_grpdir+14,1);
        p32(off_grpdir+16+0,1); p32(off_grpdir+16+4,0x80000000u|off_grp_lang);
        // language dirs -> data entries (no high bit)
        for (int i=0;i<N;i++){ u32 d=off_icon_lang[i]; p16(d+12,0); p16(d+14,1); p32(d+16+0,0x409); p32(d+16+4,off_icon_de[i]); }
        { u32 d=off_grp_lang; p16(d+12,0); p16(d+14,1); p32(d+16+0,0x409); p32(d+16+4,off_grp_de); }
        // data entries: OffsetToData is an image RVA
        for (int i=0;i<N;i++){ u32 d=off_icon_de[i]; p32(d+0,rsrc_rva+off_icon_data[i]); p32(d+4,imgs[i].size); }
        p32(off_grp_de+0,rsrc_rva+off_grp_data); p32(off_grp_de+4,grp_size);
        // icon image bodies
        for (int i=0;i<N;i++) for (u32 k=0;k<imgs[i].size;k++) r[off_icon_data[i]+k]=ico[imgs[i].off+k];
        // GRPICONDIR (like ICONDIR but each entry ends in a 2-byte resource id)
        p16(off_grp_data+0,0); p16(off_grp_data+2,1); p16(off_grp_data+4,(u16)N);
        for (int i=0;i<N;i++){
            u32 g=off_grp_data+6+i*14;
            r[g+0]=imgs[i].w; r[g+1]=imgs[i].h; r[g+2]=imgs[i].cc; r[g+3]=imgs[i].res;
            p16(g+4,imgs[i].planes); p16(g+6,imgs[i].bits); p32(g+8,imgs[i].size); p16(g+12,(u16)(i+1));
        }
        return r;
    }

    void write(const string& path){
        const u32 IMAGE_BASE_LO=0x40000000, IMAGE_BASE_HI=0x1; // 0x140000000
        const u64 IMAGE_BASE = ((u64)IMAGE_BASE_HI<<32)|IMAGE_BASE_LO;
        const u32 SECT_ALIGN=0x1000, FILE_ALIGN=0x200;

        // ----- optional icon resource (.rsrc) : opt-in, leaves the no-icon path identical -----
        vector<u8> ico, rsrc;
        bool hasIcon=false;
        if (!iconPath.empty()){
            FILE* fi=fopen(iconPath.c_str(),"rb");
            if (fi){ fseek(fi,0,SEEK_END); long sz=ftell(fi); fseek(fi,0,SEEK_SET);
                     if(sz>0){ ico.resize((size_t)sz); size_t rd=fread(ico.data(),1,(size_t)sz,fi); ico.resize(rd); } fclose(fi); }
            if (!ico.empty() && !buildIconRsrc(ico,0).empty()) hasIcon=true;
            else warnDiag("anclc: warning: could not embed icon '" + iconPath + "' (ignored)");
        }
        int nSect = hasIcon?5:4;

        // ----- .rdata : string table -----
        vector<u8> rdata;
        vector<u32> strOff(prog.strings.size());
        for (size_t k=0;k<prog.strings.size();k++){
            strOff[k]=(u32)rdata.size();
            for(char ch:prog.strings[k]) rdata.push_back((u8)ch);
            rdata.push_back(0); // NUL terminator (not counted in print length)
        }
        if (rdata.empty()) rdata.push_back(0);

        // ----- .idata : multi-DLL import table (kernel32 + Ws2_32 + user32) -----
        // group the flat import list by DLL in first-appearance order
        vector<string> dllNames; vector<vector<int>> dllFuncs; std::map<string,int> dllPos;
        for (int g=0; g<(int)cg.imports.size(); ++g){
            const string& dn=cg.imports[g].first;
            auto it=dllPos.find(dn); int di;
            if (it==dllPos.end()){ di=(int)dllNames.size(); dllPos[dn]=di; dllNames.push_back(dn); dllFuncs.push_back({}); }
            else di=it->second;
            dllFuncs[di].push_back(g);
        }
        int numDlls=(int)dllNames.size(), numFuncs=(int)cg.imports.size();

        // compute layout offsets within .idata
        u32 off_IDT=0;
        u32 cursor=(u32)((numDlls+1)*20);                     // after IDT (+null descriptor)
        vector<u32> iltOff(numDlls), iatOff(numDlls);
        for (int d=0; d<numDlls; ++d){ iltOff[d]=cursor; cursor += (u32)((dllFuncs[d].size()+1)*8); }
        u32 iatBase=cursor;
        for (int d=0; d<numDlls; ++d){ iatOff[d]=cursor; cursor += (u32)((dllFuncs[d].size()+1)*8); }
        u32 iatBytes=cursor-iatBase;

        u32 namesStart=cursor;
        vector<u8> names; vector<u32> hnOff(numFuncs);
        for (int d=0; d<numDlls; ++d) for (int g : dllFuncs[d]){
            hnOff[g]=namesStart+(u32)names.size();
            names.push_back(0); names.push_back(0);            // hint
            for(char ch:cg.imports[g].second) names.push_back((u8)ch);
            names.push_back(0); if (names.size()&1) names.push_back(0);
        }
        u32 dllNamesStart=namesStart+(u32)names.size();
        vector<u8> dllStr; vector<u32> dllNameOff(numDlls);
        for (int d=0; d<numDlls; ++d){
            dllNameOff[d]=dllNamesStart+(u32)dllStr.size();
            for(char ch:dllNames[d]) dllStr.push_back((u8)ch);
            dllStr.push_back(0); if (dllStr.size()&1) dllStr.push_back(0);
        }
        u32 idataSize=dllNamesStart+(u32)dllStr.size();
        vector<u8> idata(idataSize,0);
        for (size_t k=0;k<names.size();k++)  idata[namesStart+k]=names[k];
        for (size_t k=0;k<dllStr.size();k++) idata[dllNamesStart+k]=dllStr[k];

        // ----- .data size -----
        u32 dataSize=(u32)cg.dataSize;

        // ----- section RVAs -----
        u32 codeSize=(u32)cg.em.code.size();
        u32 text_rva =0x1000;
        u32 rdata_rva=alignUp(text_rva+codeSize,SECT_ALIGN);
        u32 data_rva =alignUp(rdata_rva+(u32)rdata.size(),SECT_ALIGN);
        u32 idata_rva=alignUp(data_rva+dataSize,SECT_ALIGN);
        u32 rsrc_rva=0;
        if (hasIcon){ rsrc_rva=alignUp(idata_rva+idataSize,SECT_ALIGN); rsrc=buildIconRsrc(ico,rsrc_rva); }
        u32 image_size = hasIcon ? alignUp(rsrc_rva+(u32)rsrc.size(),SECT_ALIGN)
                                 : alignUp(idata_rva+idataSize,SECT_ALIGN);

        // fill IDT / ILT / IAT now that idata_rva is known
        auto put32at=[&](vector<u8>& v,u32 at,u32 val){ v[at]=val&0xff; v[at+1]=(val>>8)&0xff; v[at+2]=(val>>16)&0xff; v[at+3]=(val>>24)&0xff; };
        auto put64at=[&](vector<u8>& v,u32 at,u64 val){ for(int k=0;k<8;k++) v[at+k]=(val>>(8*k))&0xff; };
        vector<u32> iatSlotRVA(numFuncs);
        for (int d=0; d<numDlls; ++d){
            u32 idt=off_IDT+(u32)d*20;
            put32at(idata, idt+0,  idata_rva+iltOff[d]);       // OriginalFirstThunk (ILT)
            put32at(idata, idt+12, idata_rva+dllNameOff[d]);   // Name
            put32at(idata, idt+16, idata_rva+iatOff[d]);       // FirstThunk (IAT)
            for (size_t j=0;j<dllFuncs[d].size();++j){
                int g=dllFuncs[d][j];
                put64at(idata, iltOff[d]+(u32)j*8, idata_rva+hnOff[g]);
                put64at(idata, iatOff[d]+(u32)j*8, idata_rva+hnOff[g]);
                iatSlotRVA[g]=idata_rva+iatOff[d]+(u32)j*8;
            }
        }
        u32 idtRVA=idata_rva+off_IDT, idtSize=(u32)((numDlls+1)*20);
        u32 iatDirRVA=idata_rva+iatBase, iatDirSize=iatBytes;

        // ----- resolve code fixups -----
        for (auto& fx:cg.em.fixups){
            u32 pos=(u32)fx.pos;
            i64t disp=0;
            if (fx.kind==0){ // rel32 -> label
                long tp=cg.em.labelPos[fx.target];
                if (tp<0) fail("unresolved label");
                disp=(i64t)tp - (i64t)(pos+4);
            } else if (fx.kind==1){ // rip -> rdata string
                u32 tgt=rdata_rva+strOff[fx.target];
                disp=(i64t)tgt - (i64t)(text_rva+pos+4);
            } else if (fx.kind==2){ // rip -> .data offset
                u32 tgt=data_rva+(u32)fx.target;
                disp=(i64t)tgt - (i64t)(text_rva+pos+4);
            } else if (fx.kind==3){ // rip -> IAT entry (global import index)
                u32 tgt=iatSlotRVA[fx.target];
                disp=(i64t)tgt - (i64t)(text_rva+pos+4);
            }
            int32_t d=(int32_t)disp;
            cg.em.code[pos]=d&0xff; cg.em.code[pos+1]=(d>>8)&0xff; cg.em.code[pos+2]=(d>>16)&0xff; cg.em.code[pos+3]=(d>>24)&0xff;
        }

        // ----- file offsets -----
        u32 hdrSize=alignUp(0x40+4+20+240+nSect*40, FILE_ALIGN);  // 4 sect -> 0x200, 5 (icon) -> 0x400
        u32 text_fp =hdrSize;
        u32 text_raw=alignUp(codeSize,FILE_ALIGN);
        u32 rdata_fp=text_fp+text_raw;
        u32 rdata_raw=alignUp((u32)rdata.size(),FILE_ALIGN);
        u32 data_fp =rdata_fp+rdata_raw;
        u32 data_raw=alignUp(dataSize,FILE_ALIGN);
        u32 idata_fp=data_fp+data_raw;
        u32 idata_raw=alignUp(idataSize,FILE_ALIGN);
        u32 file_size=idata_fp+idata_raw;
        u32 rsrc_fp=0, rsrc_raw=0;
        if (hasIcon){ rsrc_fp=file_size; rsrc_raw=alignUp((u32)rsrc.size(),FILE_ALIGN); file_size=rsrc_fp+rsrc_raw; }

        // ----- assemble image -----
        vector<u8> img(file_size,0);
        auto W8 =[&](u32 at,u8 v){ img[at]=v; };
        auto W16=[&](u32 at,u16 v){ img[at]=v&0xff; img[at+1]=(v>>8)&0xff; };
        auto W32=[&](u32 at,u32 v){ for(int k=0;k<4;k++) img[at+k]=(v>>(8*k))&0xff; };
        auto W64=[&](u32 at,u64 v){ for(int k=0;k<8;k++) img[at+k]=(v>>(8*k))&0xff; };

        // DOS header
        img[0]='M'; img[1]='Z';
        W32(0x3C, 0x40);              // e_lfanew
        u32 pe=0x40;
        img[pe]='P'; img[pe+1]='E'; img[pe+2]=0; img[pe+3]=0;
        u32 fh=pe+4;                  // IMAGE_FILE_HEADER
        W16(fh+0, 0x8664);            // Machine AMD64
        W16(fh+2, (u16)nSect);        // NumberOfSections (4, or 5 with an icon .rsrc)
        W32(fh+4, 0);                 // TimeDateStamp
        W32(fh+8, 0);                 // PointerToSymbolTable
        W32(fh+12,0);                 // NumberOfSymbols
        W16(fh+16,240);               // SizeOfOptionalHeader
        W16(fh+18,0x0022);            // Characteristics: EXECUTABLE | LARGE_ADDRESS_AWARE
        u32 oh=fh+20;                 // optional header (PE32+)
        W16(oh+0, 0x20B);             // Magic PE32+
        W8 (oh+2, 14); W8(oh+3,0);    // linker ver
        W32(oh+4, text_raw);          // SizeOfCode
        W32(oh+8, rdata_raw+data_raw+idata_raw+rsrc_raw); // SizeOfInitializedData
        W32(oh+12,0);                 // SizeOfUninitializedData
        W32(oh+16,text_rva+(u32)(cg.em.labelPos[cg.L_start])); // AddressOfEntryPoint
        W32(oh+20,text_rva);          // BaseOfCode
        W64(oh+24,IMAGE_BASE);        // ImageBase (PE32+ 8 bytes)
        W32(oh+32,SECT_ALIGN);        // SectionAlignment
        W32(oh+36,FILE_ALIGN);        // FileAlignment
        W16(oh+40,6); W16(oh+42,0);   // OS ver
        W16(oh+44,0); W16(oh+46,0);   // image ver
        W16(oh+48,6); W16(oh+50,0);   // subsystem ver
        W32(oh+52,0);                 // Win32VersionValue
        W32(oh+56,image_size);        // SizeOfImage
        W32(oh+60,hdrSize);           // SizeOfHeaders
        W32(oh+64,0);                 // CheckSum
        W16(oh+68, cg.subsystemGui?2:3); // Subsystem: 2=WINDOWS_GUI, 3=WINDOWS_CUI
        W16(oh+70,0x100);             // DllCharacteristics = NX_COMPAT
        // Raised 1 MB -> 16 MB. genExpr recurses once per operator, so a deeply
        // chained expression overflowed the stack DURING CODEGEN: exit 127, no
        // diagnostic, right after "parsed: N funcs". Measured on the self-hosted
        // compiler (same recursion shape): 1480 chained operators compiled, 1520
        // did not. RESERVE is address space, not commit -- costs nothing unused.
        W64(oh+72,0x1000000);         // SizeOfStackReserve = 16 MB
        W64(oh+80,0x1000);            // SizeOfStackCommit
        W64(oh+88,0x100000);          // SizeOfHeapReserve
        W64(oh+96,0x1000);            // SizeOfHeapCommit
        W32(oh+104,0);                // LoaderFlags
        W32(oh+108,16);               // NumberOfRvaAndSizes
        u32 dd=oh+112;                // DataDirectory[16]
        // [1] Import Directory
        W32(dd+1*8+0, idtRVA); W32(dd+1*8+4, idtSize);
        // [12] IAT
        W32(dd+12*8+0, iatDirRVA); W32(dd+12*8+4, iatDirSize);
        // [2] Resource Table (icon), only when present
        if (hasIcon){ W32(dd+2*8+0, rsrc_rva); W32(dd+2*8+4, (u32)rsrc.size()); }

        // section headers
        u32 sh=oh+240;
        auto section=[&](int idx,const char* nm,u32 vsize,u32 rva,u32 rawsz,u32 rawfp,u32 chars){
            u32 base=sh+idx*40;
            for(int k=0;k<8;k++) img[base+k]= (k<(int)strlen(nm))? nm[k]:0;
            W32(base+8, vsize);
            W32(base+12,rva);
            W32(base+16,rawsz);
            W32(base+20,rawfp);
            W32(base+24,0); W32(base+28,0);
            W16(base+32,0); W16(base+34,0);
            W32(base+36,chars);
        };
        section(0,".text", codeSize,        text_rva, text_raw, text_fp,  0x60000020); // CODE|EXEC|READ
        section(1,".rdata",(u32)rdata.size(),rdata_rva,rdata_raw,rdata_fp,0x40000040); // IDATA|READ
        section(2,".data", dataSize,        data_rva, data_raw, data_fp,  0xC0000040); // IDATA|READ|WRITE
        section(3,".idata",idataSize,       idata_rva,idata_raw,idata_fp, 0xC0000040); // IDATA|READ|WRITE
        if (hasIcon)
            section(4,".rsrc", (u32)rsrc.size(), rsrc_rva, rsrc_raw, rsrc_fp, 0x40000040); // IDATA|READ

        // section raw data
        for (size_t k=0;k<cg.em.code.size();k++) img[text_fp+k]=cg.em.code[k];
        for (size_t k=0;k<rdata.size();k++)       img[rdata_fp+k]=rdata[k];
        // .data is zero-initialized (already)
        for (size_t k=0;k<idata.size();k++)       img[idata_fp+k]=idata[k];
        if (hasIcon) for (size_t k=0;k<rsrc.size();k++) img[rsrc_fp+k]=rsrc[k];

        FILE* fo=fopen(path.c_str(),"wb");
        if (!fo) fail("cannot open output '"+path+"'");
        fwrite(img.data(),1,img.size(),fo);
        fclose(fo);
    }
};

// ---------------------------------------------------------------------
// 6b. LINUX x86-64 ELF WRITER  (static, no-PIE, no-libc; --target=linux)
//   Thread C / M0.  A static ET_EXEC: the kernel maps two PT_LOAD segments
//   and jumps to e_entry -- no dynamic linker, no PLT/GOT, no import table.
//   OS access is via the `syscall` instruction (see emit_start/print_str/
//   getch Linux branches), so there are NO kind-3 (IAT) fixups to resolve.
//   vaddr = LOAD_BASE + file_offset everywhere, so each segment trivially
//   satisfies the loader's p_offset%p_align == p_vaddr%p_align rule.
// ---------------------------------------------------------------------
struct ELFWriter {
    Program& prog;
    Codegen& cg;
    ELFWriter(Program& p,Codegen& c):prog(p),cg(c){}

    void write(const string& path){
        const u64 LOAD_BASE = 0x400000;
        const u32 PAGE = 0x1000;
        const int NPH = 2;                         // PT_LOAD x2 (R|X code, R|W data)
        const u32 headers = 64 + NPH*56;           // Ehdr(64) + Phdr(56)*NPH

        // ----- .rdata : string table (identical layout to PEWriter) -----
        vector<u8> rdata;
        vector<u32> strOff(prog.strings.size());
        for (size_t k=0;k<prog.strings.size();k++){
            strOff[k]=(u32)rdata.size();
            for(char ch:prog.strings[k]) rdata.push_back((u8)ch);
            rdata.push_back(0);
        }
        if (rdata.empty()) rdata.push_back(0);

        u32 codeSize = (u32)cg.em.code.size();
        u32 dataSize = (u32)cg.dataSize;

        // ----- file/vaddr layout (contiguous; vaddr = LOAD_BASE + offset) -----
        u32 text_off  = headers;
        u32 rdata_off = text_off + codeSize;
        u32 seg1_end  = rdata_off + (u32)rdata.size();   // end of the R|X segment
        u32 data_off  = alignUp(seg1_end, PAGE);          // R|W segment starts on a fresh page
        // .data is ALWAYS zero-initialized in ANCL (strings/arrays live in .rdata), so we write
        // ZERO .data bytes to the file (p_filesz=0) and let the loader zero-fill from p_memsz --
        // the ELF analogue of the PE writer's SizeOfRawData=0 trick. This keeps ELFs tiny
        // regardless of .data size and is REQUIRED at self-host scale (the compiler's own multi-MB
        // .data would otherwise overflow a fixed output buffer).
        u32 file_size = data_off;
        u64 entry     = LOAD_BASE + text_off + (u32)cg.em.labelPos[cg.L_start];

        // ----- resolve code fixups (kinds 0/1/2; kind 3 has no static-ELF meaning) -----
        for (auto& fx:cg.em.fixups){
            u32 pos=(u32)fx.pos;
            i64t disp=0;
            if (fx.kind==0){                              // rel32 -> label (intra-.text)
                long tp=cg.em.labelPos[fx.target];
                if (tp<0) fail("unresolved label");
                disp=(i64t)tp - (i64t)(pos+4);
            } else if (fx.kind==1){                       // rip -> .rdata string
                disp=(i64t)(rdata_off+strOff[fx.target]) - (i64t)(text_off+pos+4);
            } else if (fx.kind==2){                       // rip -> .data offset
                disp=(i64t)(data_off+(u32)fx.target) - (i64t)(text_off+pos+4);
            } else if (fx.kind==3){                       // rip -> IAT (Windows import): unreachable for valid
                // input -- alloc/free lower to mmap/munmap syscalls and extern "dll" is gated at the call site
                // (M2). This is a defensive net: any kind-3 fixup here means a new import path bypassed the gate.
                fail("internal: a Windows import fixup reached the ELF writer under --target=linux "
                     "(extern/alloc should have been gated or lowered to syscalls) -- please report");
            }
            int32_t d=(int32_t)disp;
            cg.em.code[pos]=d&0xff; cg.em.code[pos+1]=(d>>8)&0xff; cg.em.code[pos+2]=(d>>16)&0xff; cg.em.code[pos+3]=(d>>24)&0xff;
        }

        // ----- assemble image -----
        vector<u8> img(file_size,0);
        auto W16=[&](u32 at,u16 v){ img[at]=v&0xff; img[at+1]=(v>>8)&0xff; };
        auto W32=[&](u32 at,u32 v){ for(int k=0;k<4;k++) img[at+k]=(v>>(8*k))&0xff; };
        auto W64=[&](u32 at,u64 v){ for(int k=0;k<8;k++) img[at+k]=(v>>(8*k))&0xff; };

        // Elf64_Ehdr
        img[0]=0x7F; img[1]='E'; img[2]='L'; img[3]='F';
        img[4]=2;  // EI_CLASS = ELFCLASS64
        img[5]=1;  // EI_DATA  = ELFDATA2LSB
        img[6]=1;  // EI_VERSION = EV_CURRENT
        img[7]=0;  // EI_OSABI = SYSV
        // img[8..15] EI_PAD = 0
        W16(16, 2);          // e_type = ET_EXEC
        W16(18, 62);         // e_machine = EM_X86_64
        W32(20, 1);          // e_version
        W64(24, entry);      // e_entry (absolute vaddr)
        W64(32, 64);         // e_phoff (program headers follow the Ehdr)
        W64(40, 0);          // e_shoff (no section headers)
        W32(48, 0);          // e_flags
        W16(52, 64);         // e_ehsize
        W16(54, 56);         // e_phentsize
        W16(56, NPH);        // e_phnum
        W16(58, 0);          // e_shentsize
        W16(60, 0);          // e_shnum
        W16(62, 0);          // e_shstrndx

        // Phdr[0] : PT_LOAD R|X  (headers + .text + .rdata)
        u32 ph=64;
        W32(ph+0, 1);                 // p_type = PT_LOAD
        W32(ph+4, 5);                 // p_flags = PF_R(4)|PF_X(1)
        W64(ph+8, 0);                 // p_offset
        W64(ph+16, LOAD_BASE);        // p_vaddr
        W64(ph+24, LOAD_BASE);        // p_paddr
        W64(ph+32, seg1_end);         // p_filesz
        W64(ph+40, seg1_end);         // p_memsz
        W64(ph+48, PAGE);             // p_align

        // Phdr[1] : PT_LOAD R|W  (.data, zero-initialized)
        ph=64+56;
        W32(ph+0, 1);                 // p_type = PT_LOAD
        W32(ph+4, 6);                 // p_flags = PF_R(4)|PF_W(2)
        W64(ph+8, data_off);          // p_offset (page-aligned)
        W64(ph+16, LOAD_BASE+data_off);
        W64(ph+24, LOAD_BASE+data_off);
        W64(ph+32, 0);                // p_filesz = 0 : NO .data bytes in the file (loader zero-fills)
        W64(ph+40, dataSize);         // p_memsz  : the zeroed .data lives only in memory
        W64(ph+48, PAGE);             // p_align

        // segment contents
        for (size_t k=0;k<cg.em.code.size();k++) img[text_off+k]=cg.em.code[k];
        for (size_t k=0;k<rdata.size();k++)       img[rdata_off+k]=rdata[k];
        // .data region is already zero-filled

        FILE* fo=fopen(path.c_str(),"wb");
        if (!fo) fail("cannot open output '"+path+"'");
        fwrite(img.data(),1,img.size(),fo);
        fclose(fo);
    }
};

// ---------------------------------------------------------------------
// 6c. LINUX x86-64 DYNAMIC ELF WRITER  (--target=linux-dyn)
//   A dynamically-linked ET_EXEC (PT_INTERP=/lib64/ld-linux-x86-64.so.2,
//   DT_NEEDED=libc.so.6) that resolves a small set of libc symbols
//   (dlopen/dlsym/dlclose/dlerror) through .rela.plt R_X86_64_JUMP_SLOT
//   relocations under DF_BIND_NOW -- ld.so fills the .got.plt at load, and code
//   calls `call [rip+got.plt slot]` (fixup kind 4), mirroring the PE writer's
//   IAT model. NO lazy PLT stubs. The static CPU emitter (ELFWriter,
//   --target=linux) and PEWriter are UNTOUCHED; this is an additive sibling
//   reached only via the new flag (so their fixpoints stay byte-identical).
//   Layout: seg1 R|X = Ehdr+Phdrs+.interp+.hash+.dynsym+.dynstr+.rela.plt+.text
//   +.rdata ; seg2 R|W = .dynamic+.got.plt+.data (the last as bss: memsz>filesz,
//   zero-filled by the loader). Non-PIE, fixed LOAD_BASE=0x400000 so
//   vaddr=LOAD_BASE+file_off => auto page congruence, and kind 1/2 rip fixups
//   use the SAME offset arithmetic as the static writer.
// ---------------------------------------------------------------------
// =====================================================================
//  BareWriter (lever C) -- a FREESTANDING Multiboot 1 kernel image.
//
//  No PE, no ELF, no loader, no libc, no OS: the file IS the kernel. GRUB (or
//  `qemu-system-x86_64 -kernel`) reads the Multiboot header, loads the image at
//  1 MB and jumps to our 32-bit stub in protected mode with paging OFF. The stub
//  installs identity page tables, enables PAE + long mode, loads a flat 64-bit
//  GDT, and far-jumps into the SAME x86-64 code the PE and ELF targets emit.
//
//  Layout (file offset == physical address - LOAD_BASE):
//     0x0000  Multiboot header (address-fields form, so a FLAT binary can boot)
//     0x0020  32-bit entry stub, GDT, GDT pointer, 64-bit entry
//     0x1000  page tables: PML4, PDPT, PD (identity-maps the first 1 GB, 2 MB pages)
//     0x4000  .text (ANCL code), then .rdata (strings)
//     [bss]   .data, then the stack, then the bump heap -- zero-filled via bss_end_addr
// =====================================================================
struct BareWriter {
    Program& prog;
    Codegen& cg;
    BareWriter(Program& p,Codegen& c):prog(p),cg(c){}

    void write(const string& path){
        const u64 LOAD_BASE = 0x100000;          // 1 MB, the conventional multiboot load address
        const u32 PT_OFF    = 0x1000;            // page tables (4 KB aligned)
        // 0x4000 is now a fourth page table -- see the guard page below -- so code starts
        // one page later. Anything that assumes .text begins at 0x4000 must move with it:
        // tools/bare/verify_bare.py and bare_gate.ps1's NEG-INT3 control both did.
        const u32 STACK_PT  = 0x4000;            // PT giving 4 KB granularity around the stack
        const u32 TEXT_OFF  = 0x5000;            // code starts after the tables
        const u32 STACK_SZ  = 0x10000;           // 64 KB kernel stack
        const u32 HEAP_SZ   = 0x100000;          // 1 MB bump heap

        // ----- .rdata : string table (same layout as the PE/ELF writers) -----
        vector<u8> rdata;
        vector<u32> strOff(prog.strings.size());
        for (size_t k=0;k<prog.strings.size();k++){
            strOff[k]=(u32)rdata.size();
            for(char ch:prog.strings[k]) rdata.push_back((u8)ch);
            rdata.push_back(0);
        }
        if (rdata.empty()) rdata.push_back(0);

        u32 codeSize  = (u32)cg.em.code.size();
        u32 dataSz    = (u32)cg.dataSize;
        u32 rdata_off = TEXT_OFF + codeSize;
        u32 file_size = rdata_off + (u32)rdata.size();
        u32 data_off  = alignUp(file_size, 16);              // .bss: not stored in the file
        // A GUARD PAGE SITS BETWEEN .data AND THE STACK, and the stack is page-aligned so
        // that it can. Measured before this existed: 155 frames of ordinary recursion ran
        // off the bottom of the 64 KB stack and killed the machine with NO output at all --
        // it walked down into .data, then .rdata, then .text, corrupting as it went. The
        // page below the stack is now UNMAPPED, so an overflow takes a #PF and lands in the
        // panic handler instead of quietly rewriting the program.
        u32 guard_off = alignUp(data_off + dataSz, 0x1000);
        u32 stack_off = guard_off + 0x1000;
        u32 heap_off  = stack_off + STACK_SZ;
        u32 bss_end   = heap_off + HEAP_SZ;

        u64 stack_top = LOAD_BASE + stack_off + STACK_SZ;    // stack grows DOWN from its top
        u64 heap_base = LOAD_BASE + heap_off;

        // ----- resolve code fixups (flat: every section sits at a known offset) -----
        for (auto& fx:cg.em.fixups){
            u32 pos=(u32)fx.pos;
            i64t disp=0;
            if (fx.kind==0){
                long tp=cg.em.labelPos[fx.target];
                if (tp<0) fail("unresolved label");
                disp=(i64t)tp - (i64t)(pos+4);
            } else if (fx.kind==1){
                disp=(i64t)(rdata_off+strOff[fx.target]) - (i64t)(TEXT_OFF+pos+4);
            } else if (fx.kind==2){
                disp=(i64t)(data_off+(u32)fx.target) - (i64t)(TEXT_OFF+pos+4);
            } else {
                fail("--target=bare: a Windows import fixup reached the image -- there is no OS to import from");
            }
            int32_t d=(int32_t)disp;
            cg.em.code[pos]=d&0xff; cg.em.code[pos+1]=(d>>8)&0xff; cg.em.code[pos+2]=(d>>16)&0xff; cg.em.code[pos+3]=(d>>24)&0xff;
        }

        vector<u8> img(file_size,0);
        auto W32=[&](u32 at,u32 v){ for(int k=0;k<4;k++) img[at+k]=(v>>(8*k))&0xff; };
        auto W64=[&](u32 at,u64 v){ for(int k=0;k<8;k++) img[at+k]=(u8)((v>>(8*k))&0xff); };

        // ----- Multiboot 1 header -----
        // flags bit 16 = "the address fields below are valid", which is what lets a FLAT
        // binary boot; without it the loader would demand an ELF to find the entry point.
        const u32 MB_MAGIC = 0x1BADB002u;
        const u32 MB_FLAGS = 0x00010000u;
        const u32 MB_CHECK = (u32)(0u - (MB_MAGIC + MB_FLAGS));   // magic+flags+checksum == 0 mod 2^32
        u32 stub_off = 0x20;
        W32(0,  MB_MAGIC);
        W32(4,  MB_FLAGS);
        W32(8,  MB_CHECK);
        W32(12, (u32)(LOAD_BASE + 0));            // header_addr
        W32(16, (u32)(LOAD_BASE + 0));            // load_addr
        W32(20, (u32)(LOAD_BASE + file_size));    // load_end_addr
        W32(24, (u32)(LOAD_BASE + bss_end));      // bss_end_addr (loader zero-fills to here)
        W32(28, (u32)(LOAD_BASE + stub_off));     // entry_addr

        // ----- 32-bit entry stub (raw bytes: the emitter only speaks 64-bit) -----
        vector<u8> stub;
        auto B  =[&](std::initializer_list<int> bs){ for(int b:bs) stub.push_back((u8)b); };
        auto D32=[&](u32 v){ for(int k=0;k<4;k++) stub.push_back((u8)((v>>(8*k))&0xff)); };
        auto Q  =[&](u64 v){ for(int k=0;k<8;k++) stub.push_back((u8)((v>>(8*k))&0xff)); };

        u32 pml4 = (u32)(LOAD_BASE + PT_OFF);
        B({0xFA});                                   // cli
        // EBX IS THE MULTIBOOT INFO POINTER AND IT WAS BEING THROWN AWAY. The loader puts
        // it there at entry, and within a few instructions this stub clobbers every GP
        // register -- so the memory map, the command line and the module list were all
        // unreachable, and the kernel's only knowledge of RAM was a heap size the COMPILER
        // had picked. Stash it first, before anything else runs. Still 32-bit flat mode
        // here, and the image sits at a known physical address, so an absolute store works.
        B({0x89,0x1D}); D32((u32)(LOAD_BASE + data_off + Codegen::DAT_MBINFO));  // mov [abs], ebx
        B({0xB8}); D32(pml4);                        // mov eax, PML4
        B({0x0F,0x22,0xD8});                         // mov cr3, eax
        B({0x0F,0x20,0xE0});                         // mov eax, cr4
        // ANCL uses XMM for EVERY f64 operation, so SSE must be armed before any ANCL
        // code runs. It was not: the only CR4 write here was PAE, OSFXSR was never set,
        // and an f64 program compiled with exit 0, booted, printed its label and died at
        // `movq xmm0, rax` -- #UD -> #GP(e=0032) -> #DF -> triple fault, silently, with
        // IDTR still at its reset value. No CPUID guard: long mode IMPLIES SSE2, and a
        // hand-computed conditional branch inside a raw byte table is more risk than it
        // removes.  0x20 PAE | 0x200 OSFXSR | 0x400 OSXMMEXCPT.
        B({0x0D}); D32(0x620);                       // or  eax, CR4.PAE|OSFXSR|OSXMMEXCPT
        B({0x0F,0x22,0xE0});                         // mov cr4, eax
        B({0xB9}); D32(0xC0000080);                  // mov ecx, IA32_EFER
        B({0x0F,0x32});                              // rdmsr
        B({0x0D}); D32(0x100);                       // or  eax, EFER.LME
        B({0x0F,0x30});                              // wrmsr
        B({0x0F,0x20,0xC0});                         // mov eax, cr0
        // CR0.EM (bit 2) must be CLEAR or SSE traps as #UD no matter what CR4 says;
        // CR0.MP (bit 1) pairs with it. Both go in the same write as PG.
        B({0x25}); D32(0xFFFFFFFB);                  // and eax, ~CR0.EM
        B({0x0D}); D32(0x80000002);                  // or  eax, CR0.PG|CR0.MP
        B({0x0F,0x22,0xC0});                         // mov cr0, eax -> long mode is now active
        u32 lgdt_at = (u32)stub.size();
        B({0x0F,0x01,0x15}); D32(0);                 // lgdt [gdt_ptr]           (patched below)
        u32 jmp_at = (u32)stub.size();
        B({0xEA}); D32(0); B({0x08,0x00});           // jmp far 0x08:entry64     (patched below)

        while (stub.size() % 8) stub.push_back(0);
        u32 gdt_rel = (u32)stub.size();              // GDT: null, 64-bit code, data
        Q(0x0000000000000000ull);
        Q(0x00AF9A000000FFFFull);                    // code64: L=1, DPL0, exec/read
        Q(0x00CF92000000FFFFull);                    // data:   RW
        u32 gdtp_rel = (u32)stub.size();
        stub.push_back(23); stub.push_back(0);       // limit = 3*8 - 1
        D32((u32)(LOAD_BASE + stub_off + gdt_rel));  // base

        u32 e64_rel = (u32)stub.size();              // ----- 64-bit entry -----
        B({0x66,0xB8,0x10,0x00});                    // mov ax, 0x10
        B({0x8E,0xD8}); B({0x8E,0xC0}); B({0x8E,0xD0}); B({0x8E,0xE0}); B({0x8E,0xE8});
        B({0x48,0xBC}); Q(stack_top);                // movabs rsp, stack_top
        // clear the VGA text screen (80x25 cells of space, grey on black), otherwise the
        // BIOS text underneath shows through wherever our lines are shorter than it
        B({0x48,0xBF}); Q(0xB8000ull);               // movabs rdi, 0xB8000
        B({0x48,0xB9}); Q(2000ull);                  // movabs rcx, 80*25
        B({0x66,0xB8,0x20,0x07});                    // mov ax, 0x0720  (space, attr 0x07)
        B({0xF3,0x66,0xAB});                         // rep stosw
        B({0x48,0xB8}); Q(heap_base);                // movabs rax, heap_base
        u32 heapfix_at=(u32)stub.size();
        B({0x48,0x89,0x05}); D32(0);                 // mov [rip+disp32], rax    (patched below)
        // ...and the LIMIT, so alloc() can refuse instead of handing out a pointer past
        // the end of the heap. It used to just add and return: no compare, no NULL path,
        // so alloc(4 MB) on a 1 MB heap SUCCEEDED and a store through the result landed
        // in whatever followed. Every other target returns NULL on failure.
        B({0x48,0xB8}); Q(LOAD_BASE + bss_end);      // movabs rax, heap_end
        u32 heapendfix_at=(u32)stub.size();
        B({0x48,0x89,0x05}); D32(0);                 // mov [rip+disp32], rax    (patched below)
        u32 call_at=(u32)stub.size();
        B({0xE8}); D32(0);                           // call _start              (patched below)
        B({0xF4});                                   // hlt
        B({0xEB,0xFE});                              // jmp $  (park the CPU)

        // patch the stub's self-references now that every offset is known
        auto SD32=[&](u32 at,u32 v){ for(int k=0;k<4;k++) stub[at+k]=(u8)((v>>(8*k))&0xff); };
        SD32(lgdt_at+3, (u32)(LOAD_BASE + stub_off + gdtp_rel));
        SD32(jmp_at+1,  (u32)(LOAD_BASE + stub_off + e64_rel));
        {   // RIP-relative store that seeds DAT_HEAP
            i64t next = (i64t)(LOAD_BASE + stub_off + heapfix_at + 7);
            i64t tgt  = (i64t)(LOAD_BASE + data_off + Codegen::DAT_HEAP);
            SD32(heapfix_at+3, (u32)(int32_t)(tgt - next));
        }
        {   // ...and the same for the heap LIMIT slot
            i64t next = (i64t)(LOAD_BASE + stub_off + heapendfix_at + 7);
            i64t tgt  = (i64t)(LOAD_BASE + data_off + Codegen::DAT_HEAPEND);
            SD32(heapendfix_at+3, (u32)(int32_t)(tgt - next));
        }
        {   // call into the ANCL entry point
            i64t next = (i64t)(LOAD_BASE + stub_off + call_at + 5);
            i64t tgt  = (i64t)(LOAD_BASE + TEXT_OFF + (u32)cg.em.labelPos[cg.L_start]);
            SD32(call_at+1, (u32)(int32_t)(tgt - next));
        }
        if (stub_off + stub.size() > PT_OFF) fail("--target=bare: boot stub overflowed into the page tables");
        for (size_t k=0;k<stub.size();k++) img[stub_off+k]=stub[k];

        // ----- identity page tables: first 1 GB via 2 MB pages -----
        W64(PT_OFF,          (u64)(LOAD_BASE + PT_OFF + 0x1000) | 0x03);   // PML4[0] -> PDPT
        W64(PT_OFF + 0x1000, (u64)(LOAD_BASE + PT_OFF + 0x2000) | 0x03);   // PDPT[0] -> PD
        for (u32 i=0;i<512;i++)
            W64(PT_OFF + 0x2000 + i*8, ((u64)i << 21) | 0x83);             // present|rw|PS(2MB)
        // ----- 4 KB granularity for the one 2 MB region holding the guard page -----
        // That region's PD entry stops being a 2 MB page and becomes a pointer to a real
        // page table; every 4 KB page in it is identity-mapped EXCEPT the guard.
        {
            u64 guard_va = LOAD_BASE + guard_off;
            u64 region   = guard_va & ~0x1FFFFFull;         // 2 MB-aligned base
            u32 pdi      = (u32)(region >> 21);
            for (u32 i=0;i<512;i++){
                u64 va = region + (u64)i * 0x1000;
                if (va == guard_va) W64(STACK_PT + i*8, 0);              // NOT PRESENT: the guard
                else                W64(STACK_PT + i*8, va | 0x03);      // present|rw, 4 KB
            }
            W64(PT_OFF + 0x2000 + pdi*8, (u64)(LOAD_BASE + STACK_PT) | 0x03);  // no PS bit
        }

        // ----- code + strings -----
        for (u32 k=0;k<codeSize;k++) img[TEXT_OFF+k]=cg.em.code[k];
        for (size_t k=0;k<rdata.size();k++) img[rdata_off+k]=rdata[k];

        FILE* fo=fopen(path.c_str(),"wb");
        if(!fo) fail("cannot open output "+path);
        fwrite(img.data(),1,img.size(),fo);
        fclose(fo);
        printf("anclc: bare image: entry 0x%llx, text 0x%x, guard 0x%llx, bss_end 0x%llx, stack_top 0x%llx\n",
               (unsigned long long)(LOAD_BASE+stub_off), TEXT_OFF,
               (unsigned long long)(LOAD_BASE+guard_off),
               (unsigned long long)(LOAD_BASE+bss_end), (unsigned long long)stack_top);
    }
};

struct ELFWriterDyn {
    Program& prog;
    Codegen& cg;
    ELFWriterDyn(Program& p,Codegen& c):prog(p),cg(c){}

    void write(const string& path){
        const u64 LOAD_BASE = 0x400000;
        const u32 PAGE = 0x1000;
        const int NPH = 5;                          // PT_PHDR, PT_INTERP, PT_LOAD(R|X), PT_LOAD(R|W), PT_DYNAMIC
        const u32 headers = 64 + NPH*56;

        int D = (int)cg.dynImports.size();

        // distinct sonames (first-seen order) -> one DT_NEEDED each
        vector<string> sonames;
        for (auto& di:cg.dynImports){ bool seen=false; for(auto&s:sonames) if(s==di.first){seen=true;break;} if(!seen) sonames.push_back(di.first); }

        // ----- .dynstr : \0 + sonames + import symbol names -----
        vector<u8> dynstr; dynstr.push_back(0);
        vector<u32> soOff(sonames.size());
        for (size_t k=0;k<sonames.size();k++){ soOff[k]=(u32)dynstr.size(); for(char c:sonames[k]) dynstr.push_back((u8)c); dynstr.push_back(0); }
        vector<u32> symOff(D);
        for (int k=0;k<D;k++){ symOff[k]=(u32)dynstr.size(); for(char c:cg.dynImports[k].second) dynstr.push_back((u8)c); dynstr.push_back(0); }

        int nsym = 1 + D;                            // null symbol + D undefined FUNC symbols

        // ----- .hash (SysV; nbucket=1 -> every name hashes into one chain) -----
        vector<u32> hash;
        hash.push_back(1);                           // nbucket
        hash.push_back((u32)nsym);                   // nchain
        hash.push_back(nsym>1 ? 1u : 0u);            // bucket[0] = first real symbol index (STN_UNDEF if none)
        for (int i=0;i<nsym;i++){                     // chain[]: 1->2->...->(nsym-1)->0 ; chain[0]=0
            if (i==0 || i==nsym-1) hash.push_back(0u);
            else hash.push_back((u32)(i+1));
        }

        // ----- .rdata : string table (identical layout to ELFWriter) -----
        vector<u8> rdata; vector<u32> strOff(prog.strings.size());
        for (size_t k=0;k<prog.strings.size();k++){ strOff[k]=(u32)rdata.size(); for(char c:prog.strings[k]) rdata.push_back((u8)c); rdata.push_back(0); }
        if (rdata.empty()) rdata.push_back(0);

        string interp = "/lib64/ld-linux-x86-64.so.2";
        u32 interpSz = (u32)interp.size()+1;
        u32 codeSize = (u32)cg.em.code.size();
        u32 dataSize = (u32)cg.dataSize;

        // ----- seg1 (R|X) layout: headers,.interp,.hash,.dynsym,.dynstr,.rela.plt,.text,.rdata -----
        u32 interp_off  = headers;
        u32 hash_off    = alignUp(interp_off + interpSz, 8);
        u32 hashBytes   = (u32)hash.size()*4;
        u32 dynsym_off  = alignUp(hash_off + hashBytes, 8);
        u32 dynsymBytes = (u32)nsym*24;
        u32 dynstr_off  = dynsym_off + dynsymBytes;
        u32 relaplt_off = alignUp(dynstr_off + (u32)dynstr.size(), 8);
        u32 relapltBytes= (u32)D*24;
        u32 text_off    = alignUp(relaplt_off + relapltBytes, 16);
        u32 rdata_off   = text_off + codeSize;
        u32 seg1_end    = rdata_off + (u32)rdata.size();

        // ----- seg2 (R|W) : .dynamic + .got.plt (+ .data as bss: memsz>filesz) -----
        u32 dyn_off     = alignUp(seg1_end, PAGE);   // fresh page: R|W must not share a page with the R|X seg
        int nDyn        = (int)sonames.size() + 12;  // NEEDED* + 11 fixed (HASH..FLAGS,BIND_NOW) + DT_NULL
        u32 dynamic_off = dyn_off;
        u32 dynamicBytes= (u32)nDyn*16;
        u32 gotplt_off  = alignUp(dynamic_off + dynamicBytes, 8);
        u32 gotpltBytes = (u32)(3 + D)*8;            // GOT[0]=&_DYNAMIC, GOT[1..2]=0 (reserved), then D slots
        u32 seg2_end    = gotplt_off + gotpltBytes;  // end of file-backed bytes
        u32 data_voff   = seg2_end;                  // .data base (bss) = right after .got.plt in the address space
        u32 seg2_filesz = seg2_end - dyn_off;
        u32 seg2_memsz  = seg2_filesz + dataSize;    // zero-extend for .data
        u32 file_size   = seg2_end;

        // ----- resolve code fixups (kinds 0/1/2 exactly as the static writer; kind 4 -> .got.plt slot) -----
        for (auto& fx:cg.em.fixups){
            u32 pos=(u32)fx.pos; i64t disp=0;
            if      (fx.kind==0){ long tp=cg.em.labelPos[fx.target]; if(tp<0) fail("unresolved label"); disp=(i64t)tp-(i64t)(pos+4); }
            else if (fx.kind==1){ disp=(i64t)(rdata_off+strOff[fx.target]) - (i64t)(text_off+pos+4); }
            else if (fx.kind==2){ disp=(i64t)(data_voff+(u32)fx.target)     - (i64t)(text_off+pos+4); }
            else if (fx.kind==4){ disp=(i64t)(gotplt_off+(u32)(3+fx.target)*8) - (i64t)(text_off+pos+4); }   // call [rip+GOT.PLT slot]
            else if (fx.kind==3){ fail("internal: kind-3 (Win IAT) fixup under --target=linux-dyn (dl* imports use kind 4) -- please report"); }
            int32_t d=(int32_t)disp;
            cg.em.code[pos]=d&0xff; cg.em.code[pos+1]=(d>>8)&0xff; cg.em.code[pos+2]=(d>>16)&0xff; cg.em.code[pos+3]=(d>>24)&0xff;
        }

        // ----- assemble image -----
        vector<u8> img(file_size,0);
        auto W16=[&](u32 at,u16 v){ img[at]=v&0xff; img[at+1]=(v>>8)&0xff; };
        auto W32=[&](u32 at,u32 v){ for(int k=0;k<4;k++) img[at+k]=(v>>(8*k))&0xff; };
        auto W64=[&](u32 at,u64 v){ for(int k=0;k<8;k++) img[at+k]=(v>>(8*k))&0xff; };

        u64 entry = LOAD_BASE + text_off + (u32)cg.em.labelPos[cg.L_start];

        // Elf64_Ehdr
        img[0]=0x7F; img[1]='E'; img[2]='L'; img[3]='F';
        img[4]=2; img[5]=1; img[6]=1; img[7]=0;      // ELFCLASS64, ELFDATA2LSB, EV_CURRENT, SYSV
        W16(16, 2);           // e_type = ET_EXEC
        W16(18, 62);          // e_machine = EM_X86_64
        W32(20, 1);           // e_version
        W64(24, entry);       // e_entry
        W64(32, 64);          // e_phoff
        W64(40, 0);           // e_shoff (no section headers)
        W32(48, 0);           // e_flags
        W16(52, 64);          // e_ehsize
        W16(54, 56);          // e_phentsize
        W16(56, NPH);         // e_phnum
        W16(58, 0); W16(60, 0); W16(62, 0);   // e_shentsize / e_shnum / e_shstrndx

        // Program headers
        auto phdr=[&](int i,u32 type,u32 flags,u64 off,u64 vaddr,u64 filesz,u64 memsz,u64 al){
            u32 ph=64+(u32)i*56;
            W32(ph+0,type); W32(ph+4,flags);
            W64(ph+8,off); W64(ph+16,vaddr); W64(ph+24,vaddr);
            W64(ph+32,filesz); W64(ph+40,memsz); W64(ph+48,al);
        };
        //         type            flags       off          vaddr                   filesz        memsz         align
        phdr(0, 6 /*PT_PHDR*/,    4,          64,          LOAD_BASE+64,           (u64)NPH*56,  (u64)NPH*56,  8);
        phdr(1, 3 /*PT_INTERP*/,  4,          interp_off,  LOAD_BASE+interp_off,   interpSz,     interpSz,     1);
        phdr(2, 1 /*PT_LOAD*/,    5 /*R|X*/,  0,           LOAD_BASE,              seg1_end,     seg1_end,     PAGE);
        phdr(3, 1 /*PT_LOAD*/,    6 /*R|W*/,  dyn_off,     LOAD_BASE+dyn_off,      seg2_filesz,  seg2_memsz,   PAGE);
        phdr(4, 2 /*PT_DYNAMIC*/, 6 /*R|W*/,  dynamic_off, LOAD_BASE+dynamic_off,  dynamicBytes, dynamicBytes, 8);

        // .interp (trailing NUL already zero in img)
        for (u32 k=0;k<interpSz-1;k++) img[interp_off+k]=(u8)interp[k];

        // .hash
        for (size_t k=0;k<hash.size();k++) W32(hash_off+(u32)k*4, hash[k]);

        // .dynsym  (Elf64_Sym: st_name(4) st_info(1) st_other(1) st_shndx(2) st_value(8) st_size(8)); sym[0]=null
        for (int k=0;k<D;k++){
            u32 s=dynsym_off + (u32)(1+k)*24;
            W32(s+0, symOff[k]);                     // st_name -> .dynstr
            img[s+4]=0x12;                           // st_info = (STB_GLOBAL<<4)|STT_FUNC
            img[s+5]=0;                              // st_other
            W16(s+6, 0);                             // st_shndx = SHN_UNDEF
            W64(s+8, 0); W64(s+16, 0);               // st_value / st_size
        }

        // .dynstr
        for (size_t k=0;k<dynstr.size();k++) img[dynstr_off+(u32)k]=dynstr[k];

        // .rela.plt  (Elf64_Rela: r_offset(8) r_info(8) r_addend(8))
        for (int k=0;k<D;k++){
            u32 r=relaplt_off + (u32)k*24;
            u64 gotslot = LOAD_BASE + gotplt_off + (u32)(3+k)*8;
            W64(r+0, gotslot);                                   // r_offset -> the GOT.PLT slot for symbol k
            W64(r+8, ((u64)(u32)(1+k) << 32) | 7ull);            // r_info = (symidx<<32)|R_X86_64_JUMP_SLOT
            W64(r+16, 0);                                        // r_addend
        }

        // .text + .rdata
        for (size_t k=0;k<cg.em.code.size();k++) img[text_off+k]=cg.em.code[k];
        for (size_t k=0;k<rdata.size();k++)       img[rdata_off+k]=rdata[k];

        // .dynamic
        {
            u32 dd=dynamic_off; int i=0;
            auto dput=[&](u64 tag,u64 val){ W64(dd+(u32)i*16, tag); W64(dd+(u32)i*16+8, val); i++; };
            for (size_t k=0;k<sonames.size();k++) dput(1 /*DT_NEEDED*/, soOff[k]);
            dput(4  /*DT_HASH*/,     LOAD_BASE+hash_off);
            dput(5  /*DT_STRTAB*/,   LOAD_BASE+dynstr_off);
            dput(6  /*DT_SYMTAB*/,   LOAD_BASE+dynsym_off);
            dput(10 /*DT_STRSZ*/,    (u64)dynstr.size());
            dput(11 /*DT_SYMENT*/,   24);
            dput(3  /*DT_PLTGOT*/,   LOAD_BASE+gotplt_off);
            dput(2  /*DT_PLTRELSZ*/, (u64)relapltBytes);
            dput(20 /*DT_PLTREL*/,   7 /*DT_RELA*/);
            dput(23 /*DT_JMPREL*/,   LOAD_BASE+relaplt_off);
            dput(24 /*DT_BIND_NOW*/, 0);
            dput(30 /*DT_FLAGS*/,    0x8 /*DF_BIND_NOW*/);
            dput(0  /*DT_NULL*/,     0);
        }

        // .got.plt : GOT[0]=&_DYNAMIC (reserved), GOT[1..2]=0, GOT[3+k]=0 (ld.so fills under BIND_NOW)
        W64(gotplt_off+0, LOAD_BASE+dynamic_off);

        FILE* fo=fopen(path.c_str(),"wb");
        if (!fo) fail("cannot open output '"+path+"'");
        fwrite(img.data(),1,img.size(),fo);
        fclose(fo);
    }
};

// ---------------------------------------------------------------------
// 7. MAIN
// ---------------------------------------------------------------------
static string readFile(const string& p){
    FILE* f=fopen(p.c_str(),"rb");
    if(!f) fail("cannot open input '"+p+"'");
    fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
    string s; s.resize(n>0?n:0);
    if(n>0) { size_t rd=fread(&s[0],1,n,f); s.resize(rd);}
    fclose(f);
    return s;
}

// =====================================================================
//  SC1 - the self-correcting `--fix` pass (mechanical, deterministic).
//  See docs/sc1_scope.md. Two deterministic text pre-passes (run before
//  any parse): F3 ('//' -> '#') and F4 (strip let/var; bool/true/false/
//  f32/float/double -> ANCL). String- and comment-aware. The F1/F2
//  parser-insert loop is added on top of this in increment 2.
// =====================================================================
struct FixRec { int line; string desc; };
static bool scIdent(char c){ return isalnum((unsigned char)c) || c=='_'; }

// F3 + F4 over the raw source; records each change. Never touches the
// inside of string literals or '#' comments.
static string scFixText(const string& src, vector<FixRec>& fixes){
    string out; out.reserve(src.size()+16);
    int line=1; size_t n=src.size();
    for (size_t i=0;i<n;){
        char c=src[i];
        if (c=='\n'){ out.push_back(c); line++; i++; continue; }
        if (c=='"'){                                   // copy a string literal verbatim
            out.push_back(c); i++;
            while(i<n){ char d=src[i]; out.push_back(d); i++;
                        if(d=='\\'&&i<n){ out.push_back(src[i]); i++; continue; }
                        if(d=='"') break; if(d=='\n') line++; }
            continue;
        }
        if (c=='#'){                                   // existing comment: copy to EOL
            while(i<n && src[i]!='\n'){ out.push_back(src[i]); i++; }
            continue;
        }
        if (c=='/' && i+1<n && src[i+1]=='/'){          // F3: // -> #
            out.push_back('#'); i+=2;
            fixes.push_back({line, "'//' comment -> '#'"});
            while(i<n && src[i]!='\n'){ out.push_back(src[i]); i++; }
            continue;
        }
        if (scIdent(c) && (out.empty() || !scIdent(out.back()))){   // F4: whole-word at a boundary
            size_t j=i; while(j<n && scIdent(src[j])) j++;
            string w=src.substr(i,j-i);
            if (w=="let"||w=="var"){                     // strip a C-style declarator
                size_t k=j; while(k<n && (src[k]==' '||src[k]=='\t')) k++;
                if (k>j){ fixes.push_back({line,"stripped '"+w+"' declarator"}); i=k; continue; }
            }
            string sub;
            if (w=="bool") sub="i64";
            else if (w=="true") sub="1";
            else if (w=="false") sub="0";
            else if (w=="f32"||w=="float"||w=="double") sub="f64";
            if (!sub.empty()){ out+=sub; fixes.push_back({line,"'"+w+"' -> '"+sub+"'"}); i=j; continue; }
            out+=w; i=j; continue;                       // ordinary identifier: copy whole word
        }
        out.push_back(c); i++;
    }
    return out;
}

// SC1 F1/F2: the literal text to insert for a missing token kind (nullptr = not auto-insertable).
static const char* scTokText(Tok k){
    switch(k){
        case Tok::Semi:     return ";";
        case Tok::RParen:   return ")";
        case Tok::LParen:   return "(";
        case Tok::RBrace:   return "}";
        case Tok::LBrace:   return "{";
        case Tok::RBracket: return "]";
        case Tok::LBracket: return "[";
        case Tok::Arrow:    return "->";
        case Tok::FatArrow: return "=>";
        case Tok::Colon:    return ":";
        case Tok::Assign:   return "=";
        case Tok::Comma:    return ",";
        default:            return nullptr;
    }
}

// SC1 entry: F3/F4 deterministic pre-passes, THEN the F1/F2 edit->re-parse loop
// (on a missing-token parse error, splice the expected token at the previous
// token's end, then re-parse). Bounded + a no-progress guard = guaranteed halt.
static string scFixSource(const string& src, vector<FixRec>& fixes, const string& path){
    string work = scFixText(src, fixes);          // F3 + F4
    string baseDir = dirOf(path);
    size_t lastOff = (size_t)-1; Tok lastKind = Tok::End;
    for (int guard=0; guard<40; guard++){
        bool ok=false; ParseError err;
        try { Program probe; Parser p(work, probe, baseDir); p.parseProgram(); ok=true; }
        catch (const ParseError& e){ err=e; }
        if (ok) break;
        if (!err.haveExpected) break;                       // not an insertable error -> stop honestly
        const char* ins = scTokText(err.expected);
        if (!ins) break;
        size_t off = err.off; if (off>work.size()) off=work.size();
        if (off==lastOff && err.expected==lastKind) break;  // no-progress guard (e.g. nested-brace cascade)
        lastOff=off; lastKind=err.expected;
        int ln=1; for(size_t z=0; z<off && z<work.size(); z++) if(work[z]=='\n') ln++;
        work.insert(off, string(ins));
        fixes.push_back({ln, string("inserted '")+ins+"' ("+err.msg+")"});
    }
    return work;
}

// =====================================================================
// AST -> op-sequence dump (AI-native brain, --dump-ops).  ADDITIVE: runs
// only under --dump-ops, never on the codegen path -> zero PE/ELF/fixpoint
// impact.  Serializes the parsed AST as a prefix (pre-order) integer stream
// per ai_core/astbrain/OPSEQ_SPEC.md.  Symbols become per-doc indices (never
// spelled); literals become value slots.  Reversible by construction.
// =====================================================================
struct OpDump {
    Program& prog;
    vector<int> ids;
    vector<string> mru;                // user symbols in most-recently-used order (front = most recent)
    vector<string> firstSeen;          // distinct user symbols in FIRST-APPEARANCE order (= NEWSYM consume order)
    OpDump(Program& p):prog(p){}
    enum {
        O_PAD=0, O_BOS=1, O_EOS=2, O_UNK=3,
        O_BLOCK=8, O_PARAMLIST=9, O_PARAM=10, O_TYPE=11, O_ELSE_NONE=12, O_ELSE_SOME=13,
        O_FUNC=16, O_ASSIGN=17, O_IF=18, O_LOOP=19, O_RETURN=20, O_BREAK=21, O_CONTINUE=22,
        O_EXPRSTMT=23, O_SYSCALL=24, O_DECLVAR=25, O_IMPORT=26, O_STRUCT=27, O_EXTERN=28,
        O_INT=40, O_FLOAT=41, O_STR=42, O_VAR=43, O_ADDR=44, O_BINARY=45, O_CALL=46,
        O_OP0=56, O_COUNT0=96, O_COUNTMAX=63, O_LIT0=160, O_LITBIG=255,
        // v1 symbols: builtins get fixed global ids; user symbols are recency-coded.
        O_BUILTIN0=256,         // 256..287 : inline builtins 0..31 (load64/store64/band/alloc/...)
        O_RECENCY0=288,         // 288..351 : user-symbol recency rank 0..63 (0 = most recent)
        O_RECCAP=63,
        O_NEWSYM=352,           // a user symbol not seen before in this doc
        // The SECOND builtin range. 256..287 is full at 31-of-32 and O_RECENCY0 sits
        // hard against it, so growing in place would renumber recency/NEWSYM and
        // invalidate every trained .dna. Builtins 32..63 therefore get ids AFTER the
        // existing vocabulary -- append-only, exactly like extending a tokenizer
        // vocab: every id an old model was trained on keeps its meaning, and the new
        // ids appear only in documents that use the new intrinsics.
        // âš  CONSUMER CONTRACT: the first builtin that lands in this range obliges the
        // op-brain consumers to raise their vocab bound BEFORE any .ops containing it
        // is fed to them -- ai_core/astbrain/complete_cli.ancl, complete_ops.ancl and
        // eval_ops.ancl all classify ids against the 288..352 layout, and a trained
        // .dna's embedding table ends at its trained vocab size.
        O_BUILTIN2=353          // 353..384 : inline builtins 32..63
    };
    // The compiler's inline-builtin set (anclc.cpp scanExprArgs `inl[]`): fixed ids so the brain
    // learns them globally instead of as per-doc symbols.
    int builtinIndex(const string& n){
        static const char* B[]={"load8","load16","load32","load64","store8","store16",
            "store32","store64","shl","shr","band","bor","bxor","read_int","read_char",
            "alloc","free","memcpy","memset","strlen","strcmp",
            "sqrt","ftoi","itof","fbits","ffrombits","syscall","__argv_base",
            // APPEND ONLY -- the position IS the id, so reordering breaks every
            // trained .dna. The table holds 31; entries 0..31 encode as
            // O_BUILTIN0+i (256..287) and entries 32..63 as O_BUILTIN2+(i-32)
            // (353..384) -- see the enum note for why the second range sits AFTER
            // the vocabulary and what the first entry to land there obliges the
            // op-brain consumers to do. Past 64 putSym fails LOUDLY: a silently
            // mis-encoded id is this table's original sin.
            "outb","inb","__mb_info",0};
        for(int i=0;B[i];i++) if(n==B[i]) return i;
        return -1;
    }
    void put(int id){ ids.push_back(id); }
    void putCount(long n){ if(n<0)n=0; if(n>O_COUNTMAX)n=O_COUNTMAX; put(O_COUNT0+(int)n); }
    void putLitInt(long long v){ if(v>=0 && v<(O_LITBIG-O_LIT0)) put(O_LIT0+(int)v); else put(O_LITBIG); }
    // Emit a symbol reference: a builtin -> its fixed id; a user symbol -> recency rank
    // (how many DISTINCT symbols ago it was last used; 0 = the most recent), or NEW_SYM if
    // first seen in this doc. Recency is cross-document-aligned + collapses the huge per-doc
    // symbol space to ~65 learnable slots ("predict a recently-used symbol").
    void putSym(const string& n){
        int bi=builtinIndex(n);
        if(bi>=0){
            if(bi>=64) fail("op-vocab: the builtin table exceeded 64 entries -- extend the id ranges deliberately");
            put(bi<32 ? O_BUILTIN0+bi : O_BUILTIN2+(bi-32));
            return;
        }
        int k=-1;
        for(size_t i=0;i<mru.size();++i){ if(mru[i]==n){ k=(int)i; break; } }
        if(k<0){ put(O_NEWSYM); mru.insert(mru.begin(), n); firstSeen.push_back(n); }
        else { put(O_RECENCY0 + (k>O_RECCAP?O_RECCAP:k)); mru.erase(mru.begin()+k); mru.insert(mru.begin(), n); }
    }
    int opId(char op){
        switch(op){
            case '+':return O_OP0+0; case '-':return O_OP0+1; case '*':return O_OP0+2; case '/':return O_OP0+3; case 'm':return O_OP0+4;
            case 'e':return O_OP0+5; case 'n':return O_OP0+6; case 'l':return O_OP0+7; case 'L':return O_OP0+8; case 'g':return O_OP0+9; case 'G':return O_OP0+10;
            case 'a':return O_OP0+11; case 'o':return O_OP0+12; default:return O_OP0+13;
        }
    }
    int typeCode(const string& t){
        if(t=="i64")return 0; if(t=="i32")return 1; if(t=="f64")return 2; if(t=="ptr")return 3;
        if(t=="buf")return 4; if(t=="str")return 5; if(t=="i8")return 6; if(t=="i16")return 7;
        if(!t.empty()&&t[0]=='*')return 8; return 9;
    }
    void emitType(const string& t){ put(O_TYPE); putCount(typeCode(t)); }
    void emitExpr(const Expr* e){
        if(!e){ put(O_UNK); return; }
        switch(e->kind){
            case NodeKind::Int:    put(O_INT); putLitInt(e->ival); break;
            case NodeKind::Float:  put(O_FLOAT); put(O_LITBIG); break;
            case NodeKind::Str:    put(O_STR); put(O_LITBIG); break;
            case NodeKind::Var:    put(O_VAR); putSym(e->name); break;
            case NodeKind::Addr:   put(O_ADDR); putSym(e->name); break;
            case NodeKind::Binary: put(O_BINARY); put(opId(e->op)); emitExpr(e->lhs.get()); emitExpr(e->rhs.get()); break;
            case NodeKind::Call:   put(O_CALL); putSym(e->name); putCount((long)e->args.size()); for(auto& a:e->args) emitExpr(a.get()); break;
        }
    }
    void emitBlock(const vector<StmtP>& body){ put(O_BLOCK); putCount((long)body.size()); for(auto& s:body) emitStmt(s.get()); }
    void emitStmt(const Stmt* s){
        if(!s){ put(O_UNK); return; }
        switch(s->kind){
            case StKind::Assign:   put(O_ASSIGN); putSym(s->name); emitExpr(s->expr.get()); break;
            case StKind::If:       put(O_IF); emitExpr(s->expr.get()); emitBlock(s->body);
                                   if(s->elseBody.empty()){ put(O_ELSE_NONE); } else { put(O_ELSE_SOME); emitBlock(s->elseBody); } break;
            case StKind::Loop:     put(O_LOOP); emitExpr(s->expr.get()); emitBlock(s->body); break;
            case StKind::Return:   put(O_RETURN); emitExpr(s->expr.get()); break;
            case StKind::Break:    put(O_BREAK); break;
            case StKind::Continue: put(O_CONTINUE); break;
            case StKind::ExprStmt: put(O_EXPRSTMT); emitExpr(s->expr.get()); break;
            case StKind::Syscall:  put(O_SYSCALL); putCount((long)s->sysNo); putCount((long)s->sysArgs.size()); for(auto& a:s->sysArgs) emitExpr(a.get()); break;
        }
    }
    void emitFunc(const Func& f){
        put(O_FUNC); putSym(f.name);
        put(O_PARAMLIST); putCount((long)f.params.size());
        for(auto& p:f.params){ put(O_PARAM); putSym(p.name); emitType(p.type); }
        emitType(f.retType);
        emitBlock(f.body);
    }
    void emitDataVar(const DataVar& d){
        put(O_DECLVAR); putSym(d.name); emitType(d.type);
        if(d.isStr){ put(O_STR); put(O_LITBIG); }
        else if(d.isBuf){ putCount(0); }
        else if(d.isFloat){ put(O_FLOAT); put(O_LITBIG); }
        else { put(O_INT); putLitInt(d.ival); }
    }
    void run(){
        put(O_BOS);
        for(auto& d:prog.data)  emitDataVar(d);
        for(auto& f:prog.funcs) emitFunc(f);
        put(O_EOS);
    }
    void writeText(const string& path, const string& inPath){
        FILE* fo=fopen(path.c_str(),"wb");
        if(!fo){ fprintf(stderr,"--dump-ops: cannot write %s\n",path.c_str()); return; }
        fprintf(fo,"# ANCL op-seq v1  file=%s  ops=%zu  distinct-syms=%zu  (builtins fixed, user syms recency-coded)\n", inPath.c_str(), ids.size(), mru.size());
        // v2: NEWSYM consume-order name list -> a decoder replays the recency MRU to resolve every
        // RECENCY_k / NEWSYM op back to the real identifier (the user's exact names).
        fprintf(fo,"# names:"); for(size_t i=0;i<firstSeen.size();++i) fprintf(fo," %s", firstSeen[i].c_str()); fprintf(fo,"\n");
        for(size_t i=0;i<ids.size();++i) fprintf(fo,"%d%c", ids[i], (((i+1)%32==0)?'\n':' '));
        if(!ids.empty()) fprintf(fo,"\n");
        fclose(fo);
    }
};

int main(int argc,char** argv){
    string inPath, outPath, iconPath;
    bool fixMode=false, fixWrite=false, checkMode=false, targetLinux=false, dumpOps=false, targetLinuxDyn=false, targetBare=false;
    if (argc>=2 && string(argv[1])=="--fix") {              // SC1 self-correcting pass
        fixMode=true;
        if (argc==3) { inPath=argv[2]; }
        else if (argc==4 && string(argv[2])=="--write") { fixWrite=true; inPath=argv[3]; }
        else { fprintf(stderr,"usage: %s --fix [--write] <input.ancl>\n",argv[0]); return 2; }
    } else if (argc==5 && string(argv[1])=="build" && string(argv[3])=="-o") {
        inPath=argv[2];
        outPath=argv[4];
    } else if (argc==3) {
        inPath=argv[1];
        outPath=argv[2];
    } else if (argc==4 || argc==5) {      // trailing args: --check / --target=... / --dump-ops /
        inPath=argv[1];                   // --diagnostics=json / an .ico to embed, in any order.
        outPath=argv[2];                  // argc==4 behaves exactly as it always has.
        for (int ai=3; ai<argc; ai++){
            string a3=argv[ai];
            if (a3=="--check") checkMode=true;
            else if (a3=="--target=linux") targetLinux=true;
            else if (a3=="--target=bare")  targetBare=true;   // lever C: freestanding Multiboot kernel
            else if (a3=="--target=linux-dyn") { targetLinux=true; targetLinuxDyn=true; }   // dynamic ELF (dlopen/dlsym via .rela.plt)
            else if (a3=="--target=windows") targetLinux=false;
            else if (a3=="--dump-ops") dumpOps=true;
            else if (a3=="--diagnostics=json") g_jsonDiag=true;   // A6: structured diagnostics
            else if (a3.rfind("--diagnostics=",0)==0) { fprintf(stderr,"anclc: unknown diagnostics format '%s' (want --diagnostics=json)\n",a3.c_str()); return 2; }
            else iconPath=a3;
        }
    } else {
        fprintf(stderr,"ANCL bootstrap compiler (anclc)\n");
        fprintf(stderr,"usage: %s <input.ancl> <output.exe> [icon.ico]\n",argv[0]);
        fprintf(stderr,"   or: %s build <input.ancl> -o <output.exe>\n",argv[0]);
        fprintf(stderr,"   or: %s --fix [--write] <input.ancl>   (self-correct mechanical errors)\n",argv[0]);
        fprintf(stderr,"   or: %s <input.ancl> <output.exe> --check   (SC4: build an intent-oracle checker)\n",argv[0]);
        return 2;
    }

    // Conditional compilation reads the target, so it must be settled before ANY
    // source text is loaded -- the filter runs inside the read itself.
    g_condTarget = targetBare ? "bare" : (targetLinux ? "linux" : "windows");

    if (fixMode) {                                          // SC1: heal mechanical mistakes, then stop
        g_fixMode=true;
        string src=readFile(inPath);
        vector<FixRec> fixes;
        string fixed=scFixSource(src, fixes, inPath);
        if (fixes.empty()) { printf("anclc --fix: no mechanical fixes needed for %s\n", inPath.c_str()); return 0; }
        printf("anclc --fix: %zu fix(es) %s for %s\n", fixes.size(), fixWrite?"APPLIED":"proposed", inPath.c_str());
        for (auto& fx:fixes) printf("  line %-4d %s\n", fx.line, fx.desc.c_str());
        if (fixWrite) {
            string orig; slurpFile(inPath, orig);
            string bak=inPath+".bak";
            FILE* fb=fopen(bak.c_str(),"wb"); if(fb){ if(!orig.empty()) fwrite(orig.data(),1,orig.size(),fb); fclose(fb); }
            FILE* fo=fopen(inPath.c_str(),"wb"); if(!fo) fail("cannot write '"+inPath+"'");
            if(!fixed.empty()) fwrite(fixed.data(),1,fixed.size(),fo); fclose(fo);
            printf("anclc --fix: healed source written; original saved as %s\n", bak.c_str());
        } else {
            printf("\n  (dry run -- re-run with `--fix --write` to apply; original is kept as %s.bak)\n", inPath.c_str());
        }
        return 0;
    }

    string src=applyCond(readFile(inPath), inPath);

    Program prog;
    Parser parser(src, prog, dirOf(inPath), inPath);   // baseDir for resolving import "..."
    prog.importedFiles.insert(canonPath(inPath));      // never re-enter the root file (matches imp_resolve)
    parser.parseProgram();

    if (dumpOps) {                                   // AI-native brain: emit AST op-sequence, then stop
        OpDump od(prog);
        od.run();
        od.writeText(outPath, inPath);
        printf("anclc --dump-ops: %s -> %s  (%zu ops, %zu distinct syms)\n", inPath.c_str(), outPath.c_str(), od.ids.size(), od.mru.size());
        return 0;
    }

    if (checkMode) parser.synthesizeCheckRunner();   // SC4 --check: (re)define main as the intent runner

    Codegen cg(prog);
    cg.targetBare=targetBare;
    cg.targetLinux=targetLinux;
    cg.targetLinuxDyn=targetLinuxDyn;
    cg.run();

    if (targetBare){
        BareWriter bw(prog,cg);
        bw.write(outPath);
    } else if (targetLinux){
        if (targetLinuxDyn){
            ELFWriterDyn elf(prog,cg);
            elf.write(outPath);
        } else {
            ELFWriter elf(prog,cg);
            elf.write(outPath);
        }
    } else {
        PEWriter pe(prog,cg);
        pe.iconPath=iconPath;
        pe.write(outPath);
    }

    // emit assembly listing alongside the binary (transparency)
    string asmPath=outPath;
    size_t dot=asmPath.find_last_of('.');
    if (dot!=string::npos) asmPath=asmPath.substr(0,dot);
    asmPath+=".asm";
    FILE* fa=fopen(asmPath.c_str(),"wb");
    if (fa){
        fprintf(fa,"; ANCL -> x86-64 listing for %s\n; (generated by anclc; the real binary is direct machine code)\n\n",inPath.c_str());
        fprintf(fa,"BITS 64\nsection .text\n");
        for (auto& l:cg.em.asmLines) fprintf(fa,"%s\n",l.c_str());
        fclose(fa);
    }

    printf("anclc: compiled %s -> %s  (%zu code bytes, %zu funcs, %zu strings)\n",
           inPath.c_str(), outPath.c_str(), cg.em.code.size(), prog.funcs.size(), prog.strings.size());
    printf("anclc: assembly listing -> %s\n", asmPath.c_str());
    return 0;
}
